  @override
  String get maoiMilestone90Description =>
      'สามเดือนทำให้ระบบอารมณ์และพลังงานของสมองมีเวลาอย่างมากในการปรับตัวหลังจาก MAOIอารมณ์ พลังงาน และการคิดที่ชัดเจนจะมีเสถียรภาพในขณะที่สมองจัดการกับสารเคมีเหล่านี้ตามธรรมชาติอีกครั้ง';

