  String get maoiMilestone180Description =>
      'หกเดือนแสดงถึงช่วงเวลาสำคัญของการทำงานของโมโนเอมีนตามธรรมชาติSerotonin, norepinephrine และ dopamine receptor มีจำนวนเป็นปกติวิถีทางฟีนเอทิลเอมีน (PEA) ที่ได้รับผลกระทบจาก MAOI ได้กลับคืนสู่ระดับธรรมชาติ ซึ่งเป็นแง่มุมของการฟื้นตัวที่มักถูกมองข้ามซึ่งมีส่วนช่วยในการฟื้นฟูทางอารมณ์';

