  @override
  String get adderallReferenceDay1 =>
      'การถอนยาบ้า: เกิดอะไรขึ้นตั้งแต่เนิ่นๆ\n\nที่มา: MedlinePlus (หอสมุดแพทยศาสตร์แห่งชาติสหรัฐอเมริกา)\n\nยาบ้าคืออะไร?\nยาบ้าเป็นยากระตุ้นที่มีทั้งสารผิดกฎหมาย (เช่น ความเร็วบนท้องถนน) และยาตามใบสั่งแพทย์ที่ใช้รักษาโรคสมาธิสั้นและอาการเฉียบ (เช่น Adderall และ Vyvanse)พวกมันเพิ่มโดปามีนและนอร์เอพิเนฟรินอย่างรวดเร็ว ซึ่งสามารถสร้างสมาธิ พลังงาน และความอิ่มเอมใจได้อย่างมากเมื่อใช้หนักเป็นประจำ สมองจะปรับตัวตามการกระชากที่เกิดขึ้นซ้ำๆ ดังนั้นการหยุดอาจทำให้อารมณ์ พลังงาน และแรงจูงใจต่ำลงชั่วคราว\n\nอาการถอนทั่วไป\nMedlinePlus แสดงรายการเหล่านี้เป็นเรื่องปกติเมื่อหยุดยาบ้า:\n• มีความอยากยามาก\n• อารมณ์แปรปรวนตั้งแต่ซึมเศร้า ปั่นป่วน ไปจนถึงวิตกกังวล\n• รู้สึกเหนื่อยตลอดทั้งวัน\n• ไม่สามารถมีสมาธิได้\n• ภาพหลอน (การมองเห็นหรือได้ยินสิ่งที่ไม่มีอยู่)\n• ปฏิกิริยาทางกาย เช่น ปวดศีรษะ ปวดเมื่อย เบื่ออาหารเพิ่มขึ้น และนอนหลับไม่ดี\n\nการถอนเงินเป็นอันตรายหรือไม่?\nMedlinePlus ไม่ได้อธิบายว่าการถอนยาบ้านั้นเป็นอันตรายในทางการแพทย์ แต่ตั้งข้อสังเกตว่าอาการรุนแรงอาจจำเป็นต้องได้รับโปรแกรมการรักษาแบบสดๆ และปัญหาทางอารมณ์และอารมณ์จากการใช้ยาบ้า ซึ่งรวมถึงภาวะซึมเศร้า อาจร้ายแรงและต้องการความช่วยเหลือ\n\nการขอความช่วยเหลือ\nMedlinePlus แนะนำให้ติดต่อผู้ให้บริการดูแลสุขภาพของคุณหากคุณหรือคนที่คุณรู้จักติดยาบ้าและต้องการความช่วยเหลือในการหยุดใช้หากคุณมีความคิดเกี่ยวกับการทำร้ายตนเอง ผู้อ่านจะแนะนำให้ไปที่แหล่งข้อมูลในช่วงวิกฤต เช่น 988 หรือ 911';

  @override
  String get adderallReferenceDay3 =>
      'การจัดการถอนยาบ้า: วันที่ 3\n\nที่มา: \"แนวทางทางคลินิกสำหรับการจัดการการถอนและการรักษาผู้ติดยาในพื้นที่ปิด\" องค์การอนามัยโลก (2552) บนชั้นวางหนังสือ NCBI\n\nวันที่ 3 นั่งอยู่ที่ไหน\nแนวทางปฏิบัติของ WHO ระบุว่าอาการถอนยากระตุ้น \'เริ่มภายใน 24 ชั่วโมงหลังจากใช้สารกระตุ้นครั้งสุดท้ายและคงอยู่เป็นเวลา 3-5 วัน\'วันที่สามอยู่ในช่วงเฉียบพลันนี้ โดยทั่วไปจะเป็นวันที่อาการหนักที่สุดก่อนที่อาการจะเริ่มทุเลาลง\n\nอาการ\nสำหรับสารกระตุ้นประเภทแอมเฟตามีน รายการแนวทางปฏิบัติ:\n• ความปั่นป่วนและหงุดหงิด\n• อาการซึมเศร้า\n• การนอนหลับและความอยากอาหารเพิ่มขึ้น\n• ปวดเมื่อยตามกล้ามเนื้อ\nผู้ใช้จำนวนมากอาจมีอาการทางจิต เช่น หวาดระแวง ความคิดไม่เป็นระเบียบ หรือภาพหลอน\n\nส่วนใหญ่เป็นความท้าทายทางจิตวิทยา\nการถอนยากระตุ้นไม่เหมือนกับการถอนแอลกอฮอล์หรือฝิ่นตรงที่ไม่ทำให้อาเจียน อาการสั่น หรืออาการชักปัญหาที่สำคัญคือสภาพจิตใจ อารมณ์ไม่ดี สูญเสียความสุข และความอยากที่เกิดจากสมองที่ขาดสารโดปามีน\n\nแนวทางการบริหารจัดการ\nแนวทางของ WHO แนะนำให้มีการดูแลแบบประคับประคอง:\n• ดื่มน้ำอย่างน้อย 2-3 ลิตรต่อวัน\n• อาหารเสริมวิตามินรวมที่มีวิตามินกลุ่มบีและวิตามินซี\n• ยาตามอาการสำหรับอาการปวดเมื่อยและวิตกกังวล\n• สำหรับความปั่นป่วนอย่างรุนแรง กลยุทธ์ด้านพฤติกรรมก่อน การให้ยาระงับประสาทด้วยยากล่อมประสาทเฉพาะในกรณีที่จำเป็นเท่านั้น\n\nนอกเหนือจากระยะเฉียบพลัน\nหลักเกณฑ์ระบุว่าการถอนเงินที่ยากที่สุดจะใช้เวลาเพียงไม่กี่วัน ตามด้วยระยะเวลาการฟื้นตัวที่น้อยกว่าซึ่งอาจใช้เวลาหนึ่งถึงสองเดือน';

  @override
  String get adderallReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่มี Adderall: สิ่งที่เลวร้ายที่สุดคือการผ่านไป\n\nที่มา: Li & Shoptaw, \"การจัดการทางคลินิกของการถอนยากระตุ้นจิต: การทบทวนหลักฐาน\" Addiction (2023) บน PubMed Central\n\nระยะเฉียบพลันแก้ไขได้\nการทบทวนหลักฐานนี้อธิบายการถอนยากระตุ้นจิตในระยะต่างๆในระยะเฉียบพลัน อาการจะ \"สูงสุดหลังจาก 2-3 วันแรก\" และ \"อาการไม่สบายที่สำคัญจากอาการเหล่านี้มักจะหายไปภายใน 4-7 วัน\"เมื่อสิ้นสุดสัปดาห์แรก ส่วนที่ยากที่สุดของอุบัติเหตุนี้ตามหลังคนส่วนใหญ่ พลังงานและความอยากอาหารเริ่มคงที่ และการนอนหลับเริ่มควบคุม\n\nอะไรจะเกิดขึ้นต่อไป\nการทบทวนระบุว่าอาการที่เหลือส่วนใหญ่ยังคงผ่อนคลายลงในอีกสองถึงสามสัปดาห์ข้างหน้าในวันที่เจ็ด การฟื้นตัวก็ดำเนินไปด้วยดี\n\nสิ่งที่ยังคงอยู่ในวันที่ 7\nอาการทางจิตมักอยู่ได้นานกว่าอุบัติเหตุทางร่างกาย:\n• แรงจูงใจต่ำและสูญเสียความสุข\n• มีสมาธิยาก\n• อารมณ์ที่ยังต่ำกว่าปกติ\nสิ่งเหล่านี้สะท้อนให้เห็นถึงระบบโดปามีนที่กำลังปรับตัว ซึ่งเป็นเรื่องปกติชั่วคราวของการฟื้นตัว\n\nสัญญาณการกู้คืน\nไม่มียาที่ได้รับการรับรองจาก FDA ที่ใช้รักษาอาการถอนยากระตุ้นโดยเฉพาะ ดังนั้นการดูแลแบบประคับประคอง โครงสร้าง การนอนหลับ โภชนาการ และการสนับสนุนด้านจิตใจจึงเป็นแนวทางหลักในระยะนี้';

  @override
  String get adderallReferenceDay14 =>
      'Adderall ปิดสองสัปดาห์: เข้าสู่ระยะการกู้คืนที่ยาวนานขึ้น\n\nที่มา: \"แนวทางทางคลินิกสำหรับการจัดการการถอนและการรักษาผู้ติดยาในพื้นที่ปิด\" องค์การอนามัยโลก (2552) บนชั้นวางหนังสือ NCBI\n\nผ่านระยะเฉียบพลัน\nWHO กำหนดให้การถอนยากระตุ้นที่ยากที่สุดอยู่ที่ประมาณ 3-5 วัน ตามด้วยระยะการฟื้นตัวที่น้อยลงซึ่งกินเวลาประมาณ 1-2 เดือนเมื่อผ่านไปสองสัปดาห์ อุบัติเหตุก็ตามหลังคุณไปแล้ว\n\nระยะการฟื้นตัวที่นานขึ้นจะเป็นอย่างไร\nการนอนหลับที่หนักหน่วง ความปั่นป่วน และอาการปวดกล้ามเนื้อคลี่คลายไปมากแล้วสิ่งที่เหลืออยู่มักจะเบาลง เช่น อารมณ์ต่ำหรือเปลี่ยนแปลง แรงจูงใจลดลง และความอยากอาหารที่เพิ่มขึ้นและดับลงเมื่อระบบการให้รางวัลของสมองปรับใหม่\n\nการนอนหลับและความอยากอาหาร\nการนอนหลับและความอยากอาหารที่เพิ่มขึ้นในระยะเฉียบพลันกำลังเป็นปกติเมื่อการนอนหลับคงที่ อารมณ์ สมาธิ และพลังงานมีแนวโน้มที่จะตามมา\n\nความเสี่ยงในการกำเริบของโรคและสมาธิสั้น\nนี่ยังคงเป็นช่วงเวลาที่มีความเสี่ยงสูง โดยเฉพาะอย่างยิ่งหากอาการ ADHD เดิมกลับมาโดยไม่ใช้ยาแนวปฏิบัติของ WHO เน้นการสนับสนุนด้านจิตใจและทักษะการป้องกันการกลับเป็นซ้ำสำหรับผู้ที่รับประทาน Adderall เพื่อรักษาโรคสมาธิสั้น นี่เป็นช่วงเวลาที่ดีในการหารือเกี่ยวกับกลยุทธ์หรือทางเลือกอื่นที่ไม่กระตุ้นกับแพทย์';

  @override
  String get adderallReferenceDay30 =>
      'Adderall ปิดหนึ่งเดือน: อาการส่วนใหญ่ที่อยู่ข้างหลังคุณ\n\nที่มา: Li & Shoptaw, \"การจัดการทางคลินิกของการถอนยากระตุ้นจิต: การทบทวนหลักฐาน\" Addiction (2023) บน PubMed Central\n\nที่ซึ่งหนึ่งเดือนนั่งอยู่\nการทบทวนพบว่าอาการถอนยาส่วนใหญ่จางหายไปในช่วงสองถึงสามสัปดาห์แรกเมื่อผ่านไป 30 วัน อาการส่วนใหญ่ก็จะผ่อนคลายลง อารมณ์และแรงจูงใจมักจะดีขึ้นกว่าในสัปดาห์แรกมาก\n\nขั้นตอนการกู้คืนในภายหลัง\nตั้งแต่หนึ่งถึงหกเดือน ความทรงจำ การวางแผน การมุ่งเน้น และการตัดสินใจยังคงปรับปรุงอย่างต่อเนื่องเมื่อผ่านไปหนึ่งเดือน ความผิดพลาดก็สิ้นสุดลง และกำไรเหล่านั้นก็กำลังดำเนินการอยู่\n\nอารมณ์และแรงจูงใจ\nการสูญเสียความสุขอย่างสุดซึ้งจากอุบัติเหตุครั้งนี้ได้บรรเทาลงอย่างมากแล้วกิจกรรมที่รู้สึกไม่มีความสุขในสัปดาห์แรกเริ่มรู้สึกคุ้มค่าอีกครั้งเมื่อสัญญาณโดปามีนตามธรรมชาติฟื้นตัวขึ้น\n\nสำหรับผู้ที่เป็นโรคสมาธิสั้น\nถ้า Adderall ถูกกำหนดไว้สำหรับ ADHD อาการพื้นฐานอาจสังเกตได้ชัดเจนขึ้นในขณะนี้การทำงานร่วมกับผู้ให้บริการด้านการแพทย์เกี่ยวกับกลยุทธ์หรือทางเลือกอื่นที่ไม่กระตุ้นเป็นสิ่งสำคัญในระหว่างระยะนี้';

  @override
  String get adderallReferenceDay60 =>
      'Adderall ลดราคาสองเดือน: ระยะการกู้คืนที่ยาวนานขึ้นสิ้นสุดลง\n\nที่มา: \"แนวทางทางคลินิกสำหรับการจัดการการถอนและการรักษาผู้ติดยาในพื้นที่ปิด\" องค์การอนามัยโลก (2552) บนชั้นวางหนังสือ NCBI\n\nที่ซึ่งสองเดือนนั่งอยู่\nWHO อธิบายถึงระยะเวลาการฟื้นตัวที่เบาลงซึ่งกินเวลาประมาณหนึ่งถึงสองเดือนหลังจากอุบัติเหตุครั้งแรกเมื่อครบ 60 วัน คุณอยู่ไกลจากกรอบเวลานั้น และอาการที่ยังคงอยู่จะได้รับการแก้ไขเป็นส่วนใหญ่\n\nสิ่งที่ทำให้ดีขึ้น\nความปั่นป่วน อารมณ์หดหู่ และการนอนหลับและความอยากอาหารที่ถูกรบกวน ตามรายการแนวทางปฏิบัติสำหรับการถอนยากระตุ้นสำหรับคนส่วนใหญ่ ได้รับการตัดสินอย่างมีนัยสำคัญ:\n• อารมณ์ปกติจะคงที่มากขึ้น โดยมีการแปรปรวนของการฟื้นตัวเร็วน้อยลง\n• การนอนหลับและความอยากอาหารเป็นปกติ\n• ระบบการให้รางวัลตอบสนองต่อความสุขในชีวิตประจำวันได้ง่ายขึ้น ไม่ว่าจะเป็นอาหาร การออกกำลังกาย และการเชื่อมต่อ\n\nสัญญาณการกู้คืน\nปริมาณที่สูงขึ้นและการใช้ยานานขึ้นอาจทำให้การฟื้นตัวใช้เวลานานขึ้น ในขณะที่การงดเว้นจะทำให้อารมณ์ แรงจูงใจ และการคิดที่ชัดเจนดำเนินไปตามปกติในช่วงหลายเดือนต่อจากนี้\n\nสุขภาพกาย\nผลกระตุ้นต่ออัตราการเต้นของหัวใจ ความอยากอาหาร และการลดน้ำหนักเมื่อยาหายไปจากชีวิตประจำวัน และบรรเทาความเครียดจากการใช้ยากระตุ้นหัวใจและหลอดเลือด';

  @override
  String get adderallReferenceDay90 =>
      'ส่วนลดสามเดือนจาก Adderall: ผ่านช่วงเวลาที่เลวร้ายที่สุดและยังคงรักษาอยู่\n\nที่มา: Li & Shoptaw, \"การจัดการทางคลินิกของการถอนยากระตุ้นจิต: การทบทวนหลักฐาน\" Addiction (2023) บน PubMed Central\n\nที่ซึ่ง 90 วันนั่งอยู่\nเมื่อถึงสามเดือน อาการเริ่มแรกจะหายไปนานแล้ว ในขณะที่ความจำ การวางแผน การโฟกัส การตัดสินใจ และระบบการให้รางวัลยังคงดีขึ้นอย่างต่อเนื่อง\n\nการคิดและความทรงจำให้ฟื้นตัว\nการทบทวนพบว่าความจำ การวางแผน การมุ่งเน้น และการตัดสินใจด้านความเสี่ยงสามารถปรับปรุงให้ดีขึ้นได้เป็นเวลาหลายเดือนเมื่อครบ 90 วัน สมาธิและความจำยังคงเคลื่อนไปในทิศทางที่ถูกต้องและงดเว้นอย่างต่อเนื่อง\n\nเหตุใดหน้าต่างนี้จึงยังคงมีความสำคัญ\nไม่มียาที่ได้รับการอนุมัติจาก FDA มุ่งเป้าไปที่การถอนยากระตุ้นโดยเฉพาะ ดังนั้น โครงสร้าง การบำบัด การออกกำลังกาย การนอนหลับ และการให้ความช่วยเหลือจึงเป็นเครื่องมือที่ช่วยให้ฟื้นตัวได้ตลอดระยะนี้การสร้างนิสัยเหล่านั้นตั้งแต่ตอนนี้คือสิ่งที่จะนำพาการฟื้นฟูไปข้างหน้า\n\nภาพใหญ่ขึ้น\nสามเดือนเป็นความสำเร็จที่แท้จริง - การยืดเส้นยืดสายทางร่างกายและอารมณ์ที่ยากที่สุดอยู่ข้างหลังคุณ และวิถีจากที่นี่ด้วยการงดเว้นอย่างต่อเนื่องเป็นหนึ่งในการพัฒนาอย่างต่อเนื่อง';

  @override
  String get adderallReferenceDay180 =>
      'Adderall ลดราคาหกเดือน: ผ่านส่วนที่ยากไปแล้ว\n\nที่มา: \"Withdrawal Syndromes\" StatPearls (ชั้นวางหนังสือ NCBI) หอสมุดแพทยศาสตร์แห่งชาติของสหรัฐอเมริกา\n\nStatPearls พูดอะไรเกี่ยวกับสารกระตุ้น\nข้อมูลอ้างอิงทางคลินิกนี้อธิบายถึงการฟื้นตัวของสารกระตุ้นว่าเป็นความผิดพลาดที่ตามมาด้วยการปรับปรุงอย่างค่อยเป็นค่อยไปปัญหาที่พบบ่อย ได้แก่ อาการซึมเศร้า นอนหลับมาก ความหิวเพิ่มขึ้น อารมณ์ไม่ดี และการเคลื่อนไหวและการคิดช้าลงอาการซึมเศร้าอาจคงอยู่นานหลายสัปดาห์ โดยที่อาการจะดีขึ้นเรื่อยๆ นอกเหนือจากนั้น\n\nที่ซึ่งหกเดือนนั่งอยู่\nเมื่ออายุได้หกเดือน คุณจะผ่านทั้งช่วงเฉียบพลันและระยะซึมเศร้าหลายสัปดาห์ที่ StatPearls อธิบายไปแล้วมากการฟื้นตัวอย่างช้าๆ เป็นเรื่องที่ต้องใช้เวลาอย่างมากในการพัฒนา และสำหรับคนส่วนใหญ่ อารมณ์ การนอนหลับ ความอยากอาหาร และแรงจูงใจตามปกติของคนส่วนใหญ่ยังคงมั่นคงและเชื่อถือได้ในตอนนี้\n\nสัญญาณการกู้คืน\nStatPearls อธิบายถึงการฟื้นตัวอย่างค่อยเป็นค่อยไปหลังจากสัปดาห์แรกๆเมื่อถึงหกเดือน อาการเฉียบพลันและระยะซึมเศร้าหลายสัปดาห์จะตามหลังคุณไปมากแล้ว โดยมีอารมณ์ที่มั่นคง การนอนหลับ ความอยากอาหาร และแรงจูงใจ เป็นรูปแบบที่โดดเด่นในขณะนี้\n\nความสัมพันธ์กับ ADHD\nสำหรับผู้ที่รับประทาน Adderall เพื่อรักษาโรคสมาธิสั้น การงดเว้นเป็นเวลา 6 เดือนเป็นจุดที่ดีสำหรับการทบทวนอย่างมีสติกับแพทย์เกี่ยวกับอาการในปัจจุบัน และดูว่าแนวทางที่ไม่กระตุ้น เช่น การออกกำลังกาย การนอนหลับ โครงสร้าง การบำบัด หรือการใช้ยาทางเลือก ตรงตามความต้องการของคุณหรือไม่';

  @override
  String get adderallReferenceDay365 =>
      'Adderall ปิดหนึ่งปี: ฟื้นตัวได้มาก มีกรอบอย่างตรงไปตรงมา\n\nที่มา: Berman และคณะ \"ผลข้างเคียงที่อาจเกิดขึ้นจากการรักษาด้วยแอมเฟตามีนต่อสมองและพฤติกรรม: การทบทวน\" จิตเวชศาสตร์ระดับโมเลกุล (2008) บน PubMed Central\n\nเกี่ยวกับรีวิวนี้\nการทบทวนนี้จะติดตามว่าการสัมผัสยาบ้าในปริมาณมากหรือระยะยาวสามารถส่งผลอย่างไรต่อสมอง และบันทึกการฟื้นตัวที่วัดได้ระหว่างการเลิกบุหรี่\n\nสิ่งที่กล่าวเกี่ยวกับการกู้คืน\nการทบทวนนี้บันทึกการฟื้นตัวของการไหลเวียนของเลือดในสมองและในโปรตีนที่รีไซเคิลโดปามีนหลังจากการเลิกบุหรี่เป็นเวลานานสมองบางส่วนฟื้นตัวได้เร็วกว่าส่วนอื่น แต่ทิศทางโดยรวมก็ชัดเจน: สมองจะฟื้นตัวหลังจากหยุดใช้งาน\n\nการฟื้นฟูระยะยาว\nการทบทวนนี้บันทึกการฟื้นตัวที่วัดได้ของการไหลเวียนของเลือดในสมองและการรีไซเคิลโดปามีนหลังจากการเลิกบุหรี่เป็นเวลานานในหนึ่งปี ระบบสมองเหล่านั้นมีเวลาหนึ่งปีเต็มในการสร้างใหม่\n\nนี่หมายถึงอะไรในหนึ่งปี\nสำหรับคนส่วนใหญ่ — โดยเฉพาะผู้ที่รับประทาน Adderall ในปริมาณที่กำหนด — การหยุดหนึ่งปีหมายความว่าระบบการให้รางวัล ความสนใจ และแรงจูงใจทำงานได้ดีในแต่ละวันการใช้งานหนักหรือนานกว่าอาจใช้เวลานานกว่า แต่การฟื้นตัวจะดำเนินต่อไปความเสี่ยงในการกลับเป็นซ้ำจะต่ำกว่าการฟื้นตัวในช่วงแรกมาก';

  @override
  String get alcoholReferenceDay1 =>
      'จะเกิดอะไรขึ้นกับการนอนหลับของคุณเมื่อคุณหยุดดื่ม?\n\nที่มา: \"แอลกอฮอล์กับสมองที่กำลังหลับ\" (Colrain, Nicholas & Baker), คู่มือวิทยาคลินิก - ตรวจสอบโดยผู้ทรงคุณวุฒิ และจัดทำโดย NIH\n\nสถาปัตยกรรมแอลกอฮอล์และการนอนหลับ\nแอลกอฮอล์ทำให้รู้สึกสงบ จึงช่วยลดระยะเวลาในการนอนหลับและเพิ่มการนอนหลับลึกในช่วงครึ่งแรกของคืนแต่ก็ต้องแลกมาด้วยค่าใช้จ่าย: แอลกอฮอล์ไปกดการนอนหลับ REM (การเคลื่อนไหวของดวงตาอย่างรวดเร็ว) ซึ่งเป็นขั้นตอนการฟื้นฟูที่เกี่ยวข้องกับการรวมความทรงจำและการควบคุมอารมณ์ และการนอนหลับเป็นชิ้น ๆ ในช่วงครึ่งหลังของคืนขณะที่มันถูกเผาผลาญ\n\nคืนแรกงดแอลกอฮอล์\nเนื่องจากแอลกอฮอล์ไประงับการนอนหลับฝัน REM คืนแรกที่ไม่มีแอลกอฮอล์มักจะทำให้ REM ฟื้นตัวขึ้นได้ ความฝันที่ชัดเจนและการนอนหลับที่เบาลงและแตกสลาย ในขณะที่รูปแบบการนอนปกติกลับมาอีกครั้งนี่เป็นเรื่องปกติของการฟื้นฟูชั่วคราว\n\nการกู้คืนเริ่มต้นขึ้น\nเมื่อสมองปรับตัวในช่วงวันและสัปดาห์ต่อมา REM และคุณภาพการนอนหลับโดยรวมจะดีขึ้นการรบกวนการนอนหลับเป็นหนึ่งในอาการที่เกี่ยวข้องกับการถอนตัวอย่างต่อเนื่องมากที่สุด แต่มีแนวโน้มเข้าสู่ภาวะปกติด้วยการงดเว้นอย่างต่อเนื่อง\n\nหมายเหตุเกี่ยวกับการดื่มหนัก\nสำหรับผู้ที่ดื่มหนักหรือดื่มเป็นเวลานานในแต่ละวัน ในช่วง 24 ชั่วโมงแรกอาจทำให้เกิดอาการถอนยาได้ (วิตกกังวล เหงื่อออก ตัวสั่น คลื่นไส้)การถอนตัวอย่างรุนแรงอาจเป็นอันตรายได้ หากคุณดื่มหนักทุกวัน ให้ปรึกษาแพทย์ก่อนที่จะหยุดกะทันหัน';

  @override
  String get alcoholReferenceDay3 =>
      'ระยะเฉียบพลันและการฟื้นตัวตั้งแต่เนิ่นๆ\n\nที่มา: \"การถอนแอลกอฮอล์\" StatPearls - ตรวจสอบโดยผู้ทรงคุณวุฒิ หอสมุดแพทยศาสตร์แห่งชาติ NIH\n\n24–72 ชั่วโมงแรก\nเอกสารของ StatPearls ระบุว่าอาการถอนยาจะเกิดขึ้นภายในไม่กี่ชั่วโมงหลังการดื่มครั้งสุดท้าย เช่น อาการสั่น นอนไม่หลับ กระสับกระส่าย เหงื่อออก อัตราการเต้นของหัวใจเพิ่มขึ้น และความดันโลหิต และอาการดังกล่าวมักเกิดขึ้นสูงสุดประมาณ 72 ชั่วโมงคนส่วนใหญ่จะผ่านช่วงที่เลวร้ายที่สุดของระยะเฉียบพลันภายในสิ้นวันที่สามการถอนตัวอย่างรุนแรง (อาการชักหรืออาการเพ้อสั่น ซึ่ง StatPearls บันทึกไว้สามารถเกิดขึ้นได้ทุกจุดภายใน 3 ถึง 5 วันหลังจากหยุดหรือลดปริมาณลง) ถือเป็นเหตุฉุกเฉินทางการแพทย์: ผู้ดื่มหนักในแต่ละวันไม่ควรหยุดกะทันหันโดยไม่ได้รับคำแนะนำจากแพทย์\n\nความอยากมาในคลื่น\nความอยากมักจะรุนแรงขึ้นในช่วงสองสามวันแรก แต่ความอยากของแต่ละคนจะอยู่ได้ไม่นาน ซึ่งมักจะหายไปภายในไม่กี่นาทีการตระหนักว่าคลื่นแต่ละลูกสงบลงเองทำให้ขี่ออกไปได้ง่ายขึ้น\n\nการฟื้นฟูความชุ่มชื้น\nแอลกอฮอล์ไปยับยั้งฮอร์โมนแอนตี้ไดยูเรติก (ADH) ทำให้ไตขับน้ำออกมามากขึ้น และทำให้ผู้ที่ดื่มเป็นประจำขาดน้ำอย่างเรื้อรังเมื่อหยุดดื่ม ผลขับปัสสาวะจะสิ้นสุดลงและความสมดุลของของเหลวจะเริ่มฟื้นตัวในช่วงสองสามวันแรก ซึ่งมักสังเกตเห็นว่ามีผิวที่ชัดเจนขึ้นและมีพลังงานคงที่มากขึ้น\n\nจิตใจและการนอนหลับเริ่มสงบลง\nเมื่อระยะเฉียบพลันผ่านไป เคมีในสมองที่ทำให้แอลกอฮอล์หยุดชะงัก (GABA และกลูตาเมต) จะเริ่มปรับสมดุลความชัดเจนทางจิตดีขึ้น และการนอนหลับ ซึ่งกระจัดกระจายอย่างรุนแรงในระหว่างการถอนตัวเร็ว เริ่มมีแนวโน้มไปสู่คุณภาพที่ดีขึ้นในช่วงสัปดาห์แรก';

  @override
  String get alcoholReferenceDay7 =>
      'ระบบภูมิคุ้มกันฟื้นตัวได้อย่างไร\n\nที่มา: \"แอลกอฮอล์และระบบภูมิคุ้มกัน\" (Sarkar, Jung & Wang), การวิจัยแอลกอฮอล์: บทวิจารณ์ปัจจุบัน - ตรวจสอบโดยผู้ทรงคุณวุฒิ และจัดทำโดย NIH\n\nแอลกอฮอล์ทำให้ภูมิคุ้มกันอ่อนแอลงอย่างไร\nแอลกอฮอล์ทำให้ระบบภูมิคุ้มกันอ่อนแอลงได้หลายวิธีแม้แต่การดื่มหนักเพียงครั้งเดียวก็สามารถลดความสามารถในการต่อสู้กับการติดเชื้อได้นานถึง 24 ชั่วโมงการใช้ในระยะยาวจะช่วยลดเซลล์เม็ดเลือดขาว รบกวนสัญญาณภูมิคุ้มกัน และทำลายการป้องกันของลำไส้และปอด เพิ่มความเสี่ยงของการติดเชื้อและทำให้บาดแผลหายช้า\n\nการลบคำสบประมาท\nผลกระทบหลายอย่างจะดีขึ้นเมื่อแอลกอฮอล์หมดไปเซลล์เม็ดเลือดขาวและการส่งสัญญาณภูมิคุ้มกันเริ่มฟื้นตัว ในขณะที่การป้องกันลำไส้และทางเดินหายใจเริ่มซ่อมแซมภายในสัปดาห์แรก ระบบภูมิคุ้มกันของคุณจะไม่ถูกทำลายลงทุกวันอีกต่อไป และความต้านทานต่อการติดเชื้อทั่วไปก็เริ่มดีขึ้น\n\nกระบวนการที่ค่อยเป็นค่อยไป\nการฟื้นฟูภูมิคุ้มกันโดยสมบูรณ์จะใช้เวลานานกว่าหนึ่งสัปดาห์ และระดับของการซ่อมแซมขึ้นอยู่กับว่าการดื่มหนักและยาวนานเพียงใด แต่การงดแอลกอฮอล์ในสัปดาห์แรกคือจุดเริ่มต้นของการสร้างใหม่';

  @override
  String get alcoholReferenceDay14 =>
      'การฟื้นฟูสมองตั้งแต่เนิ่นๆ ในการเลิกบุหรี่\n\nที่มา: Bartsch AJ และคณะ \"อาการของการฟื้นฟูสมองในระยะเริ่มแรกที่เกี่ยวข้องกับการเลิกเป็นโรคพิษสุราเรื้อรัง\" Brain (2007) - ตรวจสอบโดยผู้ทรงคุณวุฒิ\n\nการวัดการฟื้นตัว\nการศึกษานี้ใช้เครื่อง MRI เพื่อติดตามผู้ที่เพิ่งล้างพิษจากการติดแอลกอฮอล์ในช่วงสัปดาห์แรกของการงดเว้น โดยเปรียบเทียบกับกลุ่มควบคุมที่ดีต่อสุขภาพมันช่วยให้สมองสร้างร่างกายขึ้นมาใหม่เมื่อหยุดดื่มแล้ว\n\nปริมาณสมองรีบาวด์\nการใช้แอลกอฮอล์เป็นประจำจะทำให้สมองหดตัว ส่วนหนึ่งเป็นผลมาจากการลดขนาดเซลล์แบบย้อนกลับได้ ไม่ใช่แค่การสูญเสียเซลล์อย่างถาวรด้วยการงดเว้น นักวิจัยวัดปริมาณสมองที่เพิ่มขึ้นโดยเฉลี่ยเกือบ 2% โดยเน้นไปที่สมองน้อย สมองส่วนกลาง โพรงสมอง และบริเวณหน้าผากการงอกใหม่ส่วนใหญ่เกิดขึ้นเร็วในช่วงสองสามสัปดาห์แรกโดยงดแอลกอฮอล์\n\nสมองน้อยและความสนใจ\nการฟื้นตัวมีความชัดเจนเป็นพิเศษในบริเวณสมองที่ใช้เพื่อการเคลื่อนไหวและความสนใจเครื่องหมายของสุขภาพเซลล์สมองเพิ่มขึ้นควบคู่ไปกับการปรับปรุงความสนใจที่วัดได้ ดังนั้นการรักษาทางกายภาพจึงมาพร้อมกับการคิดอย่างแท้จริง\n\nรองพื้น ไม่ใช่จุดจบ\nการทำงานระดับสูง เช่น การใช้เหตุผลที่ซับซ้อน จะค่อยๆ ฟื้นตัวมากขึ้น แต่ในช่วงสองสัปดาห์แรกพบว่าสมองเริ่มฟื้นตัวอย่างรวดเร็วเมื่อกำจัดแอลกอฮอล์ออกไป';

  @override
  String get alcoholReferenceDay30 =>
      'ความดันโลหิตลดลงเมื่อคุณงดแอลกอฮอล์\n\nที่มา: Roerecke และคณะ \"ผลของการลดการบริโภคเครื่องดื่มแอลกอฮอล์ต่อความดันโลหิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Lancet Public Health (2017) - ตรวจสอบโดยผู้ทรงคุณวุฒิ\n\nหลักฐาน\nการวิเคราะห์เมตานี้รวบรวมการทดลองแบบสุ่ม 36 รายการ (ผู้เข้าร่วมประมาณ 2,865 คน) เพื่อทดสอบว่าจะเกิดอะไรขึ้นกับความดันโลหิตเมื่อผู้คนดื่มน้อยลงพบผลลัพธ์ที่ชัดเจนและขึ้นอยู่กับขนาดยา ยิ่งมีคนลดความดันโลหิตลงมากเท่าไร\n\nผลกระทบใหญ่แค่ไหน?\nผู้ที่ดื่มสองแก้วหรือน้อยกว่าต่อวันพบว่าไม่มีการเปลี่ยนแปลงความดันโลหิตอย่างมีนัยสำคัญจากการลดปริมาณลงผู้ที่ดื่มเครื่องดื่มตั้งแต่ 6 แก้วขึ้นไปต่อวันจะลดการบริโภคลงประมาณครึ่งหนึ่ง โดยที่ความดันโลหิตซิสโตลิกลดลงประมาณ 5.5 มิลลิเมตรปรอท และความดันโลหิตล่างโดยเฉลี่ยประมาณ 4.0 มิลลิเมตรปรอทการลดขนาดนั้นมีความหมายทางคลินิก เทียบได้กับยาลดความดันโลหิตบางชนิด และเพียงพอที่จะลดความเสี่ยงต่อโรคหลอดเลือดสมองและโรคหัวใจในระยะยาวได้\n\nทำไมหนึ่งเดือนจึงมีความสำคัญ\nแอลกอฮอล์ทำให้ความดันโลหิตเพิ่มขึ้นโดยกระตุ้นการตอบสนองต่อความเครียด เพิ่มคอร์ติซอล และทำให้หลอดเลือดแข็งตัวการทดลองในการทบทวนนี้แสดงให้เห็นว่าคุณประโยชน์จะเกิดขึ้นในช่วงหลายสัปดาห์ของการลดลงอย่างต่อเนื่อง ดังนั้น เมื่องดเว้นประมาณหนึ่งเดือน ความดันโลหิตของผู้ที่ดื่มหนักก็จะมีเวลาปรับตัวไปสู่ระดับที่ดีต่อสุขภาพมากขึ้น\n\nผลกระทบจากเกณฑ์\nการทบทวนพบเกณฑ์ที่ชัดเจน: ประโยชน์มุ่งเน้นไปที่ผู้ที่ดื่มมากกว่าสองแก้วต่อวัน และจะเพิ่มมากขึ้นเรื่อยๆ เมื่อดื่มครั้งก่อนหากคุณเป็นคนที่ดื่มน้อย อย่าคาดหวังว่าจะได้รับประโยชน์จากความดันโลหิตโดยเฉพาะเจาะจงนี้ แต่ผู้ที่ดื่มหนักกว่าจะได้รับผลตอบแทนที่แท้จริงและวัดผลได้จากการหยุดดื่ม';

  @override
  String get alcoholReferenceDay60 =>
      'การฟื้นฟูตับหลังจากที่คุณหยุดดื่ม\n\nที่มา: สถาบันแห่งชาติว่าด้วยการใช้แอลกอฮอล์ในทางที่ผิดและโรคพิษสุราเรื้อรัง (NIAAA), \"ผลกระทบของแอลกอฮอล์ต่อร่างกาย\"\n\nแอลกอฮอล์ทำลายตับอย่างไร\nตับประมวลผลแอลกอฮอล์ส่วนใหญ่ที่คุณดื่ม และได้รับความเสียหายหนักNIAAA อธิบายถึงการลุกลามของอาการบาดเจ็บที่ตับจากแอลกอฮอล์ โดยเริ่มจากไขมันสะสมในตับ (ไขมันสะสมในเซลล์ตับ) อาจลุกลามไปสู่โรคตับอักเสบจากแอลกอฮอล์ (การอักเสบ) และเมื่อใช้หนักเป็นเวลานานจนเกิดภาวะพังผืดและโรคตับแข็ง (แผลเป็น)\n\nระยะแรกสามารถย้อนกลับได้\nจุดสำคัญคือตับมีการฟื้นฟูอย่างมาก และความเสียหายในระยะเริ่มแรกสามารถดีขึ้นได้เมื่อหยุดดื่มโดยเฉพาะภาวะไขมันพอกตับมักจะหายไปได้ด้วยการงดเว้นอย่างต่อเนื่องเมื่อปราศจากแอลกอฮอล์ประมาณสองเดือน ตับจะมีเวลาจริงในการล้างไขมันที่สะสม บรรเทาอาการอักเสบ และฟื้นฟูการทำงานที่ดีต่อสุขภาพ ซึ่งโดยทั่วไปจะสะท้อนให้เห็นในระดับเอนไซม์ตับที่ลดลง (ALT และ AST)\n\nเกินตับ\nNIAAA ตั้งข้อสังเกตว่าแอลกอฮอล์ยังทำให้หัวใจ ตับอ่อน และระบบภูมิคุ้มกันเกิดความเครียดอีกด้วยการให้ร่างกายหยุดพักจากแอลกอฮอล์อย่างต่อเนื่องจะช่วยให้ระบบเหล่านี้ฟื้นตัวได้เช่นกัน ซึ่งส่งผลให้มีพลังงานคงที่มากขึ้นและสุขภาพโดยรวมดีขึ้นที่หลายคนสังเกตเห็นในระยะนี้';

  @override
  String get alcoholReferenceDay90 =>
      'การคิดและความทรงจำหลังจากมีสติสามเดือน\n\nที่มา: การทบทวนอย่างเป็นระบบของการฟื้นตัวของระบบประสาทวิทยาหลังจากการเลิกดื่มแอลกอฮอล์ (PubMed Central, 2024) - ทบทวนโดยผู้ทรงคุณวุฒิ\n\nสิ่งที่แสดงหลักฐาน\nการทบทวนนี้รวมการศึกษาที่ติดตามการฟื้นตัวของความคิดและความทรงจำหลังจากที่คนหยุดดื่มทักษะส่วนใหญ่จะเข้าสู่ภาวะปกติภายในเวลาประมาณหกถึงสิบสองเดือน และบางส่วนจะดีขึ้นเร็วขึ้น\n\nอะไรจะปรับปรุงก่อน\nความสามารถเฉพาะสองอย่างโดดเด่นจากการฟื้นตัวเร็วกว่าที่เหลือ: ความเร็วในการประมวลผลขั้นพื้นฐาน (จากการตรวจสอบพบว่าโดยทั่วไปจะฟื้นตัวได้ประมาณหนึ่งเดือน แม้ว่าความแม่นยำในงานที่ซับซ้อนจะล้าหลังก็ตาม) และการอัปเดตหน่วยความจำในการทำงานเมื่อผ่านไปประมาณสามเดือน หลายๆ คนก็สังเกตเห็นความเปลี่ยนแปลงเหล่านี้แล้ว\n\nสิ่งที่ใช้เวลานานกว่า\nความสนใจ การวางแผน การตัดสินใจ การควบคุมแรงกระตุ้น การรับรู้ และความทรงจำ มีการปรับปรุงอย่างต่อเนื่องตลอดกรอบเวลาการกู้คืนหกถึงสิบสองเดือน\n\nสิ่งที่มีอิทธิพลต่อการฟื้นตัว\nบันทึกการทบทวนการฟื้นตัวนั้นขึ้นอยู่กับปัจจัยต่างๆ เช่น อายุ สถานะการสูบบุหรี่ และความสามารถก่อนเกิดโรค แต่ที่น่ายินดีคือปริมาณที่เมาทั้งหมดไม่สอดคล้องกันการฟื้นตัวเป็นวิถีที่คาดหวัง\n\nทำไมมันถึงสำคัญ\nการคิดที่ชัดเจนขึ้นคือการฟื้นฟูในทางปฏิบัติ: การเอาใจใส่และการตัดสินใจที่ดีขึ้นช่วยให้ผู้คนอยู่ในการรักษาและหลีกเลี่ยงการกำเริบของโรค';

  @override
  String get alcoholReferenceDay180 =>
      'การฟื้นฟูสมองในหกเดือนแห่งความสุขุม\n\nที่มา: การทบทวนโดยผู้ทรงคุณวุฒิเกี่ยวกับการฟื้นฟูสมองทั้งด้านโครงสร้างและการทำงานระหว่างการงดเว้นจากการใช้สารเสพติด (PubMed Central)\n\nการฟื้นตัวดำเนินต่อไป\nการฟื้นตัวของปริมาตรสมองในช่วงต้นของสัปดาห์แรกเป็นเพียงจุดเริ่มต้นเท่านั้นการทบทวนนี้บันทึกว่าด้วยการงดเว้นอย่างต่อเนื่อง สมองยังคงฟื้นตัวทั้งในด้านโครงสร้างและหน้าที่ โดยสสารสีเทาจะฟื้นตัวและทำลายเส้นทางของสสารสีขาวที่ประสานการสื่อสารระหว่างบริเวณสมองในการซ่อมแซมเป็นเวลาหลายเดือน\n\nด้านหน้าของสมอง\nการฟื้นตัวเป็นสิ่งสำคัญอย่างยิ่งในส่วนหน้าของสมอง ซึ่งทำหน้าที่ในการตัดสิน การวางแผน และการควบคุมตนเองเมื่อการรักษาดีขึ้น การตัดสินใจและการควบคุมแรงกระตุ้นก็แข็งแกร่งขึ้น\n\nการให้รางวัลสมองและการทำงาน\nนอกจากการซ่อมแซมทางกายภาพแล้ว การทำงานของสมองและการเชื่อมต่อก็ฟื้นตัวเช่นกันสมองสามารถวางสายและเรียนรู้ใหม่ได้ ซึ่งทำให้การเลิกบุหรี่อย่างต่อเนื่องเป็นช่วงเวลาที่มีประสิทธิภาพสำหรับการบำบัดและนิสัยใหม่ๆ\n\nสัญญาณการกู้คืน\nภายในหกเดือน โครงสร้างและการทำงานของสมองจะค่อยๆ เคลื่อนไปสู่สุขภาพปกติที่ดีขึ้นการไม่หยุดยั้งจะทำให้มีเวลาฟื้นตัวมากขึ้น';

  @override
  String get alcoholReferenceDay365 =>
      'แอลกอฮอล์ ความเสี่ยงมะเร็ง และการหยุด\n\nที่มา: สถาบันมะเร็งแห่งชาติ (NCI), \"ความเสี่ยงจากแอลกอฮอล์และมะเร็ง\"\n\nแอลกอฮอล์ทำให้เกิดมะเร็ง\nNCI ระบุว่ามีความเห็นพ้องต้องกันทางวิทยาศาสตร์ว่าการดื่มแอลกอฮอล์สามารถก่อให้เกิดมะเร็งได้แอลกอฮอล์เชื่อมโยงกับมะเร็งในช่องปาก (ช่องปาก) หลอดลม (คอ) กล่องเสียง (กล่องเสียง) หลอดอาหาร ตับ เต้านม ลำไส้ใหญ่และทวารหนักยิ่งใครดื่มมากเท่าไร และยิ่งดื่มนานเท่าไร ความเสี่ยงก็จะยิ่งสูงขึ้นเท่านั้น\n\nแอลกอฮอล์ขับมะเร็งได้อย่างไร\nกลไกต่างๆ ได้แก่ อะซีตัลดีไฮด์ ซึ่งเป็นผลิตภัณฑ์แอลกอฮอล์ที่เป็นพิษซึ่งทำลาย DNA;ความเครียดจากปฏิกิริยาออกซิเดชั่นและการอักเสบการดูดซึมสารอาหารป้องกันบกพร่องและสำหรับมะเร็งเต้านม ระดับฮอร์โมนเอสโตรเจนเพิ่มขึ้น\n\nความเสี่ยงจะลดลงหลังจากที่คุณหยุด\nที่สำคัญ NCI รายงานว่าการเลิกดื่มมีความสัมพันธ์กับความเสี่ยงที่ลดลงเมื่อเวลาผ่านไป การศึกษาต่างๆ แสดงให้เห็นความเสี่ยงที่เพิ่มขึ้นของโรคมะเร็งในช่องปากและหลอดอาหารลดลงหลังจากหยุด แม้ว่าอาจต้องใช้เวลาหลายปีกว่าจะเสี่ยงกับคนที่ไม่เคยดื่มก็ตามการงดแอลกอฮอล์หนึ่งปีถือเป็นก้าวที่มีความหมายบนเส้นทางนั้น\n\nผลประโยชน์ทับซ้อน\nการมีอายุถึงหนึ่งปียังล็อคการเพิ่มขึ้นของการงดเว้นหัวใจและหลอดเลือดและตับ — ลดความดันโลหิต ลดความเสี่ยงภาวะหัวใจเต้นผิดจังหวะ และการรักษาตับอย่างต่อเนื่อง — ควบคู่ไปกับความเสี่ยงมะเร็งลดลง';

  @override
  String get benzodiazepineReferenceDay7 =>
      'การถอนยา Benzodiazepine: สัปดาห์แรก\n\nที่มา: \"แนวทางทางคลินิกสำหรับการจัดการการถอนและการรักษาผู้ติดยาในพื้นที่ปิด\" องค์การอนามัยโลก (2552) บนชั้นวางหนังสือ NCBI\n\nหมายเหตุเกี่ยวกับความปลอดภัยในการถอนตัวของ Benzo\nการถอนเบนโซไดอะซีพีนอาจเป็นอันตรายได้แนวทางปฏิบัติของ WHO ระบุไว้อย่างชัดเจนว่าแนวทางที่ปลอดภัยที่สุดคือการให้ยาเบนโซไดอะซีพีนในปริมาณที่ค่อยๆ ลดลง ซึ่ง \"ช่วยบรรเทาอาการถอนยาเบนโซไดอะซีพีนและป้องกันการเกิดอาการชัก\"อย่าหยุดกะทันหันหลังจากใช้งานเป็นเวลานาน — ให้ปรึกษาแพทย์เพื่อเรียวเล็กลง\n\nเมื่อการถอนเงินปรากฏขึ้น\nลำดับเวลาของ WHO ขึ้นอยู่กับระยะเวลาออกฤทธิ์ของยา:\n• การออกฤทธิ์สั้น (ออกซาซีแพม, อัลปราโซแลม, เทมาซีแพม): การถอนยาจะเริ่มใน 1–2 วันหลังจากรับประทานยาครั้งสุดท้ายและดำเนินต่อไปอีก 2–4 สัปดาห์หรือนานกว่านั้น\n• การออกฤทธิ์นาน (ไดอาซีแพม, ไนทราซีแพม): การถอนยาจะเริ่มใน 2–7 วันหลังจากรับประทานยาครั้งสุดท้าย และดำเนินต่อไปอีก 2–8 สัปดาห์หรือนานกว่านั้น\nเหตุการณ์สำคัญในสัปดาห์แรกคือจุดที่แม้แต่เบนโซไดอะซีพีนที่ออกฤทธิ์นานกว่าก็หมดฤทธิ์เพียงพอสำหรับการถอนออกเพื่อให้เกิดผลเต็มที่\n\nอาการถอนตั้งแต่เนิ่นๆ\n• ความวิตกกังวลแบบฟื้นตัว — มักจะรุนแรงกว่าความวิตกกังวลเดิมที่ยารักษา\n• นอนไม่หลับและนอนไม่หลับ\n• อาการสั่นและตึงเครียดของกล้ามเนื้อ\n• เหงื่อออกและใจสั่น\n• เพิ่มความไวต่อแสงและเสียง\n\nการตรวจสอบ\nแนวทางปฏิบัติของ WHO ระบุว่าความรุนแรงของการถอนยา \'อาจผันผวนอย่างเห็นได้ชัด\' ดังนั้นจึงไม่แนะนำให้ใช้มาตราส่วนอย่างเป็นทางการแพทย์ควรตรวจดูทุกๆ สองสามชั่วโมง ให้ความมั่นใจ และอธิบายอาการแทนเบนโซไดอะซีพีนช่วยเพิ่ม GABA ซึ่งเป็นสัญญาณสงบหลักของสมองการใช้ในระยะยาวจะทำให้ระบบนั้นแย่ลง ดังนั้นการถอดยาออกจะทำให้สมองเกิดความตื่นเต้นมากเกินไป ซึ่งเป็นที่มาของความวิตกกังวล อาการสั่น และความเสี่ยงในการจับตัวเป็นลม ซึ่งจะทำให้การค่อยๆ ลดลงเป็นสิ่งจำเป็น';

  @override
  String get benzodiazepineReferenceDay14 =>
      'การถอนยา Benzodiazepine: สองสัปดาห์\n\nที่มา: Ashton, \"อาการถอนยาเป็นเวลานานจากเบนโซไดอะซีปีน\" วารสารการรักษาสารเสพติด (1991) บน PubMed\n\nยังอยู่ในการถอนตัวแบบเฉียบพลัน\nในช่วงสองสัปดาห์ หลายๆ คน โดยเฉพาะผู้ที่เลิกใช้เบนโซไดอะซีพีนที่ออกฤทธิ์นาน ยังคงอยู่ในช่วงเฉียบพลัน ซึ่งเป็นช่วงที่ความไม่สมดุลระหว่างระบบสงบเงียบของสมอง (GABA) และระบบกระตุ้นเด่นชัดที่สุดความวิตกกังวล การนอนไม่หลับ และการรบกวนการรับรู้เป็นเรื่องปกติ\n\nเหตุใดการถอนตัวของ Benzo จึงสามารถดำเนินต่อไปได้\nศาสตราจารย์ Heather Ashton อธิบายว่าอาการถอนยาครั้งแรกสามารถผสมผสานเข้ากับปัญหาที่ยืดเยื้อได้อย่างไรความวิตกกังวล นอนไม่หลับ ปัญหาในการคิดอย่างชัดเจน และการเปลี่ยนแปลงทางประสาทสัมผัสอาจดำเนินต่อไปเป็นเวลาหลายเดือน เนื่องจากการเปลี่ยนแปลงความทนทานของสมองอาจย้อนกลับได้ช้า\n\nการเปลี่ยนแปลงที่ย้อนกลับได้ช้าๆ\nแอชตันอธิบายลักษณะเหล่านี้ว่าเป็น \'การเปลี่ยนแปลงการทำงานที่ย้อนกลับได้ช้าๆ ในระบบประสาทส่วนกลาง\'ข้อเรียกร้องหลักคือการฟื้นตัว: ระบบประสาทจะค่อยๆ ย้อนกลับการปรับการทำงานที่เกิดจากการได้รับเบนโซไดอะซีพีนในระยะยาว\n\nการค่อยๆ ลดลงเป็นกุญแจสำคัญ\nหลักฐานสนับสนุนอย่างมากว่าการค่อยๆ ลดลงอย่างช้าๆ และได้รับการดูแลควบคุมเป็นวิธีที่ปลอดภัยที่สุดในการหยุด โดยปล่อยให้สมองค่อยๆ ปรับตัวใหม่ แทนที่จะเผชิญกับการสูญเสียสัญญาณที่ยับยั้งกะทันหัน';

  @override
  String get benzodiazepineReferenceDay60 =>
      'เบนโซและการฟื้นฟูการนอนหลับภายในสองเดือน\n\nที่มา: Poyares และคณะ \"การใช้และการถอนเบนโซไดอะซีพีนเรื้อรังในผู้ป่วยนอนไม่หลับ\" วารสารวิจัยจิตเวช (2004) บน PubMed\n\nBenzos เปลี่ยนการนอนหลับอย่างไร\nยาเบนโซไดอะซีพีนเป็นที่รู้จักอย่างกว้างขวางสำหรับการนอนไม่หลับ แต่ยาเหล่านี้เปลี่ยนแปลงโครงสร้างการนอนหลับในการศึกษาเกี่ยวกับการตรวจการนอนหลับหลายรอบในผู้ป่วยที่รับประทานเบนโซไดอะซีพีนทุกคืนเป็นเวลาเฉลี่ยเกือบเจ็ดปี การใช้แบบเรื้อรังสัมพันธ์กับการนอนหลับแบบคลื่นช้า (ลึก) ที่ลดลง และการนอนหลับระยะที่ 2 ที่สว่างมากขึ้น ผู้ใช้จึงสูญเสียการนอนหลับลึกเพื่อการฟื้นฟูแม้ในขณะที่รู้สึกผ่อนคลายก็ตาม\n\nการนอนหลับลึกกลับมา\nการค้นพบที่น่ายินดี: การศึกษาวัดการนอนหลับอีกครั้ง 15 วันหลังจากการถอนยา และพบว่าการนอนหลับแบบคลื่นช้าและกิจกรรมเดลต้าฟื้นตัวได้ เมื่อเทียบกับคืนที่ใช้งานเรื้อรัง พร้อมกับคุณภาพการนอนหลับแบบอัตนัยที่ดีขึ้นการนอนหลับลึกซึ่งถูกยาระงับไว้ เริ่มกลับมาภายในเวลาประมาณสองสัปดาห์หลังจากหยุด\n\nสิ่งนี้หมายถึงอะไรใน 60 วัน\nหากการนอนหลับลึกฟื้นตัวภายในสองสัปดาห์ แสดงว่าภายในสองเดือน สมองของคุณก็จะมีเวลาเหลือเฟือที่จะสร้างการนอนหลับที่เป็นธรรมชาติและฟื้นฟูต่อไปโดยทั่วไปอาการนอนไม่หลับที่ฟื้นตัวอย่างรุนแรงของการถอนตัวเร็วมักจะได้รับการแก้ไขแล้วผู้เขียนบอกตามตรงว่าการถอนยาทำให้การนอนหลับแย่ลงในช่วงแรก ซึ่งเป็นเหตุผลว่าทำไมการค่อยๆ ลดลงจึงมีความสำคัญ แต่เมื่อสิ้นสุดโครงการวิจัย คุณภาพการนอนหลับก็ดีขึ้นกว่าการใช้เบนโซไดอะซีปีนแบบเรื้อรัง\n\nการปรับปรุงอื่นๆ ภายในสองเดือน\nอาการถอนตัวทางกายภาพในช่วงต้นหลายอย่าง เช่น ความตึงเครียดของกล้ามเนื้อ อาการสั่น ใจสั่น เหงื่อออก โดยทั่วไปจะบรรเทาลงหรือหายไปภายในเวลาสองเดือนเมื่อร่างกายควบคุมใหม่';

  @override
  String get benzodiazepineReferenceDay90 =>
      'สามเดือนหลังจากใช้ยาเบนโซ: สุขภาพกายเริ่มคงที่\n\nที่มา: Ashton, \"อาการถอนยาเป็นเวลานานจากเบนโซไดอะซีปีน\" วารสารการรักษาสารเสพติด (1991) บน PubMed\n\nการรักษาเสถียรภาพทางกายภาพ\nเมื่อครบ 90 วัน ระยะเฉียบพลันก็ผ่านไปแล้วสำหรับผู้ที่ทำ Taper สำเร็จแล้ว อาการถอนทางกายภาพส่วนใหญ่ เช่น อาการสั่น ใจสั่น ปวดศีรษะ และการรบกวนการนอนหลับที่เลวร้ายที่สุด จะลดลงอย่างมาก และโดยทั่วไปการนอนหลับจะมีเสถียรภาพมากขึ้น\n\nทำไมอาการบางอย่างยังคงอยู่\nแอชตันบันทึกว่าอาการบางอย่างอาจคงอยู่นานหลายเดือนเมื่อถึงสามเดือน ความวิตกกังวลที่ยืดเยื้อ หมอกในสมอง และการเปลี่ยนแปลงทางประสาทสัมผัสยังคงปรากฏขึ้นในขณะที่สมองยังคงปรับตัวอย่างช้าๆ และย้อนกลับได้\n\nเหตุผลสองประการที่ความวิตกกังวลยังคงอยู่\n1. ระบบ GABA ของสมองยังคงปรับตัวเข้ากับความไวตามปกติ ซึ่งเป็นกระบวนการที่ช้า\n2. ความวิตกกังวลที่ซ่อนอยู่ซึ่งนำไปสู่การใช้เบนโซสามารถรู้สึกได้โดยไม่ต้องใช้บัฟเฟอร์ที่ขับเคลื่อนด้วยยา\n\nช่วงเวลาที่ดีสำหรับการบำบัด\nเมื่อมีอาการแย่ที่สุดในระยะเริ่มแรกอยู่ข้างหลังคุณ สามเดือนถือเป็นจุดแข็งที่จะใช้การสนับสนุน เช่น การบำบัดด้วยการพูดคุย เช่น CBT (CBT) สำหรับความวิตกกังวล และสร้างทักษะการรับมือในขณะที่ระบบประสาทยังคงนิ่งอยู่';

  @override
  String get benzodiazepineReferenceDay180 =>
      'การคิดและความทรงจำในหกเดือน: กำไรที่วัดได้\n\nที่มา: Tata et al., \"ขาดการฟื้นตัวของความรู้ความเข้าใจหลังจากการถอนตัวจากการใช้เบนโซไดอะซีพีนในระยะยาว\" เวชศาสตร์จิตวิทยา (1994) บน PubMed\n\nสิ่งที่การศึกษาทำ\nการศึกษานี้ทดสอบผู้ป่วยเบนโซไดอะซีพีนในระยะยาว 21 รายก่อนถอนยา หลังถอนยาทันที และอีกครั้งเมื่องดเว้นเป็นเวลา 6 เดือน โดยเปรียบเทียบกับกลุ่มควบคุมที่ตรงกันเป็นหนึ่งในจุดข้อมูลที่ตรงไปตรงมาที่สุดในเอกสารการฟื้นตัวของเบนโซ\n\nสิ่งที่พบ\nก่อนหยุด ผู้ป่วยมีปัญหาเกี่ยวกับการเรียนรู้ด้วยวาจา ความจำ ความเร็วในการเคลื่อนไหว การประสานงานด้านการมองเห็น และการใช้เหตุผลทางการมองเห็นหลังจากหยุดก็มีการเปลี่ยนแปลงเล็กน้อยเมื่อผ่านไปหกเดือน หลายพื้นที่เหล่านั้นก็ดีขึ้นอย่างเห็นได้ชัด\n\nนี่หมายถึงอะไร\nเมื่อผ่านไปหกเดือน การเรียนรู้ด้วยวาจา ความจำ ความเร็วการเคลื่อนไหว และการประสานงานด้านภาพก็ฟื้นตัวได้อย่างวัดผลได้การปรับปรุงมีความชัดเจนแล้วและยังมีพื้นที่ให้ดำเนินการต่อไป\n\nภาพใหญ่ขึ้น\nหากคุณรู้สึกว่ามีหมอกหนาในหกเดือน งานวิจัยนี้ระบุว่า เป็นสิ่งที่คาดหวัง และการงดเว้นอย่างต่อเนื่องคือหนทางข้างหน้าการศึกษาระยะยาวแสดงให้เห็นว่าการฟื้นตัวยังคงดำเนินไปได้ดีเกินกว่าจุดนี้ — สมองยังคงรักษาต่อไป';

  @override
  String get benzodiazepineReferenceDay365 =>
      'หนึ่งปีหลังจากใช้ยาเบนโซ: การคิดและความทรงจำยังคงฟื้นตัว\n\nที่มา: Barker et al., \"การคงอยู่ของผลกระทบทางความรู้ความเข้าใจหลังจากการถอนตัวจากการใช้เบนโซไดอะซีพีนในระยะยาว: การวิเคราะห์เมตาดาต้า\" Archives of Clinical Neuropsychology (2004) บน PubMed\n\nหลักฐานที่แข็งแกร่งที่สุดที่เรามี\nนักวิจัยได้รวมการศึกษาที่ทดสอบผู้ใช้เบนโซไดอะซีพีนในระยะยาวอีกครั้งหลังจากเลิกใช้ยาอย่างน้อยหกเดือนผลลัพธ์ที่รวมกันแสดงให้เห็นถึงการฟื้นตัวที่ชัดเจนในด้านความคิดและความทรงจำหลังการถอนตัว\n\nข่าวดี\nการศึกษาแบบผสมผสานพบว่ามีการปรับปรุงอย่างแท้จริงและวัดผลได้ในด้านต่างๆ ของการคิดและความจำหลังจากการถอนยาประมาณหนึ่งปี การฟื้นตัวจะกว้างและชัดเจนเมื่อเทียบกับการใช้งานจริง\n\nการกู้คืนดำเนินต่อไป\nการศึกษาแบบผสมผสานพบว่ามีการฟื้นตัวในวงกว้างในด้านความคิดและความจำภายในหนึ่งปี คุณจะมีแนวโน้มการฟื้นตัวที่ดีซึ่งสามารถวัดผลได้ภายในหกเดือน\n\nนี่หมายถึงอะไรในหนึ่งปี\nคาดว่าการคิด ความจำ และความชัดเจนจะฟื้นตัวอย่างมากภายในหนึ่งปี คนส่วนใหญ่จะรู้สึกเฉียบคมกว่าตอนใช้งานอย่างเห็นได้ชัดแต่หากบางพื้นที่ยังล่าช้าแสดงว่าสอดคล้องกับหลักฐานไม่ใช่สัญญาณว่าคุณจนตรอกการฟื้นตัวยังคงดำเนินต่อไป และการงดเว้นหนึ่งปีถือเป็นเหตุการณ์สำคัญที่สำคัญและคุ้มค่าบนเส้นทางนั้น';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 เดือนหลังใช้ยาเบนโซ: ฟื้นตัวช้าแต่ได้จริง\n\nที่มา: Ashton, \"อาการถอนยาเป็นเวลานานจากเบนโซไดอะซีปีน\" วารสารการรักษาสารเสพติด (1991) บน PubMed\n\nทำไม Benzo Recovery ถึงใช้เวลานานมาก\nเบนโซออกฤทธิ์ต่อ GABA ซึ่งเป็นระบบสงบเงียบหลักของสมองการใช้งานระยะยาวจะเปลี่ยนการตอบสนองของระบบนั้นอย่างมาก และการเปลี่ยนแปลงเหล่านั้นอาจใช้เวลาหลายเดือนกว่าจะย้อนกลับได้นั่นคือสาเหตุที่การฟื้นตัวของเบนโซวัดเป็นเดือนแทนที่จะเป็นสัปดาห์\n\nที่ 18 เดือนนั่งอยู่\nแอชตันอธิบายถึงอาการถอนยาที่กินเวลานานกว่าซึ่งอาจใช้เวลาหลายเดือนกว่าจะบรรเทาลงภายใน 18 เดือน สิ่งที่เลวร้ายที่สุดก็ตามหลังคนส่วนใหญ่ไป และความวิตกกังวลที่ยังคงอยู่ การเปลี่ยนแปลงทางประสาทสัมผัส และหมอกในสมองก็คลี่คลายลงอย่างมาก\n\nพลิกกลับได้ช้าๆ\nสิ่งสำคัญอย่างยิ่งคือ Ashton กำหนดกรอบการเปลี่ยนแปลงที่ซ่อนอยู่ว่าเป็น \'การเปลี่ยนแปลงการทำงานที่สามารถย้อนกลับได้อย่างช้าๆ ในระบบประสาทส่วนกลาง\'ช้า แต่สามารถย้อนกลับได้ — เส้นเวลาที่ยาวนานสะท้อนถึงความลึกของการปรับตัวของเบนโซไดอะซีพีนที่เกิดขึ้น ไม่ใช่ความเสียหายถาวรในคนส่วนใหญ่\n\nสัญญาณการกู้คืน\nAshton อธิบายการเปลี่ยนแปลงที่ซ่อนอยู่ว่าสามารถย้อนกลับได้อย่างช้าๆเมื่อผ่านไป 18 เดือน ระบบ GABA ที่ทำให้สมองสงบลงจะใช้เวลาปรับตัวนาน และทิศทางหลักก็จะฟื้นตัวเข้าสู่ภาวะปกติต่อไป';

  @override
  String get benzodiazepineReferenceDay730 =>
      'สองปีหลังจากเบนโซไดอะซีพีน: ความก้าวหน้าครั้งสำคัญที่ยั่งยืน\n\nที่มา: Barker et al., \"การคงอยู่ของผลกระทบทางความรู้ความเข้าใจหลังจากการถอนตัวจากการใช้เบนโซไดอะซีพีนในระยะยาว: การวิเคราะห์เมตาดาต้า\" Archives of Clinical Neuropsychology (2004) บน PubMed\n\nแลนด์มาร์คแห่งการฟื้นฟู\nสองปีถือเป็นเหตุการณ์สำคัญ โดยเฉพาะอย่างยิ่งหลังจากการถอนตัวออกไปเป็นเวลานานระยะอาการเริ่มแรกและต่อเนื่องนั้นผ่านไปนานแล้ว และผลที่เพิ่มขึ้นจากปีแรกก็มีเวลาอีกปีที่ต้องทำให้แข็งแกร่งขึ้น\n\nสิ่งที่หลักฐานสนับสนุน\nการศึกษาแบบผสมผสานแสดงให้เห็นการฟื้นตัวในหลายด้านหลังจากการถอนยาภายในสองปี คนส่วนใหญ่รายงานว่ามีความวิตกกังวลถึงหรือต่ำกว่าระดับพรีเบนโซ การนอนหลับโดยไม่ต้องใช้ยา อารมณ์มั่นคงขึ้น และความคิดที่ชัดเจนกว่าระหว่างใช้งาน\n\nสัญญาณการกู้คืน\nการศึกษาแบบผสมผสานนี้ทำให้เกิดการฟื้นตัวในหลายๆ ด้านของการคิดและความทรงจำในสองปี การฟื้นตัวอย่างยั่งยืนคือความคาดหวังที่มีหลักฐานสนับสนุน\n\nการรักษามุมมอง\nสองปีช่วยให้การนอนหลับ อารมณ์ ความทรงจำ และการคิดที่ชัดเจนมีเวลาฟื้นตัวที่ยาวนานหลักฐานแสดงให้เห็นถึงการปรับปรุงที่สำคัญในทั้งสี่ โดยการรักษาจะดำเนินต่อไปจากที่นี่';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'สามปีหลังจากเบนโซไดอะซีพีน: การรักษาระยะยาว\n\nที่มา: Barker et al., \"การคงอยู่ของผลกระทบทางความรู้ความเข้าใจหลังจากการถอนตัวจากการใช้เบนโซไดอะซีพีนในระยะยาว: การวิเคราะห์เมตาดาต้า\" Archives of Clinical Neuropsychology (2004) บน PubMed\n\nมุมมองยาว\nสามปีถือเป็นช่วงสุดท้ายของเส้นเวลาการฟื้นฟูเบนโซสำหรับคนส่วนใหญ่ แม้หลังจากการถอนยาอย่างรุนแรงเป็นเวลานาน อาการที่ไม่พึงประสงค์ยังคงอยู่และคุณภาพชีวิตก็เปลี่ยนไปเมื่อเทียบกับการใช้งานอย่างต่อเนื่อง\n\nสิ่งที่การวิเคราะห์เมตาพบ\nการศึกษาร่วมกันของผู้ใช้ระยะยาวแสดงให้เห็นการฟื้นตัวในหลายพื้นที่หลังจากการถอนออกเรื่องราวที่โดดเด่นในช่วงหลายปีที่ผ่านมาคือการฟื้นตัวในด้านความคิด ความทรงจำ และการทำงานในแต่ละวัน\n\nสัญญาณการกู้คืน\nการวิจัยระยะยาวแสดงให้เห็นถึงการฟื้นตัวในหลายๆ ด้านของการคิดและความทรงจำเมื่อถึงสามปี ขั้นตอนการถอนเงินในช่วงแรกและยาวนานนั้นยังตามหลังคุณอยู่มาก และกำไรเหล่านั้นก็ต้องใช้เวลาอีกหลายปีในการเสริมความแข็งแกร่ง\n\nข้อความแห่งความหวัง\nเส้นทางการฟื้นฟูด้วยเบนโซถือเป็นภารกิจด้านการแพทย์ที่มีความต้องการมากที่สุด และการรักษาอย่างต่อเนื่องเป็นเวลาสามปีถือเป็นความสำเร็จที่ยิ่งใหญ่หลักฐานชัดเจน: สมองได้รับการเยียวยาอย่างมาก คนส่วนใหญ่ฟื้นตัวได้อย่างชัดเจน การนอนหลับ และช่วงทางอารมณ์ และการปรับปรุงจะดำเนินไปตามเวลา';

  @override
  String get cocaineReferenceDay1 =>
      'การถอนโคเคน: 24 ชั่วโมงแรก\n\nที่มา: \"Withdrawal Syndromes\" StatPearls (ชั้นวางหนังสือ NCBI) หอสมุดแพทยศาสตร์แห่งชาติของสหรัฐอเมริกา\n\nโคเคนและสมอง\nโคเคนขัดขวางการดูดซึมโดปามีน (และโมโนเอมีน other) อีกครั้งในวงจรการให้รางวัลของสมอง ทำให้โดปามีนสะสมและสร้างความสุขและพลังงานอย่างเข้มข้นเมื่อใช้เป็นประจำ สมองจะปรับตัวโดยการลดการควบคุมระบบ ดังนั้นหากไม่มียา กิจกรรมปกติจะรู้สึกไม่สู้ดีนัก\n\nความผิดพลาด\nStatPearls อธิบายถึงการถอนยากระตุ้นโดยเริ่มจาก \"การหยุดทำงาน\" เมื่อหยุดใช้ โดยมีลักษณะเด่นคือมีอาการซึมเศร้า นอนหลับมากเกินไป ความหิว อารมณ์ไม่ดี และการเคลื่อนไหวและการคิดช้าลงอย่างรุนแรงโดยทั่วไปแล้วใน 24 ชั่วโมงแรกจะรวมถึง:\n• เหนื่อยล้าอย่างมากและจำเป็นต้องนอนเพิ่มขึ้น\n• อารมณ์หดหู่และการเคลื่อนไหวและการคิดช้าลง\n• ความอยากอาหารเพิ่มขึ้น (โคเคนระงับความอยากอาหาร)\n\nความอยาก ความหงุดหงิด และวิตกกังวลมักถูกรายงานในช่วงกรอบเวลานี้ในวรรณกรรมเกี่ยวกับการติดยาเสพติดในวงกว้าง แม้ว่า StatPearls จะไม่ลงรายละเอียดว่าเป็นส่วนหนึ่งของเหตุการณ์ขัดข้องโดยเฉพาะก็ตาม\n\nไม่เหมือนยาบางชนิด\nStatPearls ตั้งข้อสังเกตว่าการถอนตัวกระตุ้นนั้นได้รับการปฏิบัติด้วยการสังเกตและการดูแลแบบประคับประคองแตกต่างจากการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีน โดยทั่วไปจะไม่ทำให้เกิดอาการชักหรืออาการเพ้ออันตรายหลักคือสภาวะจิตใจ — ภาวะซึมเศร้า และสำหรับผู้ใช้จำนวนมาก ความคิดฆ่าตัวตายอาจเกิดขึ้นได้ในระหว่างเกิดอุบัติเหตุ ดังนั้นจึงแนะนำให้ให้การสนับสนุนและติดตาม\n\nไม่มียาที่ได้รับการรับรอง\nขณะนี้ยังไม่มียาที่ได้รับการอนุมัติให้ใช้รักษาอาการถอนโคเคนได้การจัดการคือการสนับสนุน และแนวทางการไม่ใช้ยา เช่น การจัดการภาวะฉุกเฉินเป็นวิธีการรักษาที่มีหลักฐานเชิงประจักษ์สำหรับความผิดปกติจากการใช้ยา';

  @override
  String get cocaineReferenceDay3 =>
      'สามวันโดยไม่มีโคเคน: ก้าวสู่จุดสูงสุด\n\nที่มา: \"ความเป็นพิษของโคเคน\" StatPearls (ชั้นวางหนังสือ NCBI) หอสมุดแพทยศาสตร์แห่งชาติของสหรัฐอเมริกา\n\nโคเคนส่งผลต่อร่างกายอย่างไร\nเอกสารของ StatPearls ที่โคเคนขัดขวางการดูดซึมโดปามีน นอร์เอพิเนฟริน และเซโรโทนินกลับคืน ส่งผลให้การกระตุ้นด้วยความเห็นอกเห็นใจยืดเยื้อออกไปนี่คือสิ่งที่ขับเคลื่อนทั้งความอิ่มเอิบใจและอันตรายของมัน มันสามารถส่งผลกระทบต่อระบบอวัยวะเกือบทุกระบบ\n\nวันที่ 2–4: การถอนตัวทางจิตวิทยาสูงสุด\nในวันที่สาม อุบัติเหตุเฉียบพลันทำให้เกิดอาการถอนตัวทางจิตใจที่รุนแรงที่สุด:\n• อารมณ์ต่ำและอารมณ์หดหู่อย่างรุนแรงที่สุด\n• สูญเสียความสุข\n• ความอยากที่แรงกระตุ้นด้วยคิว\n• ความวิตกกังวลและกระสับกระส่าย\n• การนอนหลับรบกวน — มากเกินไปในบางคน นอนไม่หลับในบางคน\n\nอันตรายต่อหัวใจและหลอดเลือดลดลง\nStatPearls ระบุว่าความเป็นพิษต่อระบบหัวใจและหลอดเลือดเป็นผลร้ายแรงที่สุดของโคเคน: อัตราการเต้นของหัวใจและความดันโลหิตที่เพิ่มขึ้น ความต้องการออกซิเจนในกล้ามเนื้อหัวใจเพิ่มขึ้น ภาวะหลอดเลือดหดเกร็งของหลอดเลือด และการกระตุ้นเกล็ดเลือด ซึ่งทำให้เกิดความเสี่ยงต่อภาวะหัวใจเต้นผิดจังหวะ ภาวะกล้ามเนื้อหัวใจตาย และโรคหลอดเลือดสมอง แม้แต่ในผู้ใช้อายุน้อยครึ่งชีวิตของโคเคนนั้นสั้น คือ ประมาณหนึ่งชั่วโมง และในวันที่สาม ตัวยาเองก็ได้ล้างระบบของคุณอย่างสมบูรณ์แล้ว แม้ว่า StatPearls จะตั้งข้อสังเกตว่าสารเมตาโบไลต์ของมันยังคงทำให้เกิดการหดตัวของหลอดเลือดได้เป็นเวลาหลายชั่วโมงหลังการใช้ และสารเมตาบอไลต์หนึ่งตัวอาจคงอยู่นานหลายสัปดาห์ ดังนั้นความเครียดจากระบบหัวใจและหลอดเลือดบางส่วนที่หลงเหลืออยู่สามารถอยู่ได้นานกว่าตัวยาเอง\n\nถนนข้างหน้า\nระยะเฉียบพลันนั้นรุนแรง แต่อาการทางจิตใจ เช่น ซึมเศร้า ความอยาก สูญเสียความสุข ต่างหากที่ต้องได้รับการช่วยเหลือมากที่สุดและคงอยู่นานที่สุด';

  @override
  String get cocaineReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่มีโคเคน: เริ่มต้นการฟื้นฟูร่างกาย\n\nที่มา: \"Withdrawal Syndromes\" StatPearls (ชั้นวางหนังสือ NCBI) หอสมุดแพทยศาสตร์แห่งชาติของสหรัฐอเมริกา\n\nระยะเฉียบพลันกำลังจะสิ้นสุดลง\nStatPearls อธิบายว่าการถอนโคเคนเป็นการย้ายจากความผิดพลาดครั้งแรกไปสู่ระยะการฟื้นฟูที่ยาวนานขึ้นภายในสิ้นสัปดาห์แรก อาการที่เลวร้ายที่สุดมักจะบรรเทาลงในขณะที่ระบบโดปามีนยังคงสร้างใหม่ต่อไป\n\nการฟื้นฟูทางกายภาพอยู่ระหว่างดำเนินการ\nเมื่อการกระตุ้นด้วยความเห็นอกเห็นใจของโคเคนหยุดลง ผลกระทบของโคเคนต่อระบบหัวใจและหลอดเลือด ความอยากอาหาร การนอนหลับ และทางเดินหายใจจะเริ่มย้อนกลับในวันและสัปดาห์ต่อไปนี้:\n• อัตราการเต้นของหัวใจและความดันโลหิตกลับสู่ปกติ\n• ความอยากอาหารค่อยๆ กลับมาอีกครั้ง (โคเคนระงับความอยากอาหารอย่างรุนแรง)\n• รูปแบบการนอนเริ่มคงที่\n• ช่องจมูกเริ่มหายหากมีโคเคนสูดดม\n\nอาการทางจิตเกิดขึ้นต่อไป\nStatPearls ตั้งข้อสังเกตว่าภาวะซึมเศร้าและการสูญเสียความสุขเป็นลักษณะของการถอนตัวจากการกระตุ้นและอยู่ได้นานกว่าอาการทางกายภาพ:\n• อารมณ์ยังคงต่ำ แม้ว่าจะรุนแรงน้อยกว่าช่วงสูงสุดก็ตาม\n• ความอยากที่กระตุ้นด้วยคิวยังคงรุนแรง\n• สมาธิและแรงจูงใจยังคงบกพร่อง\n\nระยะหลังเฉียบพลัน\nการถอนตัวจะเปลี่ยนเป็นสัปดาห์หรือเดือนของการปรับปรุงอารมณ์ ความอยาก และการคิดที่ชัดเจนมากขึ้นการรู้รูปแบบนั้นทำให้การฟื้นตัวช้าลงจัดการได้ง่ายขึ้น';

  @override
  String get cocaineReferenceDay14 =>
      'สองสัปดาห์โดยไม่มีโคเคน: การค้นหาความมั่นคง\n\nที่มา: \"Withdrawal Syndromes\" StatPearls (ชั้นวางหนังสือ NCBI) หอสมุดแพทยศาสตร์แห่งชาติของสหรัฐอเมริกา\n\nสองสัปดาห์ใน\nเมื่อผ่านไปสองสัปดาห์ อาการการชนที่รุนแรง เช่น ภาวะซึมเศร้าลึก นอนหลับมาก การเคลื่อนไหวและการคิดช้าลง โดยทั่วไปจะคลี่คลายลงขณะนี้การฟื้นตัวมุ่งเน้นไปที่การสร้างสุขภาพสมองและอารมณ์ขึ้นมาใหม่\n\nสภาวะอารมณ์และอารมณ์\nในสองสัปดาห์ อารมณ์ยังคงต่ำกว่าปกติในขณะที่ระบบโดปามีนฟื้นตัวเมื่อเทียบกับสัปดาห์แรก การสูญเสียความสุขอย่างลึกซึ้งจะผ่อนคลายลง และช่วงเวลาแห่งความเป็นอยู่ที่ดีที่แท้จริงกำลังกลับมา\n\nความอยากและทริกเกอร์\nความอยากที่กระตุ้นด้วยคิวถือเป็นความท้าทายที่สำคัญในระยะนี้สมองมีความสัมพันธ์ที่แน่นแฟ้นระหว่างการใช้โคเคนกับสภาพแวดล้อม ผู้คน อารมณ์ และกิจกรรมที่เฉพาะเจาะจงการเผชิญสิ่งกระตุ้นเหล่านี้อาจทำให้เกิดความอยากอาหารอย่างรุนแรงแม้ว่าอารมณ์โดยทั่วไปจะดีขึ้นก็ตามการหลีกเลี่ยงสภาพแวดล้อมที่มีความเสี่ยงสูงและการสร้างความสัมพันธ์ใหม่ถือเป็นสิ่งสำคัญ\n\nการปรับปรุงการนอนหลับ\nการนอนหลับมักจะคงที่และฟื้นตัวได้ภายในสองสัปดาห์มากกว่าในช่วงระยะถอนตัวแบบเฉียบพลันการนอนหลับที่ดีขึ้นมีผลเชิงบวกอย่างมากต่ออารมณ์ การคิดที่ชัดเจน และความสามารถในการจัดการกับความอยาก\n\nการสร้างมูลนิธิ\nเนื่องจากการรักษาความผิดปกติจากการใช้สารกระตุ้นโดยอิงหลักฐานเชิงประจักษ์นั้นขึ้นอยู่กับพฤติกรรม การจัดการภาวะฉุกเฉิน การบำบัด และการสนับสนุนจากเพื่อนฝูง ระยะเวลาสองสัปดาห์จึงเป็นช่วงเวลาสำคัญในการมีส่วนร่วมกับโครงสร้างการสนับสนุนที่จะสนับสนุนการฟื้นตัวในระยะยาว';

  @override
  String get cocaineReferenceDay60 =>
      'สองเดือนที่ไม่มีโคเคน: อารมณ์และรางวัลเริ่มฟื้นตัว\n\nที่มา: \"การกู้คืนจากโคเคน: ข้อมูลเชิงลึกจากการสืบสวนทางคลินิกและพรีคลินิก\" บทวิจารณ์ด้านประสาทวิทยาศาสตร์และพฤติกรรมชีวภาพ (2013) บน PubMed Central\n\nสิ่งที่สมองกำลังทำอยู่\nการทบทวนนี้เป็นการสังเคราะห์การศึกษาของมนุษย์และสัตว์เกี่ยวกับสิ่งที่เกิดขึ้นกับสมองเมื่อหยุดการใช้โคเคนโคเคนเรื้อรังเปลี่ยนแปลงระบบโดปามีนและลดกิจกรรมในเยื่อหุ้มสมองส่วนหน้าการฟื้นตัวของระบบเหล่านี้เป็นปัจจัยสำคัญในการปรับปรุงอารมณ์และแรงจูงใจที่ผู้คนสังเกตเห็นในการเลิกบุหรี่ตั้งแต่เนิ่นๆ\n\nความคืบหน้าของระบบรางวัล\nในการศึกษาในสัตว์ทดลอง การเปลี่ยนแปลงที่เกี่ยวข้องกับโคเคนในตัวรับโดปามีนและการรีไซเคิลโปรตีนกลับไปสู่ระดับที่ดีต่อสุขภาพด้วยการเลิกบุหรี่อย่างต่อเนื่องเมื่อระบบการให้รางวัลฟื้นตัว การสูญเสียความสุขอย่างล้ำลึกก็เพิ่มขึ้นและรางวัลในแต่ละวัน เช่น อาหาร การเชื่อมต่อ ความสำเร็จ รู้สึกเหมือนได้รับรางวัลอีกครั้ง\n\nสัญญาณการกู้คืน\nภายในสองเดือน อารมณ์จะดีขึ้นและการนอนหลับจะคงที่มากขึ้น ในขณะที่ระบบโดปามีนและเยื่อหุ้มสมองส่วนหน้ายังคงสร้างใหม่ต่อไปการศึกษาในไพรเมตแสดงให้เห็นว่าการเปลี่ยนแปลงของตัวรับ D1 และผู้ขนส่งที่เกี่ยวข้องกับโคเคนกลับไปสู่ระดับควบคุมด้วยการเลิกบุหรี่อย่างต่อเนื่อง';

  @override
  String get cocaineReferenceDay90 =>
      'สามเดือนโดยไม่มีโคเคน: เครื่องหมายโดปามีนฟื้นตัว\n\nที่มา: \"การกู้คืนจากโคเคน: ข้อมูลเชิงลึกจากการสืบสวนทางคลินิกและพรีคลินิก\" บทวิจารณ์ด้านประสาทวิทยาศาสตร์และพฤติกรรมชีวภาพ (2013) บน PubMed Central\n\nเหตุใด 90 วันจึงเป็นจุดสังเกต\nการทบทวนนี้เน้นย้ำจุดสามเดือนว่ามีความหมายทางชีวภาพในไพรเมตที่ไม่ใช่มนุษย์ ตัวรับ dopamine D1 และผู้ขนส่งโคเคนที่เพิ่มขึ้นแสดงให้เห็นว่า \"หลักฐานการกลับมาสู่ระดับควบคุม\" หลังจากการเลิกบุหรี่ประมาณ 90 วัน ซึ่งเป็นหลักฐานโดยตรงที่แสดงว่าระบบการให้รางวัลสามารถปรับได้อีกครั้งเมื่อยาหมดไป\n\nด้านหน้าของสมอง\nผู้เขียนเน้นย้ำว่าการฟื้นตัวของสมองส่วนหน้าเป็นสัญญาณที่สำคัญที่สุดอย่างหนึ่งของการเลิกบุหรี่เป็นเวลานานบริเวณนี้ควบคุมแรงกระตุ้น การตัดสินใจ และการควบคุมตนเอง และความสามารถเหล่านั้นจะแข็งแกร่งขึ้นเมื่อฟื้นตัว\n\nสิ่งที่แสดงให้เห็น 90 วัน\nเมื่อครบ 90 วัน การศึกษาเกี่ยวกับไพรเมตพบว่าความหนาแน่นของ D1, D2 และสารขนส่งโดปามีนไม่แตกต่างอย่างมีนัยสำคัญจากกลุ่มควบคุมที่ไม่ใช้ยาอีกต่อไปแม้จะเปิดรับแสงเป็นเวลานาน การฟื้นตัวของระบบโดปามีนจำนวนมากก็สามารถมองเห็นได้ในจุดนี้และยังคงดำเนินต่อไปโดยงดเว้น';

  @override
  String get cocaineReferenceDay180 =>
      'หกเดือนโดยไม่มีโคเคน: การคิดที่ชัดเจนยิ่งขึ้น\n\nที่มา: \"การฟื้นฟูสมองเชิงโครงสร้างและการทำงานของบุคคลที่มีความผิดปกติจากการใช้สารเสพติดระหว่างการเลิกบุหรี่: การทบทวนการศึกษาการสร้างภาพระบบประสาทตามยาว\" บน PubMed Central\n\nการกู้คืนที่คุณสามารถสร้างภาพได้\nการทบทวนนี้รวมเอาการศึกษาเกี่ยวกับการถ่ายภาพสมองตามยาวซึ่งจะสแกนคนกลุ่มเดิมซ้ำๆ เมื่อการเลิกบุหรี่ของพวกเขายาวนานขึ้นสำหรับโคเคน รายงานว่ากิจกรรมการทำงานสามารถฟื้นตัวได้อย่างวัดผลได้ด้วยการเลิกบุหรี่อย่างต่อเนื่อง\n\nหลักฐานการถ่ายภาพสมอง\nการศึกษาด้วย MRI เชิงฟังก์ชัน 2 ชิ้นติดตามผู้ใช้โคเคนเมื่อเวลาผ่านไป และทั้งสองพบว่าการกระตุ้นการทำงานของสมองส่วนกลางและฐานดอกดีขึ้นด้วยการเลิกบุหรี่นานขึ้นประการหนึ่ง หลังจากงดเว้นไปประมาณหกเดือน รูปแบบการกระตุ้นของสมองก็เทียบได้กับรูปแบบการควบคุมเพื่อสุขภาพที่ไม่เสพติดในบรรดาสารต่างๆ การทบทวนตั้งข้อสังเกตว่าผลลัพธ์จากการถ่ายภาพด้วยนิวเคลียร์ชี้ไปที่การฟื้นตัวของโดปามิเนอร์จิคด้วยการเลิกบุหรี่\n\nสิ่งนี้หมายความว่าเมื่อหกเดือน\nประโยชน์ที่ได้รับจากการทำงานเหล่านี้ติดตามด้วยการปรับปรุงในโลกแห่งความเป็นจริงที่ผู้คนรายงานในขั้นตอนนี้:\n• มีความสนใจและความจำในการทำงานดีขึ้น\n• การตัดสินใจที่คมชัดยิ่งขึ้นและการควบคุมแรงกระตุ้น\n• อารมณ์มั่นคงขึ้นและการควบคุมอารมณ์\n\nสัญญาณการกู้คืน\nเมื่อเวลาประมาณหกเดือน กลุ่มตัวอย่าง fMRI ระยะยาวกลุ่มหนึ่งแสดงรูปแบบการกระตุ้นที่เทียบได้กับกลุ่มควบคุมที่ดีต่อสุขภาพโดยไม่เสพติด ในขณะที่การกระตุ้นสมองส่วนกลางและสมองส่วนลึกดีขึ้นเมื่อการเลิกบุหรี่นานขึ้นนั่นคือการฟื้นฟูสมองจากการทำงานโดยตรง';

  @override
  String get cocaineReferenceDay365 =>
      'หนึ่งปีโดยไม่มีโคเคน: ความเครียดของหัวใจและหลอดเลือดถูกลบออก\n\nที่มา: \"ความเป็นพิษของโคเคน\" StatPearls (ชั้นวางหนังสือ NCBI) หอสมุดแพทยศาสตร์แห่งชาติของสหรัฐอเมริกา\n\nเหตุใดหัวใจจึงเป็นศูนย์กลาง\nStatPearls ระบุว่าความเป็นพิษต่อระบบหัวใจและหลอดเลือดเป็นผลร้ายแรงที่สุดของโคเคนการใช้แต่ละครั้งจะทำให้อัตราการเต้นของหัวใจ ความดันโลหิต และความต้องการออกซิเจนในกล้ามเนื้อหัวใจเพิ่มขึ้น ในขณะเดียวกันก็ทำให้เกิดภาวะหลอดเลือดหัวใจตีบและส่งเสริมการเกิดลิ่มเลือด ซึ่งเป็นส่วนผสมที่กระตุ้นให้เกิดอาการหัวใจวาย ภาวะหัวใจเต้นผิดจังหวะ และโรคหลอดเลือดสมอง แม้แต่ในคนหนุ่มสาว\n\nปีแห่งการเลิกบุหรี่จะขจัดอะไรออกไป\nทุกวันที่ปราศจากโคเคนคือวันที่ปราศจากการดูถูกเหยียดหยามเหล่านี้กว่าหนึ่งปีที่ความดันโลหิตและอัตราการเต้นของหัวใจเพิ่มขึ้นซ้ำแล้วซ้ำเล่าหายไป ความเสี่ยงของภาวะหลอดเลือดหัวใจตีบจากโคเคนและภาวะกล้ามเนื้อตายเฉียบพลันหายไป และหัวใจไม่ได้ถูกผลักดันให้ออกซิเจนไม่ตรงกันอีกต่อไป\n\nสัญญาณการกู้คืน\nการหยุดโคเคนจะหยุดภาวะหลอดเลือดหัวใจตีบซ้ำ หัวใจเต้นเร็ว ความดันโลหิตสูง การแข็งตัวของเลือด และออกซิเจนไม่ตรงกันที่ทำให้เกิดอาการบาดเจ็บหัวใจเฉียบพลันโรคพังผืดหรือกล้ามเนื้อหัวใจอักเสบที่มีอยู่ยังคงเป็นปัญหาทางการแพทย์ แต่การดูถูกโคเคนซ้ำแล้วซ้ำเล่าก็หมดไป\n\nการฟื้นฟูสมองด้วย\nภายในหนึ่งปี ระบบการให้รางวัลและการควบคุมตนเองได้ขยายเวลาในการฟื้นตัวขึ้น ซึ่งสนับสนุนการควบคุมแรงกระตุ้นที่ดีขึ้น อารมณ์ที่มั่นคงขึ้น และการตอบสนองต่อรางวัลในแต่ละวันมากขึ้น';

  @override
  String get cocaineReferenceDay730 =>
      'สองปีที่ไม่มีโคเคน: การฟื้นตัวอย่างยั่งยืน\n\nที่มา: \"การกู้คืนจากโคเคน: ข้อมูลเชิงลึกจากการสืบสวนทางคลินิกและพรีคลินิก\" บทวิจารณ์ด้านประสาทวิทยาศาสตร์และพฤติกรรมชีวภาพ (2013) บน PubMed Central\n\nมุมมองยาว\nการทบทวนนี้รวบรวมสิ่งที่การศึกษาของมนุษย์และสัตว์แสดงให้เห็นเกี่ยวกับการงดโคเคนเป็นเวลานานข้อสรุปหลักคือการรักษาและการฟื้นตัวของการทำงานของเปลือกสมองส่วนหน้าเป็นเครื่องหมายที่สำคัญที่สุดของการงดเว้นในระยะยาว ผู้งดเว้นระยะยาว (10 เดือนขึ้นไป) มีกิจกรรมของเปลือกสมองส่วนหน้าสูงกว่าผู้ที่งดเว้นในระยะสั้น\n\nสิ่งที่ยังคงรักษาอยู่\n• เครื่องหมายโดปามีนที่ถูกเปลี่ยนแปลงโดยโคเคนยังคงเคลื่อนตัวเข้าสู่ภาวะปกติโดยงดเว้นอย่างต่อเนื่อง\n• ความสมบูรณ์ของสารสีเทาและสีขาวที่ลดลงซึ่งพบเห็นได้ในผู้ใช้ที่กระตือรือร้นและผู้ที่งดเว้นตั้งแต่เนิ่นๆ อาจย้อนกลับผ่านการงดเว้นนานขึ้น อาจเกิดจากการที่เยื่อไมอีลินเติบโตอย่างต่อเนื่อง\n• วงจรควบคุมด้านหน้า — การควบคุมแรงกระตุ้น การตัดสิน การควบคุมอารมณ์ — แข็งแกร่งขึ้น\n\nสัญญาณการกู้คืน\nผู้เขียนขอเตือนทางวิทยาศาสตร์อย่างแท้จริง: ความแตกต่างบางประการของผู้งดเว้นในระยะยาวอาจสะท้อนถึง \"ผลของการรอดชีวิต\" คนที่เริ่มต้นด้วยความสมบูรณ์ของสมองมากขึ้นอาจพบว่าการงดเว้นนั้นง่ายกว่า แทนที่จะฟื้นตัวตามลำพังสิ่งที่ชัดเจนก็คือ การปราศจากโคเคนเป็นเวลา 2 ปีช่วยให้สมองทำงานได้ใกล้เคียงกับสมองของผู้ไม่ใช้มากขึ้น และชีวิตที่ไม่เพียงแต่งดเว้นเท่านั้น แต่ยังได้รับการสร้างขึ้นใหม่อย่างมากอีกด้วย';

  @override
  String get ghbReferenceDay1 =>
      'การถอนเงินของ GHB: ชั่วโมงแรก\n\nที่มา: \"ลักษณะเฉพาะของกลุ่มอาการถอน GHB\" บน PubMed Central\n\n⚠ นี่คือเหตุฉุกเฉินทางการแพทย์\nการถอน GHB จัดอยู่ในกลุ่มการถอนสารที่อันตรายที่สุด เทียบได้กับการถอนแอลกอฮอล์อย่างรุนแรงและการถอนเบนโซไดอะซีพีนหากไม่ได้รับการรักษา อาจมีอาการเพ้อมากขึ้นได้กว่าครึ่งหนึ่งของกรณี โดยมีอัตราการเต้นของหัวใจ ความดันโลหิต และอาการชักผันผวนที่เป็นอันตรายใครก็ตามที่ต้องใช้ GHB, GBL หรือ 1,4-บิวเทนไดออล ควรขอรับการดีท็อกซ์แบบผู้ป่วยในภายใต้การดูแล แทนที่จะหยุดเพียงลำพัง\n\nทำไมมันเริ่มเร็วมาก\nครึ่งชีวิตของ GHB อยู่ที่ 30–60 นาทีเท่านั้น และผู้ใช้ที่ต้องพึ่งยามักจะต้องโดสใหม่ทุกๆ 2–3 ชั่วโมงเพื่อหลีกเลี่ยงการถอนยา ซึ่งเร็วกว่าแอลกอฮอล์หรือเบนโซไดอะซีพีนมากเภสัชจลนศาสตร์ที่รวดเร็วนั้นเป็นเหตุผลว่าทำไมอาการจึงเกิดขึ้นได้เร็วกว่าการถอนยาระงับประสาทและสะกดจิต other\n\nอาการเบื้องต้น\nความวิตกกังวล นอนไม่หลับ อาการสั่น เหงื่อออก หัวใจเต้นเร็ว และความดันโลหิตเพิ่มขึ้น';

  @override
  String get ghbReferenceDay3 =>
      'การถอนเงินของ GHB: วันที่ยากที่สุด\n\nที่มา: \"ลักษณะเฉพาะของกลุ่มอาการถอน GHB\" บน PubMed Central\n\nการยืดที่ยากที่สุด\nการศึกษานี้พบว่าอาการหลักๆ หลายอย่างจากการถอนตัว ได้แก่ ปวดกล้ามเนื้อ กล้ามเนื้อกระตุก ความรู้สึกตึงเครียด หัวใจเต้นเร็ว และปวดท้อง โดยจะรุนแรงที่สุดในสามวันแรก โดยมีความรุนแรงลดลงมากกว่า 70% สำหรับอาการต่างๆ ภายในวันที่สี่โดยทั่วไปช่วงต้นนี้จะเป็นช่วงที่มีความเสี่ยงสูงสุด เมื่อการถอนตัวโดยไม่ได้รับการรักษามีแนวโน้มที่จะรุนแรงขึ้นจนมีอาการเพ้อ อาการลมชัก หรือการเปลี่ยนแปลงที่เป็นอันตรายของอัตราการเต้นของหัวใจและความดันโลหิต\n\nคุณสมบัติที่รุนแรง\n• กระสับกระส่ายและวิตกกังวลอย่างรุนแรง\n• ภาพหลอนทางการได้ยินและภาพ หวาดระแวง\n• อาการสั่น เหงื่อออก หัวใจเต้นแรง และความดันโลหิตสูง\n• เสี่ยงต่ออาการชัก\n\nการจัดการ\nการศึกษานี้อธิบายว่าการลดขนาดเบนโซไดอะซีพีนและการลดขนาด GHB ทางเภสัชกรรมเป็นวิธีการล้างพิษสองวิธีที่ใช้กันทั่วไป โดยสังเกตหลักฐานบางประการที่บ่งชี้ว่าการลดขนาด GHB อาจควบคุมอาการได้อย่างมีประสิทธิภาพมากกว่าการใช้ยาเบนโซไดอะซีพีนเพียงอย่างเดียวทั้งสองวิธีจำเป็นต้องมีการตรวจสอบอย่างใกล้ชิด ซึ่งไม่ปลอดภัยในการจัดการที่บ้าน';

  @override
  String get ghbReferenceDay7 =>
      'หยุดหนึ่งสัปดาห์ GHB\n\nที่มา: \"ลักษณะเฉพาะของกลุ่มอาการถอน GHB\" บน PubMed Central\n\nอาการส่วนใหญ่จะจางลง\nอาการถอนยาหลักหลายอย่างลดลงมากกว่า 70% ในด้านความรุนแรงหรือความชุกภายในสี่วันแรกภายใต้การดูแลให้เรียวลง ระยะการเรียวนั้นกินเวลาโดยเฉลี่ย 11 วัน ตามด้วยระยะการฟื้นตัวประมาณหกวัน ดังนั้นภายในหนึ่งสัปดาห์ ผู้คนจำนวนมากก็เข้าสู่การปรับปรุงดังกล่าว แม้ว่ากระบวนการจะยังไม่เสร็จสิ้นอย่างสมบูรณ์ก็ตาม\n\nสิ่งที่สามารถอิทธิพลได้\n• เหงื่อออก ตัวสั่น และมือสั่น\n• นอนมากหรือในทางกลับกัน นอนไม่หลับและกระสับกระส่าย\n• ความอยากอาหาร\n\nการศึกษาพบว่าอาการเฉพาะเหล่านี้เปลี่ยนแปลงเพียงเล็กน้อยแม้แต่ในช่วง 11 วัน ดังนั้นการคงอยู่ในสัปดาห์นี้จึงไม่ใช่เรื่องผิดปกติการกำกับดูแลทางการแพทย์อย่างต่อเนื่องยังคงมีความสำคัญจนกว่ากลุ่มอาการจะคลี่คลายลงอย่างชัดเจน';

  @override
  String get ghbReferenceDay14 =>
      'GHB หยุดสองสัปดาห์\n\nที่มา: \"ลักษณะเฉพาะของกลุ่มอาการถอน GHB\" บน PubMed Central\n\nผ่านอาการเฉียบพลัน\nเมื่อผ่านไปสองสัปดาห์ อาการทางกายภาพเฉียบพลันที่อธิบายไว้ในการศึกษานี้ ซึ่งมีระยะการค่อยๆ ลดลงและการฟื้นตัวรวมกันโดยเฉลี่ยประมาณ 17 วันภายใต้การรักษาภายใต้การดูแล โดยทั่วไปจะได้รับการแก้ไขหรือใกล้เคียงมากอัตราการเต้นของหัวใจ ความดันโลหิต และอาการทางร่างกายส่วนใหญ่ควรจะคงที่\n\nสิ่งที่ยังคงอยู่\nการศึกษานี้บ่งชี้ถึงความอยากและการนอนไม่หลับโดยเฉพาะ เนื่องจากยังคงมีผู้ป่วยบางรายออกจากโรงพยาบาล โดยสังเกตว่าสิ่งเหล่านี้อาจทำให้เกิดความเสี่ยงในการกลับเป็นซ้ำได้การสนับสนุนและโครงสร้างมีความสำคัญในขณะนี้ แม้ว่าช่วงเริ่มต้นที่เป็นอันตรายจะอยู่ข้างหลังคุณก็ตาม';

  @override
  String get ghbReferenceDay30 =>
      'ลด 1 เดือน GHB\n\nที่มา: \"ลักษณะเฉพาะของกลุ่มอาการถอน GHB\" บน PubMed Central\n\nที่ซึ่งหนึ่งเดือนนั่งอยู่\nระยะเฉียบพลันและอันตรายที่อธิบายไว้ในการศึกษานี้ผ่านไปนานหนึ่งเดือนแล้วเมื่อผ่านไปหนึ่งเดือน ระยะอันตรายเฉียบพลันซึ่งกระจุกตัวอยู่ในวันแรก ตามมาด้วยระยะค่อยๆ ลดลงและฟื้นตัวโดยมีผู้ดูแลซึ่งโดยเฉลี่ยประมาณสองสัปดาห์ครึ่ง ก็ได้ผ่านไปนานแล้วความอยากและการนอนไม่หลับเป็นความเสี่ยงที่สำคัญในการกลับเป็นซ้ำซึ่งระบุได้เมื่อออกจากโรงพยาบาล\n\nเหตุใดการสนับสนุนจึงยังช่วยได้\nหากความอยาก อารมณ์ไม่ดี หรือปัญหาการนอนหลับยังคงมีอยู่ในหนึ่งเดือน นั่นก็สอดคล้องกับสิ่งที่ผู้เขียนรายงานการศึกษาระบุว่าเป็นปัจจัยเสี่ยงในการกลับเป็นซ้ำ ซึ่งเป็นเหตุผลว่าทำไมการสนับสนุนและโครงสร้างอย่างต่อเนื่องจึงมีความสำคัญ';

  @override
  String get ghbReferenceDay90 =>
      'GHB ลดสามเดือน\n\nที่มา: \"ลักษณะเฉพาะของกลุ่มอาการถอน GHB\" บน PubMed Central\n\nสามเดือนแห่งการฟื้นฟู\nภายในสามเดือน อาการถอน GHB เฉียบพลันจะได้รับการแก้ไขเป็นเวลานานความเสี่ยงที่เหลืออยู่ที่ระบุเมื่อออกจากโรงพยาบาลคือความอยากและการนอนไม่หลับ ดังนั้นการงดเว้นเป็นเวลา 3 เดือนจะช่วยให้นอนหลับได้ เสถียรภาพของระบบอัตโนมัติ และกิจวัตรการป้องกันอาการกำเริบของโรค ทำให้มีเวลามากพอสมควรในการรวมตัว\n\nสิ่งที่ผู้คนมักรายงาน\n• อารมณ์ปกติสงบขึ้น\n• การนอนหลับที่เชื่อถือได้มากขึ้น\n• คิดชัดเจนขึ้นและความอยากน้อยลง\n\nหากความวิตกกังวล นอนไม่หลับ หรืออารมณ์ไม่ดียังคงเด่นชัดในสามเดือน ก็ควรปรึกษากับแพทย์ แทนที่จะคิดว่าจะคลี่คลายไปเอง';

  @override
  String get ghbReferenceDay180 =>
      'ลด 6 เดือน GHB\n\nที่มา: \"ลักษณะเฉพาะของกลุ่มอาการถอน GHB\" บน PubMed Central\n\nครึ่งปีแล้ว\nภายในหกเดือน กลุ่มอาการถอน GHB เฉียบพลันจะได้รับการแก้ไขเป็นเวลานาน และการฟื้นตัวได้เปลี่ยนจากการล้างพิษไปสู่การนอนหลับที่มั่นคง การควบคุมความอยาก และการป้องกันการกำเริบของโรคระยะอัตโนมัติและอาการเพ้อที่เป็นอันตรายเป็นของวันแรกและสัปดาห์แรก ไม่ใช่ระยะนี้\n\nภาพใหญ่ขึ้น\nการถอนตัวจาก GHB อย่างปลอดภัยและการพักรักษาตัวเป็นเวลาครึ่งปีถือเป็นความสำเร็จครั้งสำคัญ เมื่อพิจารณาว่าช่วงแรกๆ นั้นอันตรายแค่ไหน และความเสี่ยงในการกลับเป็นซ้ำของโรคนั้นเกิดขึ้นจริงเพียงใด ซึ่งส่วนหนึ่งได้รับแรงหนุนจากความอยากที่ยืดเยื้อและการนอนไม่หลับกิจวัตรและการสนับสนุนที่นำคุณมาที่นี่นั้นคุ้มค่าที่จะเก็บไว้';

  @override
  String get inhalantsReferenceDay1 =>
      'การหยุดการสูดดม: วันแรก\n\nที่มา: Radparvar, \"การประเมินทางคลินิกและการรักษาการละเมิดด้วยการสูดดม\" The Permanente Journal (2023) บน PubMed Central\n\nเหตุใดการถอนเงินจึงเกิดขึ้น\nการใช้ยาสูดดมเรื้อรังทำให้เกิดการปรับตัวของระบบประสาท - ระบบประสาทจะคาดหวังสารนี้การสูดดมหลายชนิดส่งผลต่อวงจรสมองเช่นเดียวกับแอลกอฮอล์ ดังนั้นการหยุดทำให้สมองไม่สมดุลชั่วคราวสารเคมีล้างเลือดอย่างรวดเร็วแต่ถูกเก็บไว้ในไขมันในร่างกาย ซึ่งทำให้ไม่สามารถคาดเดาระยะเวลาในการถอนได้\n\nอาการเบื้องต้น\nการทบทวนนี้อธิบายถึงการถอนยาสูดดมคล้ายกับการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีน โดยมีอาการตามรายงาน ได้แก่:\n• คลื่นไส้ อาเจียน และเหงื่อออก\n• อาการสั่นและหัวใจเต้นเร็ว\n• นอนไม่หลับและรบกวนการนอนหลับ\n• ความวิตกกังวลและหงุดหงิด\n\nหมายเหตุด้านความปลอดภัย\nในกรณีที่รุนแรงกว่านั้น การทบทวนยังแสดงรายการอาการประสาทหลอน อาการหลงผิด และอาการชักในอาการที่รายงานด้วย แม้ว่าจะไม่ได้กำหนดตารางเวลาในแต่ละวันอย่างแม่นยำก็ตาม ให้ถือว่าอาการเหล่านี้เป็นอาการที่อาจเกิดขึ้นได้ ไม่ใช่กำหนดเวลาที่แน่นอนการดูแลทางการแพทย์เป็นสิ่งที่ชาญฉลาดในระหว่างการดีท็อกซ์ โดยเฉพาะอย่างยิ่งสำหรับผู้ใช้ที่มีน้ำหนักมากในระยะยาว';

  @override
  String get inhalantsReferenceDay7 =>
      'การสูดดมหนึ่งสัปดาห์\n\nที่มา: Radparvar, \"การประเมินทางคลินิกและการรักษาการละเมิดด้วยการสูดดม\" The Permanente Journal (2023) บน PubMed Central\n\nหน้าต่างเฉียบพลัน\nการถอนยาโดยการสูดดมมีการอธิบายไว้ในเอกสารทางคลินิกว่าคล้ายกับการถอนแอลกอฮอล์หรือการถอนเบนโซไดอะซีพีน แต่โดยทั่วไปเป็นที่เข้าใจกันว่ามีอายุสั้นกว่าเมื่อสิ้นสุดสัปดาห์แรก อาการทางกายภาพเฉียบพลัน เช่น คลื่นไส้ ตัวสั่น เหงื่อออก นอนไม่หลับ มักจะหายไปในคนส่วนใหญ่\n\nสิ่งที่เหลืออยู่\n• เหนื่อยล้าและมีหมอกในสมอง\n• อารมณ์ต่ำหรือไม่มั่นคง\n• ความอยากอาหาร\n\nหมายเหตุเกี่ยวกับการเลิกบุหรี่ตั้งแต่เนิ่นๆ\nหมอกสมองในระยะนี้ไม่ได้หมายถึงความเสียหายถาวร — สมองยังคงปรับตัวอยู่การวิจัยเกี่ยวกับวิธีการฟื้นตัวของความคิดและความทรงจำโดยเฉพาะในช่วงสัปดาห์และเดือนต่อๆ ไปจะกล่าวถึงในเหตุการณ์สำคัญต่อๆ ไป';

  @override
  String get inhalantsReferenceDay14 =>
      'ยาสูดพ่นหยุดสองสัปดาห์\n\nที่มา: Radparvar, \"การประเมินทางคลินิกและการรักษาการละเมิดด้วยการสูดดม\" The Permanente Journal (2023) บน PubMed Central\n\nผ่านระยะเฉียบพลัน\nการทบทวนทางคลินิกอธิบายว่าการถอนยาสูดดมมีความคล้ายคลึงกับการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีน แต่สั้นกว่าภายในสองสัปดาห์ อาการคลื่นไส้ อาการสั่น นอนไม่หลับ และวิตกกังวลจะคลี่คลายลง\n\nถนนข้างหน้า\nความสนใจ ความจำ การเคลื่อนไหว และการประสานงานจะค่อยๆ ฟื้นตัวมากขึ้นในช่วงหลายเดือนต่อๆ ไปการงดเว้นอย่างต่อเนื่องจะทำให้ระบบทั้งหมดเหล่านี้มีเวลาในการปรับปรุงโภชนาการที่ดี (การสูดดมอาจทำให้วิตามินบี 12 หมดสิ้นได้) และการเลิกบุหรี่เป็นเหตุให้เกิดวิตามินบี 12';

  @override
  String get inhalantsReferenceDay30 =>
      'ระงับการสูดดมหนึ่งเดือน\n\nที่มา: Dingwall และคณะ \"การฟื้นตัวของความรู้ความเข้าใจระหว่างและหลังการรักษาการใช้ตัวทำละลายระเหยในทางที่ผิด\" การพึ่งพายาและแอลกอฮอล์ (2011) บน PubMed\n\nที่ซึ่งหนึ่งเดือนนั่งอยู่\nระยะเวลาการถอนเงินก่อนกำหนดนั้นรอคุณอยู่ในการศึกษานี้ ทักษะการเรียนรู้บางอย่างพัฒนาขึ้นภายในหกสัปดาห์ ในขณะที่การประสานงานด้านการมองเห็น ความจำ การวางแผน และการตัดสินใจจะค่อยๆ พัฒนาขึ้นในช่วงเดือนต่อๆ มา\n\nสิ่งที่สามารถปรับปรุงได้\n• ความสนใจและงานการเรียนรู้บางอย่าง\n• อารมณ์และการนอนหลับตามที่ร่างกายทรงตัว\n• ความเร็วมอเตอร์ค่อยๆ\n\nสัญญาณการกู้คืน\nข้อสรุปของการศึกษานี้ชัดเจน: ความจำ การวางแผน และการตัดสินใจจะค่อยๆ ดีขึ้นในช่วงหลายเดือนหรือหลายปีของการเลิกบุหรี่การงดเว้นอย่างต่อเนื่องเป็นตัวขับเคลื่อนที่แข็งแกร่งที่สุดของการฟื้นตัว';

  @override
  String get inhalantsReferenceDay90 =>
      'สารสูดดมปิดสามเดือน\n\nที่มา: Dingwall และคณะ \"การฟื้นตัวของความรู้ความเข้าใจระหว่างและหลังการรักษาการใช้ตัวทำละลายระเหยในทางที่ผิด\" การพึ่งพายาและแอลกอฮอล์ (2011) บน PubMed\n\nกระบวนการที่ไม่สม่ำเสมอและยาวนานกว่า\nการศึกษานี้ติดตามผู้คนที่นอกเหนือจากโปรแกรมการรักษาแปดสัปดาห์ และตรวจดูบางคนอีกครั้งในอีกหนึ่งปีต่อมาทักษะการเรียนรู้บางอย่างพัฒนาขึ้นภายในหกสัปดาห์ ในขณะที่การประสานงานด้านการมองเห็น ความจำ การวางแผน และการตัดสินใจดีขึ้นอย่างต่อเนื่องในระยะเวลานานขึ้น\n\nอยู่ในหลักสูตร\nผลการศึกษาแสดงให้เห็นว่าทักษะที่ช้ากว่าจะค่อยๆ พัฒนาขึ้นในช่วงหลายเดือนถึงหลายปีเมื่อถึงสามเดือน การงดเว้นอย่างต่อเนื่องเป็นหนทางที่แข็งแกร่งที่สุดในการเพิ่มการฟื้นตัวเดือนแล้วเดือนเล่า';

  @override
  String get inhalantsReferenceDay365 =>
      'หนึ่งปีปิดการสูดดม\n\nที่มา: \"การศึกษาในอนาคตเกี่ยวกับการเปลี่ยนแปลงทางระบบประสาทรับรู้ 15 ปีหลังจากการสูดดมในทางที่ผิด\" บน PubMed\n\nการฟื้นฟูที่วัดผลได้จริง\nการศึกษาระยะยาวพบว่าการฟื้นตัวอย่างมีนัยสำคัญจากสมองที่เกี่ยวข้องกับการสูดดมเรื้อรังและปัญหาการคิดหลังจากการงดเว้นเป็นเวลาสองปีในหนึ่งปี คุณก็อยู่ในเส้นทางการฟื้นฟูที่ดี\n\nมันหมายถึงอะไร\nหน่วยความจำ ความสนใจ และการทำงานของมอเตอร์ได้รับการปรับปรุงอย่างต่อเนื่องการงดเว้นระยะยาวจะทำให้สมองฟื้นตัวอย่างแท้จริง ภายในสองปี คะแนนสมอง ความจำ และการคิดส่วนใหญ่กลับมาเป็นปกติในผู้ใช้เรื้อรังที่ไม่มีความเสียหายต่อสมองจากสารตะกั่ว';

  @override
  String get inhalantsReferenceDay730 =>
      'สองปีที่สารสูดดม\n\nที่มา: \"การศึกษาในอนาคตเกี่ยวกับการเปลี่ยนแปลงทางระบบประสาทรับรู้ 15 ปีหลังจากการสูดดมในทางที่ผิด\" บน PubMed\n\nเครื่องหมายสองปี\nนี่คือหลักชัยสำคัญในการวิจัย: การขาดดุลซึ่งสะท้อนถึงความเสียหายของสมองจากการใช้ตัวทำละลายในระยะยาว แสดงให้เห็นการฟื้นตัวอย่างมีนัยสำคัญหลังจากการเลิกบุหรี่เป็นเวลาสองปีผู้เขียนสรุปว่าหากไม่มีความเสียหายต่อสมองจากน้ำมันที่มีสารตะกั่ว การงดเว้นในระยะยาวอาจทำให้สมองฟื้นตัวได้เป็นปกติ\n\nสัญญาณการกู้คืน\nข้อยกเว้นที่สำคัญคือความเสียหายจากการใช้น้ำมันที่มีสารตะกั่วในทางที่ผิด ซึ่งอาจทำให้เกิดการขาดดุลอย่างต่อเนื่องไม่เช่นนั้น การงดเว้นเป็นเวลา 2 ปีถือเป็นโอกาสที่ดีที่สุดของสมองในการรักษา ควบคู่ไปกับชีวิตที่สร้างขึ้นใหม่โดยรอบ';

  @override
  String get ketamineReferenceDay1 =>
      'การหยุดคีตามีน: วันแรก\n\nที่มา: \"โรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีน: การทบทวนผลทางระบบทางเดินปัสสาวะของยาออกฤทธิ์ต่อจิตประสาทนี้อย่างครอบคลุม\" บน PubMed Central\n\nการถอนตัวเป็นเรื่องทางจิตวิทยาเป็นหลัก\nคีตามีนแตกต่างจากฝิ่นหรือแอลกอฮอล์ตรงที่ไม่ค่อยทำให้เกิดการถอนตัวอย่างรุนแรงโดยทั่วไปการเลิกใช้งานจะปลอดภัยผู้คนมักต่อสู้กับความอยากและการพึ่งพาทางจิตใจมากกว่าความเจ็บป่วยทางกาย\n\nสิ่งที่คุณอาจรู้สึก\n• อารมณ์แปรปรวนและอารมณ์ต่ำ\n• ความอยากอาหาร\n• เหงื่อออกหรือใจสั่นเป็นครั้งคราว\n\nขั้นตอนที่สำคัญ\nสำหรับผู้ที่มีอาการกระเพาะปัสสาวะ การหยุดทันทีและโดยสมบูรณ์เป็นจุดเริ่มต้นที่จำเป็นในการฟื้นตัว ดังนั้นวันแรกจึงเป็นการตัดสินใจที่สำคัญที่สุด';

  @override
  String get ketamineReferenceDay7 =>
      'หยุดคีตามีนหนึ่งสัปดาห์\n\nที่มา: \"โรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีน: บทวิจารณ์ที่ครอบคลุม\" บน PubMed Central\n\nระยะจิตวิทยา\nความท้าทายหลักในการเลิกคีตามีนตั้งแต่เนิ่นๆ อยู่ที่ด้านจิตวิทยา ได้แก่ ความอยาก อารมณ์แปรปรวนหรือต่ำ และหมอกในสมองบางส่วนการถอนตัวทางกายภาพ (หากมี) มักจะไม่รุนแรง\n\nอาการหมอกในสมองเป็นเรื่องปกติในระยะนี้ — สมาธิรู้สึกต้องใช้ความพยายาม เวลาตอบสนองช้าลง และความจำระยะสั้นอาจรู้สึกไม่น่าเชื่อถือผลเหล่านี้ต่อการคิดและความจำดีขึ้นเมื่อเลิกบุหรี่: การศึกษาระยะยาวของผู้ใช้คีตามีน 114 ราย พบว่าความจำทางวาจา ความจำภาพ ความเร็วในการประมวลผล และการวางแผน การโฟกัส และการตัดสินใจเพิ่มขึ้นอย่างมีนัยสำคัญหลังจากผ่านไป 12 สัปดาห์โดยไม่ใช้คีตามีน\n\nอาการกระเพาะปัสสาวะ\nหากคุณเป็นโรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีน (ปัสสาวะเร่งด่วน ความถี่ ความเจ็บปวด หรือมีเลือดในปัสสาวะ) การหยุดทันทีจะทำให้กระเพาะปัสสาวะมีโอกาสหายดีที่สุดความเจ็บปวดสามารถดึงดูดผู้คนให้กลับมารับประทานคีตามีนเพื่อรักษาตัวเอง ซึ่งเป็นวงจรที่คุ้มค่าที่จะทำลายด้วยการสนับสนุนความเจ็บปวดที่เหมาะสมแทน';

  @override
  String get ketamineReferenceDay14 =>
      'สองสัปดาห์ปิดคีตามีน\n\nที่มา: \"โรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีน: บทวิจารณ์ที่ครอบคลุม\" บน PubMed Central\n\nการคิดที่ชัดเจนยิ่งขึ้น\nเมื่อยาหายไปหมด หมอกทางจิตและความคิดที่ขาดการเชื่อมต่อที่เกี่ยวข้องกับการใช้คีตามีนเป็นประจำจะเริ่มดีขึ้นความจำและสมาธิดีขึ้น และอารมณ์คงที่\n\nการเริ่มต้นการกู้คืนกระเพาะปัสสาวะ\nสำหรับโรคกระเพาะปัสสาวะอักเสบในระยะเริ่มแรก การทบทวนเน้นย้ำว่าการหยุดคีตามีนเป็นขั้นตอนที่สำคัญที่สุดเพียงขั้นตอนเดียวในการทำให้อาการกลับมาเป็นปกติ และการหยุดก่อนกำหนดจะมีโอกาสฟื้นตัวได้ดีที่สุด ก่อนที่ความเสียหายจะถาวรการงดเว้นเป็นเวลาสองสัปดาห์เป็นจุดเริ่มต้นของกระบวนการนั้น';

  @override
  String get ketamineReferenceDay30 =>
      'ลดคีตามีนหนึ่งเดือน\n\nที่มา: \"ความชุกและประวัติทางธรรมชาติของอาการทางเดินปัสสาวะในกลุ่มผู้ใช้คีตามีนเพื่อสันทนาการ\" Winstock และคณะ, BJU International (2012)\n\nการกู้คืนกระเพาะปัสสาวะ\nการรักษาที่สำคัญที่สุดสำหรับโรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีนคือการหยุดคีตามีนการศึกษาผู้ใช้คีตามีนเพื่อการพักผ่อนหย่อนใจนี้พบว่า 51% ของผู้ที่มีอาการทางเดินปัสสาวะรายงานว่าอาการดีขึ้นหลังจากหยุดใช้ ในขณะที่น้อยกว่า 4% อาการแย่ลงหยุดเร็วเท่าไหร่ ผลลัพธ์ก็จะยิ่งดีขึ้นเท่านั้น\n\nจิตใจและอารมณ์\nการรับรู้และอารมณ์ยังคงชัดเจนในหนึ่งเดือนการสนับสนุนด้านจิตวิทยาและสังคมช่วยเพิ่มโอกาสที่จะหยุดอยู่ได้อย่างมีนัยสำคัญ การหยุดจะได้ผลดีที่สุดเมื่อได้รับการสนับสนุน';

  @override
  String get ketamineReferenceDay90 =>
      'ลดคีตามีนสามเดือน\n\nที่มา: \"โรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีน: บทวิจารณ์ที่ครอบคลุม\" บน PubMed Central\n\nการกู้คืนอย่างต่อเนื่อง\nการฟื้นตัวของกระเพาะปัสสาวะหลังจากคีตามีนมักจะค่อยเป็นค่อยไปการทบทวนนี้อธิบายถึงความรุนแรงของอาการที่ดีขึ้นหลังการหยุดยา แม้ว่าอาจยืดเยื้อและแปรผันได้ก็ตามสามเดือนทำให้ระบบทางเดินปัสสาวะมีเวลาในการรักษาอย่างต่อเนื่องในกรณีที่จะต้องตอบสนอง\n\nใจ\nความคิดและอารมณ์ที่ชัดเจนชัดเจนกว่าการงดเว้นตั้งแต่เนิ่นๆ และความอยากเกิดขึ้นน้อยกว่าอาการกระเพาะปัสสาวะเรื้อรังหรือรุนแรงควรได้รับการประเมินโดยผู้เชี่ยวชาญด้านระบบทางเดินปัสสาวะ';

  @override
  String get ketamineReferenceDay180 =>
      'ลดคีตามีนหกเดือน\n\nที่มา: \"โรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีน: บทวิจารณ์ที่ครอบคลุม\" บน PubMed Central\n\nครึ่งปีแล้ว\nหากงดเว้นอย่างต่อเนื่อง อาการของกระเพาะปัสสาวะจะดีขึ้นอย่างต่อเนื่องในกรณีที่ตอบสนองต่อการเลิกบุหรี่ และการคิด ความจำ และอารมณ์จะคงที่แรงผลักดันในการใช้ลดลงอย่างมาก\n\nสัญญาณการกู้คืน\nการฟื้นตัวของความเสียหายที่กระเพาะปัสสาวะที่เกิดขึ้นนั้นอาจไม่สมบูรณ์ ซึ่งเป็นเหตุผลว่าทำไมการหยุดก่อนกำหนดจึงมีความสำคัญมากไม่ว่าคุณจะหยุดในระยะใดก็ตาม การงดเว้นจะทำให้กระเพาะปัสสาวะได้ผลดีที่สุด';

  @override
  String get ketamineReferenceDay365 =>
      'ลดคีตามีนหนึ่งปี\n\nที่มา: \"โรคกระเพาะปัสสาวะอักเสบที่เกิดจากคีตามีน: บทวิจารณ์ที่ครอบคลุม\" บน PubMed Central\n\nหนึ่งปีผ่านไป\nการงดเว้นเป็นเวลา 12 เดือนจะทำให้กระเพาะปัสสาวะมีโอกาสฟื้นตัวอย่างเต็มที่ และทำให้ความคิด ความจำ และอารมณ์คงที่และชัดเจนการพึ่งพาอาศัยกันทางจิตวิทยาที่ทำให้การหยุดอย่างหนักได้จางหายไปอย่างมาก\n\nภาพใหญ่ขึ้น\nการใช้บริการฟรีหนึ่งปีคือการเปลี่ยนแปลงครั้งใหญ่ ทั้งในด้านสุขภาพกาย ความชัดเจน และการกำกับตนเองการรักษาการสนับสนุนที่พาคุณมาที่นี่จะช่วยปกป้องมัน';

  @override
  String get kratomReferenceDay1 =>
      'การถอนกระท่อม: วันแรก\n\nที่มา: Swogger และคณะ(2022), \"การทำความเข้าใจการใช้กระท่อม: คู่มือสำหรับผู้ให้บริการด้านสุขภาพ\" ขอบเขตทางเภสัชวิทยา\n\nเหตุใดการถอนเงินจึงเกิดขึ้น\nสารประกอบออกฤทธิ์ของกระท่อมออกฤทธิ์กับตัวรับฝิ่นแบบเดียวกับฝิ่นแบบคลาสสิกเมื่อใช้เป็นประจำร่างกายจะปรับตัว ดังนั้นการหยุดจะทำให้เกิดอาการถอนยาคล้ายฝิ่นคู่มือทางคลินิกนี้อธิบายถึงการพึ่งพาและการถอนตัวเป็นความเสี่ยงที่ได้รับการยอมรับจากการใช้กระท่อมเป็นประจำ\n\nสิ่งที่แสดงหลักฐานเกี่ยวกับการโจมตี\nการศึกษาในสัตว์ทดลองที่อ้างถึงในคู่มือนี้แสดงสัญญาณการถอนตัวของร่างกายที่เกิดขึ้นภายในประมาณ 12 ชั่วโมง โดยจะมีอาการคล้ายความวิตกกังวลชัดเจนภายใน 24 ชั่วโมงระยะเวลาการโจมตีของมนุษย์ที่แม่นยำนั้นไม่ค่อยมีการกำหนดไว้ แต่อาการเริ่มแรกที่มีการรายงานโดยทั่วไป ได้แก่:\n• กระสับกระส่าย วิตกกังวล และหงุดหงิด\n• ปวดกล้ามเนื้อและมีน้ำมูกไหล\n• เหงื่อออกและมีน้ำตาไหล\n• ความอยากอาหาร\n\nหมายเหตุเกี่ยวกับความรุนแรง\nคู่มือตั้งข้อสังเกตว่าระยะเวลาการใช้ยานานขึ้นและปริมาณที่สูงขึ้นเชื่อมโยงกับการถอนยาที่รุนแรงและยาวนานขึ้นการสนับสนุนทางการแพทย์ภายใต้การดูแลเป็นสิ่งที่ควรค่าแก่การแสวงหา โดยเฉพาะอย่างยิ่งหากใช้กระท่อมในขนาดสูงหรือร่วมกับฝิ่น';

  @override
  String get kratomReferenceDay3 =>
      'การถอนกระท่อม: วันที่ยากที่สุด\n\nที่มา: Singh และคณะ(2014), การติดยาเสพติดและแอลกอฮอล์ - การสำรวจผู้ใช้กระท่อมปกติ 293 รายในมาเลเซีย\n\nสิ่งที่แสดงหลักฐาน\nแทนที่จะเป็น \'วันเร่งด่วน\' ที่ระบุเพียงวันเดียว การสำรวจนี้พบว่าความรุนแรงของการถอนยาติดตามว่ามีคนใช้กระท่อมมากน้อยเพียงใดและนานแค่ไหน โดยผู้ที่ดื่มกระท่อมตั้งแต่ 3 แก้วขึ้นไปต่อวัน มีโอกาสสูงที่จะติดยาเสพติดขั้นรุนแรงและถอนยาได้ยากขึ้นอย่างมีนัยสำคัญสำหรับคนส่วนใหญ่ ช่วง 2-3 วันแรกหลังจากหยุดจะเป็นช่วงที่ยากที่สุด\n\nอาการที่พบบ่อย\n• ปวดกล้ามเนื้อและข้อ ขากระสับกระส่าย\n• นอนไม่หลับแม้จะอ่อนเพลีย\n• คลื่นไส้ ปวดท้อง และท้องร่วง\n• ความวิตกกังวล อารมณ์ไม่ดี และหงุดหงิด\n• ความอยากอาหารอย่างรุนแรง\n\nการผ่านมันไป\nการให้น้ำ การพักผ่อน และการสนับสนุนตามอาการหากการถอนออกรู้สึกรุนแรงจนถึงตอนนี้ นั่นก็สอดคล้องกับการใช้ที่หนักกว่าหรือนานกว่า แทนที่จะเป็นสิ่งที่ผิดปกติผิดปกติ และมีแนวโน้มจะผ่อนคลายลงจากจุดนี้';

  @override
  String get kratomReferenceDay7 =>
      'กระท่อมหนึ่งสัปดาห์\n\nที่มา: Swogger และคณะ(2022), \"การทำความเข้าใจการใช้กระท่อม: คู่มือสำหรับผู้ให้บริการด้านสุขภาพ\" ขอบเขตทางเภสัชวิทยา\n\nผ่านระยะเฉียบพลัน\nข้อมูลการรายงานตนเองของมนุษย์ที่อ้างถึงในคู่มือนี้ระบุว่าอาการถอนยาจะได้รับการแก้ไขภายในประมาณหนึ่งถึงสามวันสำหรับคนส่วนใหญ่ที่หยุดยาภายในหนึ่งสัปดาห์ อาการทางกายภาพเฉียบพลัน เช่น ปวดกล้ามเนื้อ เหงื่อออก และคลื่นไส้ มักจะคลี่คลายลงสำหรับคนส่วนใหญ่สิ่งที่ยังคงอยู่ได้คือสภาพจิตใจ: ความเหนื่อยล้า การนอนหลับที่หยุดชะงัก และอารมณ์ไม่ดีเนื่องจากกระท่อมของตัวรับฝิ่นถูกกระตุ้นให้ปรับตัวกลับสู่สัญญาณของร่างกาย\n\nความเสี่ยงที่แท้จริง\nคู่มือยังตั้งข้อสังเกตด้วยว่ามีคนจำนวนไม่มากที่พบว่าเลิกกระท่อมได้ยาก โดยมีรายงานการถอนกระท่อมที่รุนแรงและยาวนานกว่าในกลุ่มผู้ใช้ที่หนักกว่าและระยะยาวสัปดาห์นี้เป็นจุดที่พบบ่อยของการกำเริบของโรค และความอดทนลดลงอย่างรวดเร็ว การกลับไปใช้ยาขนาดเดิม โดยเฉพาะอย่างยิ่งหากเกี่ยวข้องกับฝิ่น ถือเป็นอันตรายอย่างแท้จริง';

  @override
  String get kratomReferenceDay14 =>
      'สองสัปดาห์ปิดกระท่อม\n\nที่มา: สถาบันป้องกันยาเสพติดแห่งชาติ (NIDA), \"กระท่อม\"\n\nเกินหน้าต่างการศึกษา\nข้อมูลของมนุษย์ที่ได้รับการควบคุมเกี่ยวกับระยะเวลาในการถอนกระท่อมโดยทั่วไปจะครอบคลุมเฉพาะช่วงสองสามวันแรกเท่านั้น ดังนั้นจึงยังไม่มีงานวิจัยที่น่าเชื่อถือที่ปักหมุดเหตุการณ์สำคัญ \"สองสัปดาห์\" ที่เฉพาะเจาะจงได้สิ่งที่บันทึกไว้คือรูปแบบที่กว้างขึ้น โดยกระท่อมทำหน้าที่กับตัวรับฝิ่นแบบเดียวกับฝิ่นแบบคลาสสิก และเนื่องจากการใช้เป็นประจำจะหยุดตัวรับเหล่านั้นจะค่อยๆ คืนความไวต่อสัญญาณของร่างกาย\n\nสิ่งที่ผู้คนมักรายงาน\n• ความอยากอาหารและพลังงานมักจะดีขึ้น\n• การนอนหลับมีแนวโน้มที่จะเชื่อถือได้มากขึ้น\n• โดยทั่วไปแล้วอารมณ์จะคงที่มากขึ้น แต่ยังคงแปรปรวนอยู่\n\nความอยากยังคงถูกกระตุ้นโดยความเครียดและสัญญาณที่คุ้นเคย ดังนั้นการวางแผนสำหรับสิ่งเหล่านั้นยังคงมีประโยชน์';

  @override
  String get kratomReferenceDay30 =>
      'งดกระท่อมหนึ่งเดือน\n\nที่มา: สถาบันป้องกันยาเสพติดแห่งชาติ (NIDA), \"กระท่อม\"\n\nการกู้คืนระบบรางวัล\nNIDA อธิบายว่ากระท่อมทำหน้าที่ต่อตัวรับฝิ่นในสมอง โดยการใช้อย่างต่อเนื่องและการถอนออกถือเป็นความเสี่ยงจากการใช้เป็นประจำไม่มีการศึกษาที่เฉพาะเจาะจงเกี่ยวกับเหตุการณ์สำคัญในการฟื้นตัว \"หนึ่งเดือน\" แต่รูปแบบทั่วไปของการพึ่งพาสารฝิ่นคือการตอบสนองของสมองต่อความสุขในชีวิตประจำวันจะค่อยๆ เป็นปกติด้วยการเลิกบุหรี่อย่างต่อเนื่อง\n\nเงินเดือนหนึ่งเดือนสามารถสร้างได้\nเดือนที่ไม่มีกระท่อมคือเดือนแห่งการนอนหลับ การรับประทานอาหาร และกิจวัตรประจำวันอย่างสม่ำเสมอ เพื่อทดแทนเวลาและแรงกายที่จำเป็นความอยากมักเกิดขึ้นไม่บ่อยนักและรู้สึกควบคุมได้ง่ายกว่า แม้ว่าช่วงเวลาที่มีความเครียดสูงยังคงเป็นช่วงที่อ่อนแอที่สุดก็ตาม';

  @override
  String get kratomReferenceDay90 =>
      'งดกระท่อมสามเดือน\n\nที่มา: สถาบันป้องกันยาเสพติดแห่งชาติ (NIDA), \"กระท่อม\"\n\nสถานะวันต่อวันที่มั่นคงยิ่งขึ้น\nพืชกระท่อมออกฤทธิ์ต่อตัวรับฝิ่น ดังนั้น 3 เดือนหากไม่มีกระท่อมกระท่อมจะทำให้ระบบการให้รางวัลและความเครียดของสมองมีเวลาปรับตัวได้อย่างยั่งยืนหลายๆ คนรายงานว่ามีความคิดที่ชัดเจนขึ้นและมีแรงจูงใจที่มั่นคงมากขึ้นเมื่อพวกเขาได้รับการใช้งานมากขึ้น\n\nทำไมมันถึงสำคัญ\nยิ่งมีการใช้งานน้อยครั้งเท่าใด การดึงกระท่อมในแต่ละวันก็ยิ่งลดลงมากขึ้นเท่านั้น ทำให้เหตุการณ์สำคัญนี้เป็นรากฐานที่มั่นคงสำหรับการฟื้นตัวที่ยั่งยืน';

  @override
  String get kratomReferenceDay365 =>
      'หนึ่งปีนอกกระท่อม\n\nที่มา: สถาบันป้องกันยาเสพติดแห่งชาติ (NIDA), \"กระท่อม\"\n\nการถอนแบบเฉียบพลันที่ผ่านมา\nNIDA ไม่ได้เผยแพร่ลำดับเวลาการฟื้นตัวในกระท่อมหนึ่งปีโดยเฉพาะ แต่หนึ่งปีของการงดเว้นอย่างต่อเนื่องนั้นเกินกว่ากรอบเวลาการถอนตัวทางจิตใจแบบเฉียบพลันและระยะเริ่มต้นที่บันทึกไว้ในการวิจัยกระท่อมสำหรับคนส่วนใหญ่ที่มาถึงจุดนี้ ความอยากเกิดขึ้นไม่บ่อยนักและจัดการได้ง่ายกว่ามาก\n\nภาพใหญ่ขึ้น\nการงดเว้นหนึ่งปีแสดงถึงการเปลี่ยนแปลงที่สำคัญด้านสุขภาพ การเงิน และการกำกับตนเองการเชื่อมต่อกับฝ่ายสนับสนุนช่วยรักษาความคืบหน้านั้นให้ปลอดภัย';

  @override
  String get maoiReferenceDay3 =>
      'การหยุดชะงักของ MAOI: ระยะที่มีความเสี่ยงสูงสุด\n\nที่มา: Dilsaver (1988) การวิจัยเกี่ยวกับปฏิกิริยาการถอน MAOI\n\nคำเตือนด้านความปลอดภัยที่สำคัญ\nMAOIs มีความเสี่ยงที่ร้ายแรงที่สุดในการหยุดยาในกลุ่มยาต้านอาการซึมเศร้าการหยุดกะทันหัน โดยเฉพาะฟีเนลซีนและทรานิลไซโปรมีน อาจทำให้เกิดปฏิกิริยารุนแรง ได้แก่:\n• ความวิตกกังวลและความปั่นป่วนอย่างรุนแรง\n• พูดถูกกดดันและกระสับกระส่าย\n• นอนไม่หลับหรือง่วงนอน\n• อาการประสาทหลอน\n• อาการเพ้อและโรคจิตแบบหวาดระแวง\n\nหากคุณมีอาการเหล่านี้ ให้ไปพบแพทย์ทันที\n\nMAOI ทำงานอย่างไร\nMAOI ทำงานโดยการผูกมัดและปิดการใช้งานเอนไซม์ monoamine oxidase อย่างถาวร (MAO-A และ MAO-B)โดยปกติเอนไซม์เหล่านี้จะสลายเซโรโทนิน นอร์เอพิเนฟริน โดปามีน และไทรามีนในสมองและลำไส้เนื่องจากตัวเอนไซม์ถูกทำลายมากกว่าแค่ถูกบล็อก การฟื้นตัวจึงขึ้นอยู่กับร่างกายที่ผลิตเอนไซม์ใหม่ มากกว่าขึ้นอยู่กับความเร็วของยาในการล้างกระแสเลือด';

  @override
  String get maoiReferenceDay7 =>
      'หนึ่งสัปดาห์หลังจาก MAOI: การสังเคราะห์เอนไซม์ MAO กำลังดำเนินการ\n\nที่มา: \"สารยับยั้งโมโนเอมีนออกซิเดส (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nกระบวนการกู้คืนเอนไซม์\nซึ่งแตกต่างจาก SSRIs, SNRIs และ TCAs ซึ่งยับยั้งการดูดซึมสารเคมีในสมองแบบย้อนกลับได้ MAOIs ที่ไม่สามารถย้อนกลับได้ (phenelzine, tranylcypromine) จะทำลายโมเลกุลของเอนไซม์ monoamine oxidase อย่างถาวรการชะล้างทางคลินิกจึงขึ้นอยู่กับความเร็วที่ร่างกายสามารถสังเคราะห์เอนไซม์ใหม่ทั้งหมดได้ ประมาณ 2 สัปดาห์ แทนที่จะขึ้นอยู่กับความเร็วของตัวยาในการล้างกระแสเลือด\n\nเกิดอะไรขึ้นในหนึ่งสัปดาห์\n• การสังเคราะห์เอนไซม์ MAO-A และ MAO-B อยู่ในระหว่างดำเนินการอย่างดี โดยประมาณกลางคันของหน้าต่างการสังเคราะห์ใหม่ ~2 สัปดาห์\n• ระยะความเสี่ยงเฉียบพลันที่อธิบายไว้ในวันที่ 3 กำลังจะผ่านไป แม้ว่าการดูแลทางการแพทย์อย่างใกล้ชิดยังคงเป็นสิ่งสำคัญ\n\nข้อควรระวังด้านอาหาร\nการรักษาด้วย MAOI จำเป็นต้องรับประทานอาหารที่มีไทรามีนต่ำ เนื่องจากเอนไซม์เหล่านี้มักจะสลายไทรามีนและป้องกันไม่ให้กระตุ้นให้เกิดภาวะความดันโลหิตสูงคำแนะนำคือให้ปฏิบัติตามข้อจำกัดด้านอาหารอย่างต่อเนื่องผ่านหน้าต่างการสังเคราะห์ใหม่นี้ แพทย์ที่สั่งยาจะแนะนำเมื่อปลอดภัยที่จะผ่อนคลายอาการเหล่านั้น';

  @override
  String get maoiReferenceDay14 =>
      'สองสัปดาห์หลังจาก MAOIs: กิจกรรมของเอนไซม์ MAO ได้รับการฟื้นฟูอย่างมาก\n\nที่มา: Fritz และคณะ(2526), จิตเวชศาสตร์ชีวภาพ\n\nเครื่องหมายสองสัปดาห์ที่สำคัญ\nสองสัปดาห์เป็นกรอบเวลาการชะล้างทางคลินิกมาตรฐานสำหรับการฟื้นฟูเอนไซม์ MAO หลังจากหยุด MAOI ที่ไม่สามารถรักษาให้หายขาดได้ เช่น ทรานิลไซโปรมีนหรือฟีเนลซีนจากการศึกษา tranylcypromine การวิจัยนี้พบว่ากิจกรรมการเร่งปฏิกิริยาของเกล็ดเลือด MAO-B ซึ่งลดลงอย่างรวดเร็วภายในหนึ่งวันหลังการให้ยา จะฟื้นตัวเป็นปกติภายในเวลาประมาณสองสัปดาห์ เนื่องจากร่างกายจะแทนที่เกล็ดเลือดที่ได้รับผลกระทบจากยาด้วยเกล็ดเลือดสดที่มีเอนไซม์ที่ออกฤทธิ์ แม้ว่าระดับโปรตีน MAO-B ทั้งหมดจะไม่เปลี่ยนแปลงก็ตาม\n\nการกู้คืนเอนไซม์ MAO\n• กิจกรรมของเกล็ดเลือด MAO-B ได้รับการฟื้นตัวอย่างมีนัยสำคัญเมื่อถึงจุดนี้\n• สมอง MAO-A และ MAO-B ซึ่งเป็นไปตามไทม์ไลน์การสังเคราะห์ใหม่ที่คล้ายกันในวงกว้าง ก็ได้รับการฟื้นฟูเป็นส่วนใหญ่เช่นกัน\n• เมแทบอลิซึมของไทรามีนกลับมาเป็นปกติอีกครั้ง — โดยทั่วไปคุณสามารถผ่อนคลายข้อจำกัดด้านอาหารของ MAOI ได้โดยการปรึกษากับผู้สั่งจ่ายยาของคุณ\n\nคืนสมดุลเคมีและสมอง\nเมื่อการทำงานของเอนไซม์ MAO ฟื้นตัวขึ้น ระบบเคมีในสมองที่ MAOI ได้รับผลกระทบก็เริ่มอยู่ภายใต้การควบคุมตามธรรมชาติ:\n• Serotonin, norepinephrine และ dopamine จะไม่ถูกเพิ่มสูงขึ้นโดยการยับยั้ง MAO อีกต่อไป\n• ภาวะภูมิไวเกินของตัวรับโมโนเอมีน (เกิดจากระดับสารเคมีในสมองที่เพิ่มขึ้นอย่างเรื้อรังของ MAOI) กำลังเริ่มหายไป\n• การควบคุมอารมณ์และพลังงานตามธรรมชาติกำลังกลับมา';

  @override
  String get maoiReferenceDay30 =>
      'หนึ่งเดือนหลังจาก MAOIs: การปรับสมดุลระบบเคมีและสมอง\n\nที่มา: \"สารยับยั้งโมโนเอมีนออกซิเดส (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nการประเมินหนึ่งเดือน\nหนึ่งเดือนหลังจากการหยุดใช้ MAOI ก็เลยช่วงการสังเคราะห์เอนไซม์ MAO ใหม่ประมาณ 2 สัปดาห์ที่อธิบายไว้ในแหล่งนี้ไปแล้ว ดังนั้นเมื่อถึงจุดนี้ กิจกรรมของเอนไซม์ MAO ก็ฟื้นตัวเต็มที่ และระบบเคมีในสมองอยู่ภายใต้การควบคุมตามธรรมชาติทั้งหมด\n\nสิ่งที่ได้คืนมาในหนึ่งเดือน\n• กิจกรรมของเอนไซม์ MAO สมบูรณ์: ทั้ง MAO-A และ MAO-B ทำงานได้อย่างสมบูรณ์\n• ข้อจำกัดด้านอาหารได้รับการแก้ไขแล้ว: การรับประทานอาหารตามปกติโดยไม่มีข้อจำกัดด้านไทรามีน\n• การเสื่อมของเซโรโทนินตามธรรมชาติ: วงจรการหมุนเวียนของเซโรโทนินตามปกติของสมองกลับคืนมา\n• การควบคุมแคทีโคลามีนตามธรรมชาติ: ระดับโดปามีนและนอร์เอพิเนฟรินควบคุมโดยกิจกรรม MAO ตามธรรมชาติ\n\nข้อควรระวังในการโต้ตอบยา\nMAOIs เกี่ยวข้องกับปฏิกิริยาที่คุกคามถึงชีวิตกับยาเซโรโทนินความเสี่ยงในการโต้ตอบเหล่านี้ได้รับการแก้ไขแล้วภายในเวลาหนึ่งเดือนอย่างไรก็ตาม ควรแจ้งให้ผู้สั่งจ่ายยาและเภสัชกรทราบถึงการใช้ MAOI ก่อนหน้านี้เสมอ เมื่อมีการสั่งยาใหม่';

  @override
  String get maoiReferenceDay90 =>
      'สามเดือนหลังจาก MAOI: การถอนตัวที่ผ่านมาอย่างดี\n\nที่มา: \"Antidepressant Withdrawal Syndrome\" จดหมายบำบัด 112 (2018) Therapeutics Initiative บนชั้นวางหนังสือ NCBI\n\nการถอนตัวออกจากกลุ่มยาแก้ซึมเศร้า\nการทบทวนหลักฐานนี้ถือว่าการถอนยาต้านอาการซึมเศร้าเป็นปรากฏการณ์ที่แท้จริงของความอดทนและการพึ่งพาอาศัยกัน โดยการวางยาแก้ซึมเศร้า \'ควบคู่ไปกับยาฝิ่นและเบนโซไดอะซีพีน\'หลักฐานโดยละเอียดมีศูนย์กลางอยู่ที่ SSRI และ SNRI แต่ปฏิกิริยาการถอนยาได้รับการยอมรับในกลุ่มยาแก้ซึมเศร้า รวมถึงหลังจากหยุด MAOIอาการ \'มักปรากฏภายในไม่กี่วันหลังจากหยุด\' และ \'ส่วนใหญ่... หายภายใน 2 สัปดาห์\' แม้ว่าอาการจะนานกว่านั้นก็ตาม\n\nที่ซึ่งสามเดือนนั่งอยู่\nเมื่อถึงสามเดือน ระยะการถอนยาแบบเฉียบพลันยังตามหลังคนส่วนใหญ่อยู่มาก และร่างกายได้ปรับตัวมานานแล้วเพื่อควบคุมโมโนเอมีนโดยปราศจากการยับยั้ง MAO\n\nสัญญาณการกู้คืนบน \'การตอบสนองต่อตัวรับอีกครั้ง\'\nคำกล่าวอ้างอย่างมั่นใจว่าเซโรโทนิน นอร์เอพิเนฟรีน และตัวรับโดปามีนทั้งหมด \'กลับมามีภูมิต้านทานอีกครั้งภายในสามเดือน\' เกินกว่าที่หลักฐานระบุไว้สิ่งที่เชื่อถือได้: โดยทั่วไประยะการถอนตัวได้รับการแก้ไขแล้ว และสำหรับคนส่วนใหญ่ อารมณ์ พลังงาน และช่วงทางอารมณ์จะคงที่ในการส่งสัญญาณของสมองตามธรรมชาติที่ควบคุมตนเอง\n\nการถอนกับการกำเริบของโรค\nจดหมายเน้นย้ำถึงการถอนตัว นอกเหนือจากการคืนสภาพที่แท้จริงหากอาการยังคงอยู่เป็นเวลาสามเดือน ให้ตรวจสอบกับแพทย์ที่สั่งจ่ายยา แทนที่จะคิดว่าเป็นเพียงอาการถอนยาเท่านั้น';

  @override
  String get maoiReferenceDay180 =>
      'หกเดือนหลังจาก MAOI: การฟื้นฟูระยะยาว\n\nที่มา: Zwiebel & Viguera (2022), Cleveland Clinic Journal of Medicine\n\nการประเมินรอบหกเดือน\nการทบทวนนี้อธิบายว่ายาแก้ซึมเศร้าออกฤทธิ์บางส่วนโดยการทำให้ตัวรับโมโนเอมีนลดลงเมื่อเวลาผ่านไป และการปรับลดนี้ต้องใช้เวลาหลายสัปดาห์หรือหลายเดือนเพื่อย้อนกลับเมื่อยาหยุดลง ซึ่งเป็นกระบวนการที่ช้ากว่าการสังเคราะห์เอนไซม์ MAO ประมาณสองสัปดาห์เอง\n\nที่ซึ่งหกเดือนนั่งอยู่\nหกเดือนผ่านไปอย่างสบายๆ ผ่านช่วงการปรับตัวรับรายสัปดาห์ต่อเดือนสำหรับคนส่วนใหญ่ ควบคู่ไปกับการทำงานของเอนไซม์ที่ทำให้เป็นมาตรฐานอย่างสมบูรณ์ภายในเดือนแรกสัญญาณการฟื้นตัว: เส้นเวลาที่แม่นยำสำหรับการกระตุ้นเซโรโทนิน นอร์เอพิเนฟริน และโดปามีนแบบเต็มนั้นไม่ได้ถูกกำหนดขึ้นด้วยความแน่นอนในแต่ละวันในวรรณกรรม สิ่งที่เชื่อถือได้คือภายในหกเดือน ผู้คนส่วนใหญ่จะทำงานโดยใช้การส่งสัญญาณของสมองตามธรรมชาติและควบคุมตนเอง\n\nหมายเหตุเกี่ยวกับฟีเอทิลเอมีน\nMAOIs ยังยับยั้งการย่อยสลายฟีเอทิลเอมีน (กฟภ.) ซึ่งเป็นเอมีนที่เชื่อมโยงกับอารมณ์และพลังงานคาดว่าเมแทบอลิซึมของมันจะทำให้เป็นปกติควบคู่ไปกับการฟื้นตัวของเอนไซม์ MAO ทั่วไป แม้ว่าจะไม่มีการกำหนดเส้นเวลาเฉพาะของกฟภ. ที่ชัดเจนในงานวิจัย เช่นเดียวกับการตอบสนองต่อตัวรับอีกครั้ง';

  @override
  String get maoiReferenceDay365 =>
      'หนึ่งปีหลังจาก MAOI: ฟื้นตัวได้สำเร็จ\n\nที่มา: \"สารยับยั้งโมโนเอมีนออกซิเดส (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nหนึ่งปี: ความสำเร็จอันน่าทึ่ง\nการเสร็จสิ้นหนึ่งปีหลังจากการยุติการผลิตของ MAOI ถือเป็นเหตุการณ์สำคัญที่สำคัญอย่างแท้จริงMAOIs เป็นหนึ่งในกลุ่มยาแก้ซึมเศร้าที่เรียกร้องจากยามากที่สุด โดยมีกลไกที่ไม่สามารถรักษาให้หายได้ การรับประทานอาหารที่มีไทรามีนต่ำอย่างเข้มงวด และข้อควรระวังในการโต้ตอบระหว่างยาซึ่งแตกต่างจากกลุ่มยาต้านอาการซึมเศร้า other ใดๆ\n\nสิ่งที่ปีนี้เป็นตัวแทน\n• กิจกรรมโมโนเอมีนออกซิเดสตามธรรมชาติที่ควบคุมตนเองได้หนึ่งปีเต็ม ซึ่งสร้างขึ้นจากการสังเคราะห์เอนไซม์ใหม่ซึ่งจะเสร็จสิ้นภายในเดือนแรก\n• แสดงให้เห็นถึงความสามารถในการรักษาความเป็นอยู่ที่ดีโดยไม่ต้องยับยั้ง MAO ที่ขับเคลื่อนด้วยยา\n• ประวัติที่ยาวนานพอที่จะมั่นใจได้ว่าความเสี่ยงในการหยุดชะงักเฉียบพลันของวันที่ 3 จะอยู่เบื้องหลังคุณอย่างแน่นอน\n\nหมายเหตุเกี่ยวกับ MAOI\nMAOIs ยังคงมีประสิทธิภาพเฉพาะสำหรับสภาวะที่ดื้อต่อการรักษาและภาวะซึมเศร้าที่ไม่ปกติการหยุดยาที่ประสบความสำเร็จไม่ได้ทำให้คุณค่าของมันลดลงในฐานะการใช้ยา แต่มันแสดงให้เห็นถึงความสามารถในการฟื้นตัวของสมอง และความสามารถของผู้ป่วยในการดำเนินกระบวนการทางการแพทย์ที่มีความต้องการเป็นพิเศษข้อควรระวังประการหนึ่งที่ยั่งยืน: แจ้งให้ผู้สั่งจ่ายยาหรือวิสัญญีแพทย์รายใหม่ทราบต่อไปเกี่ยวกับการใช้ MAOI ในอดีต เนื่องจากความเสี่ยงในการโต้ตอบยาบางอย่างอาจคุ้มค่าที่จะติดธงไว้อย่างไม่มีกำหนด';

  @override
  String get marijuanaReferenceDay1 =>
      'การถอนกัญชา: วันแรก\n\nที่มา: \"กลุ่มอาการถอนกัญชา: ข้อมูลเชิงลึกในปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ (2017) บน PubMed Central\n\nการถอนกัญชามีจริง\nการทบทวนโดยผู้ทรงคุณวุฒินี้ระบุว่ากลุ่มอาการถอนกัญชา (CWS) เป็นภาวะทางคลินิกที่ได้รับการตรวจสอบอย่างดี ซึ่งเกิดขึ้นในประมาณ 90% ของผู้ที่ได้รับการวินิจฉัยว่าติดกัญชาหลังจากที่หยุดใช้ความรุนแรงสูงสุดโดยเฉลี่ยเทียบได้กับกลุ่มอาการถอนยาสูบ\n\nเหตุใดการถอนเงินจึงเกิดขึ้น\nTHC ทำหน้าที่ในระบบเอนโดแคนนาบินอยด์ ซึ่งเป็นตัวรับ CB1 ที่เกี่ยวข้องกับอารมณ์ ความอยากอาหาร การนอนหลับ ความจำ และความเครียดด้วยการใช้งานเรื้อรัง สมองจะควบคุมระบบนี้ลงเมื่อกัญชาหยุด กัญชาจะใช้งานไม่ได้ชั่วคราวการทบทวนบันทึกว่าตัวรับ CB1 กลับสู่การทำงานปกติภายในประมาณสี่สัปดาห์หลังจากเลิกบุหรี่\n\nเริ่มเป็นวันแรก\nเอกสารการตรวจสอบระบุว่าอาการทางกายภาพมักจะปรากฏขึ้นก่อน — ภายใน 1–3 วันนับจากการใช้ครั้งสุดท้าย — ในขณะที่อาการทางจิตจะเกิดขึ้นในช่วง 2–10 วันอาการเริ่มแรก ได้แก่:\n• หงุดหงิด วิตกกังวล และกระสับกระส่าย\n• นอนหลับยาก\n• ความอยากอาหารลดลง\n• ความตึงเครียดทางร่างกาย เหงื่อออก หรือหนาวสั่น\n• อารมณ์ซึมเศร้า\n\nความรุนแรง\nCWS ไม่เป็นอันตรายทางการแพทย์ และอาการต่างๆ มักจะไม่รุนแรงถึงปานกลาง แต่การทบทวนตั้งข้อสังเกตว่าอาการเหล่านี้น่าวิตกมากพอที่จะกระตุ้นให้เกิดอาการกำเริบอีก ซึ่งเป็นเหตุผลว่าทำไมการทำความเข้าใจไทม์ไลน์จึงมีความสำคัญ';

  @override
  String get marijuanaReferenceDay3 =>
      'เส้นเวลาการถอนกัญชา: วันแรก ๆ\n\nที่มา: \"ระยะเวลาของอาการถอนกัญชา DSM-5 ในผู้เสพสารเสพติดหลายชนิด\" BMC Psychiatry (2013) บน PubMed Central\n\nหลักสูตรเวลาที่วัดได้\nการศึกษานี้ติดตามอาการถอนกัญชา DSM-5 ในผู้ป่วย 90 รายในช่วงสี่สัปดาห์ ทำให้เกิดภาพที่ชัดเจนที่สุดว่าอาการเกิดขึ้นและลดลงอย่างไรความรุนแรงโดยรวมเป็นไปตามเส้นโค้ง: เพิ่มขึ้น แล้วลดลงในช่วงสัปดาห์ต่อมา\n\nสิ่งที่พีคส์ในช่วงต้น\nอาการที่ก่อกวนทางร่างกายมากที่สุดหลายอย่างจะรุนแรงขึ้นภายในสองสามวันแรกหลังจากหยุด:\n• อาการนอนไม่หลับ — สูงสุดประมาณวันที่ 1\n• อาการประหม่า — สูงสุดประมาณวันที่ 4\n• อารมณ์ซึมเศร้าและอาการทางกายภาพ — มีอาการสูงสุดประมาณวันที่ 5\n• กระสับกระส่าย — สูงสุดประมาณวันที่ 6\n\nอะไรจะเกิดขึ้นในภายหลัง\nผลการศึกษาพบว่ามีอาการบางอย่างเกิดขึ้นและสูงสุดช้ากว่าสัปดาห์แรก:\n• ความฝันอันไม่พึงประสงค์ที่ชัดเจน — สูงสุดประมาณวันที่ 11\n• อาการหงุดหงิดและโกรธ — สูงสุดประมาณวันที่ 14\n\nการนอนหลับและกัญชา\nความฝันที่ล่าช้าและสดใสสะท้อนถึงการฟื้นตัวของ REM: กัญชาระงับการนอนหลับ REM ในระหว่างการใช้งาน และสมองจะชดเชยมากเกินไปเมื่อหยุดผู้เขียนโต้แย้งว่าอาการนี้เป็นเรื่องปกติมากพอที่จะอยู่ในเกณฑ์การถอนตัวอย่างเป็นทางการ\n\nTakeaway สำหรับวันที่สาม\nในวันที่สาม คุณจะเข้าสู่ช่วงจุดสูงสุดทางกายภาพในช่วงแรก อาการนอนไม่หลับ ความกังวลใจ และกระสับกระส่าย แทบจะแย่ที่สุดแล้วเส้นโค้งที่สม่ำเสมอและคาดเดาได้นั้นทำให้มั่นใจได้: อาการเหล่านี้มีทิศทางที่ทราบอยู่แล้วและลดลงจากจุดนี้';

  @override
  String get marijuanaReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่มีกัญชา: เลวร้ายที่สุด\n\nที่มา: \"กลุ่มอาการถอนกัญชา: ข้อมูลเชิงลึกในปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ (2017) บน PubMed Central\n\nโดยที่หนึ่งสัปดาห์อยู่ในซินโดรม\nการทบทวนนี้บันทึกว่ากลุ่มอาการถอนกัญชามักจะกินเวลานานถึงสามสัปดาห์ โดยช่วงเวลาที่น่าวิตกที่สุดอยู่ในช่วงระหว่างสัปดาห์แรกถึงสัปดาห์ที่สามในหนึ่งสัปดาห์ อาการทางกายภาพที่เกิดขึ้นในช่วงแรกๆ เช่น นอนไม่หลับ เบื่ออาหาร กระสับกระส่าย มักจะผ่านพ้นจุดสูงสุดและผ่อนคลายลงแล้ว\n\nสิ่งที่ยังคงลงตัว\nการทบทวนนี้จะแยกแยะอาการทางร่างกายที่เกิดขึ้นในช่วงแรกออกจากอาการทางจิตที่เกิดขึ้นในภายหลังในหนึ่งสัปดาห์:\n• อาการไม่สบายทางร่างกายและความอยากอาหารดีขึ้นอย่างมาก\n• การนอนหลับยังคงถูกรบกวนสำหรับหลายๆ คน โดยความฝันที่ชัดเจน (REM rebound) มักจะถึงจุดสูงสุดในช่วงนี้\n• อาการหงุดหงิดและอารมณ์อาจยังคงอยู่ในระดับสูง เนื่องจากอาการเหล่านี้มักจะรุนแรงขึ้นในช่วงสองสัปดาห์แรก\n\nชีววิทยาของการฟื้นฟู\nภายใต้การเปลี่ยนแปลงเหล่านี้ การทบทวนตั้งข้อสังเกตว่าตัวรับ CB1 ที่ลดลงจะกลับมาทำงานตามปกติภายในประมาณสี่สัปดาห์หลังจากเลิกบุหรี่หนึ่งสัปดาห์ต่อมา กฎระเบียบใหม่ดังกล่าวกำลังดำเนินการไปด้วยดี ระบบกำลังฟื้นตัวแม้ว่าอาการบางอย่างจะยังคงอยู่ก็ตาม\n\nซื้อกลับบ้าน\nการไปถึงหนึ่งสัปดาห์หมายถึงจุดสูงสุดทางกายภาพอันเฉียบพลันอยู่ข้างหลังคุณอาการการนอนหลับและอารมณ์ที่เหลืออยู่เป็นส่วนหนึ่งของกลุ่มอาการที่ทราบแน่ชัดและมีขอบเขตจำกัด ซึ่งจะค่อยๆ หายไปในอีก 2-3 สัปดาห์ข้างหน้า';

  @override
  String get marijuanaReferenceDay14 =>
      'สองสัปดาห์โดยไม่มีกัญชา: การถอนตัวแบบเฉียบพลันสิ้นสุดลง\n\nที่มา: Budney, AJ และคณะ(2003) — การศึกษาแบบทบทวนโดยผู้ทรงคุณวุฒิเกี่ยวกับหลักสูตรเวลาถอนกัญชา\n\nผลการวิจัย\nการศึกษาที่ได้รับการตรวจสอบโดยผู้ทรงคุณวุฒินี้บันทึกระยะเวลาของอาการถอนกัญชาในผู้ใช้ทั่วไปอย่างเป็นระบบผลการวิจัยพบว่ากลุ่มอาการถอนยาเฉียบพลันจะถึงจุดสูงสุดภายในสัปดาห์แรก และจะหายไปเองภายใน 2 สัปดาห์หลังจากหยุดแสดงอาการส่วนใหญ่\n\nสิ่งที่แก้ไขได้ภายใน 2 สัปดาห์\nการศึกษาบันทึกไว้ว่าภายใน 14 วัน อาการต่อไปนี้หายไปอย่างมากในผู้เข้าร่วมการศึกษา:\n• ความรู้สึกไม่สบายทางร่างกายและอาการทางร่างกาย\n• รบกวนความอยากอาหาร\n• รบกวนการนอนหลับมากที่สุด\n• หงุดหงิดและวิตกกังวลถึงขีดสุด\n\nสิ่งที่อาจคงอยู่นานกว่า 2 สัปดาห์\nการวิจัยยังระบุถึงอาการที่ยังคงมีอยู่เกินเครื่องหมายสองสัปดาห์ในผู้ใช้บางราย:\n• อารมณ์ซึมเศร้า\n• มีปัญหาเรื่องสมาธิ\n• คุณภาพการนอนหลับ (แม้ว่าจะดีขึ้นก็ตาม)\n\nความสำคัญของเครื่องหมาย 2 สัปดาห์\nการผ่านเครื่องหมายสองสัปดาห์ไปนั้นมีความสำคัญ เนื่องจากหมายความว่าอาการถอนตัวแบบเฉียบพลันนั้นเกือบจะสมบูรณ์แล้วความท้าทายที่นอกเหนือจากประเด็นนี้ส่วนใหญ่เกี่ยวข้องกับการฟื้นฟูสมองในระยะยาว และการจัดการสาเหตุเบื้องหลังของการใช้กัญชา มากกว่าการตอบสนองทางสรีรวิทยาเฉียบพลันต่อการหยุด';

  @override
  String get marijuanaReferenceDay30 =>
      'หนึ่งเดือนโดยไม่มีกัญชา: ฟังก์ชั่นหน่วยความจำดีขึ้น\n\nที่มา: สมเด็จพระสันตะปาปา และคณะ(2544) จดหมายเหตุของจิตเวชศาสตร์ทั่วไป\n\nกัญชากับความทรงจำ: ปัญหา\nการศึกษานี้ติดตามผู้ใช้กัญชาจำนวนมากและระยะยาวตลอด 28 วันของการงดเว้นที่ได้รับการยืนยัน และเปรียบเทียบผลการทดสอบการคิดและความจำกับผู้ใช้ที่ไม่รุนแรงและผู้ไม่ใช้ในช่วงเริ่มต้นของการเลิกบุหรี่ และอีกครั้งในวันที่ 1 และ 7 ผู้ใช้จำนวนมากทำงานได้แย่กว่าการควบคุมการเรียกคืนรายการคำศัพท์ ซึ่งเป็นการขาดดุลที่ติดตามด้วยระดับสาร THC ในปัสสาวะ ซึ่งสะท้อนถึงการสัมผัสยาล่าสุดมากกว่าการใช้ตลอดชีวิต\n\nข่าวดี: ฟื้นตัวภายในวันที่ 28\nภายในวันที่ 28 ผู้ใช้จำนวนมาก ผู้ใช้ขนาดเล็ก และผู้ที่ไม่ใช่ผู้ใช้ดำเนินการแทบจะเหมือนกันในการทดสอบการคิดและความจำของการศึกษานี้นอกจากนี้ยังไม่มีความสัมพันธ์ที่มีนัยสำคัญระหว่างการใช้กัญชาตลอดอายุการใช้งานกับการทดสอบประสิทธิภาพ ณ จุดนั้น\n\nสิ่งนี้หมายความว่าอย่างไรใน 30 วัน\n• การเรียนรู้ด้วยวาจาและการจดจำได้กลับสู่ระดับกลุ่มควบคุมแล้ว\n• การขาดดุลคงเหลือที่พบในสัปดาห์แรกได้รับการแก้ไขแล้ว\n• การขาดดุลที่เหลืออยู่ก่อนหน้านี้เชื่อมโยงกับความเสี่ยงที่เกิดขึ้นล่าสุด ไม่ใช่ความเสียหายถาวร\n\nสิ่งที่แสดงหลักฐาน\nเมื่อถึงวันที่ 28 ผู้ใช้จำนวนมากแทบจะแยกไม่ออกจากผู้ใช้ขนาดเล็กและผู้ไม่ใช้ในการทดสอบการคิดและความจำชุดเต็มของการศึกษานี้การขาดดุลการเรียนรู้ด้วยวาจาและการจดจำที่พบในสัปดาห์แรกได้ฟื้นตัวสู่ระดับกลุ่มควบคุมแล้ว';

  @override
  String get marijuanaReferenceDay60 =>
      'สองเดือนโดยไม่มีกัญชา: ความเข้มข้นเพิ่มขึ้น\n\nที่มา: Roten และคณะ(2015) พฤติกรรมเสพติด\n\nคำถามวิจัย\nการศึกษาเพื่อการเลิกกัญชาในเยาวชนนี้ติดตามคะแนนการทดสอบความจำและความคิดควบคู่ไปกับการทดสอบปัสสาวะในช่วงเวลาประมาณสองเดือน โดยเปรียบเทียบผู้ใช้ที่ยังคงใช้กัญชาต่อไปกับผู้ที่หยุดใช้เมื่อเร็วๆ นี้หรือยังคงเลิกบุหรี่อยู่\n\nข้อค้นพบที่สำคัญ\nการเลิกบุหรี่อย่างต่อเนื่องสัมพันธ์กับการปรับปรุงที่สำคัญใน:\n• คะแนนหน่วยความจำคอมโพสิต\n• หน่วยความจำทางวาจาโดยเฉพาะ — โดเมนที่ได้รับผลกระทบมากที่สุด\n• ประสิทธิภาพการเคลื่อนไหวและความเร็วปฏิกิริยา\n\nเมื่อสองเดือน\nจากการงดเว้นอย่างต่อเนื่องประมาณแปดสัปดาห์ คะแนนประสิทธิภาพด้านความจำ การเคลื่อนไหว และความเร็วปฏิกิริยาได้เพิ่มขึ้นอย่างวัดผลได้เหนือจุดที่พวกเขานั่งในระหว่างการใช้งาน โดยติดตามอย่างใกล้ชิดโดยได้รับการยืนยันว่าไม่ได้ใช้งาน มากกว่าที่จะอยู่คนเดียวตามลำพัง\n\nการศึกษานี้แสดงให้เห็นอะไร\nในวัยรุ่นและผู้ใหญ่วัยหนุ่มสาวที่ติดกัญชา การเลิกบุหรี่อย่างต่อเนื่องทำให้หน่วยความจำรวม ความจำทางวาจา และประสิทธิภาพการเคลื่อนไหวและความเร็วปฏิกิริยาเพิ่มขึ้นอย่างมีนัยสำคัญในช่วงเวลาการรักษาประมาณสองเดือน';

  @override
  String get marijuanaReferenceDay90 =>
      'สามเดือนที่ไม่มีกัญชา: ความมั่นคงทางอารมณ์กลับมา\n\nที่มา: คอนเนอร์ และคณะ(2022), Addiction — การทบทวนทางคลินิกเกี่ยวกับการถอนกัญชา\n\nเส้นเวลาการถอนเงินจริงๆ แล้วเป็นอย่างไร\nการทบทวนนี้จะอธิบายอาการถอนกัญชาซึ่งโดยทั่วไปจะเริ่มใน 24–48 ชั่วโมงหลังจากการหยุดและถึงจุดสูงสุดประมาณวันที่ 2–6ความโกรธ ความก้าวร้าว และอารมณ์หดหู่อาจเกิดขึ้นได้เร็วถึงหนึ่งสัปดาห์ แต่โดยทั่วไปจะสูงสุดหลังจากเลิกบุหรี่ไปประมาณสองสัปดาห์การรบกวนการนอนหลับโดยเฉพาะสามารถคงอยู่ได้นานกว่าอาการของ other\n\nที่ซึ่งสามเดือนนั่งอยู่\nภายในสามเดือน คุณจะอยู่นอกเหนือหลักสูตรการถอนตัวที่บันทึกไว้มาก โดยทั่วไปอาการจะเริ่มภายใน 24–48 ชั่วโมง อาการจะรุนแรงสูงสุดประมาณวันที่ 2–6 และแม้กระทั่งอาการทางอารมณ์และการนอนหลับที่ช้าลงจะรุนแรงขึ้นภายในสัปดาห์ต่อๆ ไปเก้าสิบวันช่วยให้อารมณ์ที่หดหู่และการนอนหลับพักผ่อนเป็นเวลาหลายเดือน\n\nหมายเหตุเกี่ยวกับระบบเอนโดแคนนาบินอยด์\nการวิจัยการถอนกัญชายังแสดงให้เห็นว่าตัวรับ CB1 ที่ลดลงจะกลับมาทำงานตามปกติภายในเวลาประมาณสี่สัปดาห์หลังจากเลิกบุหรี่เมื่อถึง 90 วัน คุณจะอยู่นอกกรอบเวลาการกู้คืนตัวรับนั้นมาก\n\nมองไปข้างหน้า\nการทบทวนยังกล่าวถึงการพยากรณ์โรคหลังการล้างพิษและการป้องกันการกำเริบของโรค โดยเน้นย้ำว่าการสนับสนุนอย่างต่อเนื่องและกลยุทธ์การรับมือมีความสำคัญเกินกว่ากรอบเวลาการถอนตัวแบบเฉียบพลัน';

  @override
  String get marijuanaReferenceDay180 =>
      'หกเดือนโดยไม่มีกัญชา: การฟื้นฟูการวางแผนและการตัดสินใจ\n\nที่มา: Crean, Crane & Mason (2011), วารสารการแพทย์ติดยาเสพติด\n\nการวางแผนและการตัดสินใจหลังกัญชา\nการทบทวนนี้ตรวจสอบความสนใจ การตัดสินใจ การควบคุมตนเอง ความจำในการทำงาน และความคล่องแคล่วทางวาจาตั้งแต่ชั่วโมงแรกหลังการใช้ ผ่านการเลิกบุหรี่ในระยะยาวภายในหกเดือน คุณจะอยู่ไกลเกินกว่าผลกระทบระยะสั้นและเข้าสู่ช่วงฟื้นตัว\n\nสิ่งที่การวิจัยพบ\nปัญหาหลายประการที่เกี่ยวข้องกับการใช้งานหนักลดลงด้วยการเลิกบุหรี่อย่างต่อเนื่อง โดยการศึกษาบางชิ้นพบว่าสามารถฟื้นตัวได้ภายใน 28 วันบริเวณที่ฟื้นตัวได้ช้าที่สุดหลังจากใช้งานหนักและเริ่มมีอาการตั้งแต่เนิ่นๆ ได้แก่:\n• การตัดสินใจและการกล้าเสี่ยง — ทำเครื่องหมายโดยเฉพาะว่าเป็นโดเมนที่การขาดดุลอาจคงอยู่ในระยะยาวในผู้ใช้จำนวนมากและเรื้อรัง\n• ทักษะการใช้เหตุผลและวาจาเชิงนามธรรม — โดยเฉพาะในผู้ใหญ่ที่เริ่มใช้ก่อนอายุ 17 ปี\n\nการฟื้นตัวตั้งแต่เนิ่นๆ\nหกเดือนอยู่ไกลเกินกว่าผลกระทบระยะสั้นในการทบทวนนี้การวางแผน การตัดสินใจ และการให้เหตุผลจะปรับปรุงให้ดีขึ้นด้วยการงดเว้นอย่างต่อเนื่อง ทำให้การงดเว้นอย่างต่อเนื่องเป็นหนทางที่แข็งแกร่งที่สุดในการฟื้นตัวต่อไป\n\nภาพที่กว้างขึ้น\nสำหรับผู้ใหญ่ที่เริ่มมีอาการและใช้ยาเพียงเล็กน้อย แนวโน้มจะดีขึ้น ผู้คนจำนวนมากในช่วง 6 เดือนรายงานว่ามีความคิดที่ชัดเจนขึ้น การตัดสินใจที่มั่นคงมากขึ้น และความรู้สึกในการชี้ทิศทางตนเองมากขึ้นประโยชน์สูงสุดมาจากการไม่ละเว้น โดยเฉพาะหลังจากใช้งานหนักหรือเริ่มมีอาการตั้งแต่เนิ่นๆ';

  @override
  String get marijuanaReferenceDay365 =>
      'หนึ่งปีที่ไม่มีกัญชา โครงสร้างสมองจะฟื้นตัว\n\nที่มา: \"อันตรายของ Hippocampal การป้องกัน และการฟื้นตัวหลังจากการใช้กัญชาเป็นประจำ\" Translational Psychiatry (2016) บน PubMed Central\n\nการเปลี่ยนแปลงโครงสร้างจากกัญชา\nการศึกษาด้วยการสแกนสมองนี้ตรวจสอบฮิบโปแคมปัส ซึ่งเป็นพื้นที่สมองที่เป็นศูนย์กลางของหน่วยความจำในผู้ใช้ปัจจุบัน ผู้ใช้เดิม และผู้ที่ไม่ใช่ผู้ใช้ผู้ใช้ปัจจุบันที่ไม่ได้รับ CBD มีฮิบโปแคมปัสเล็กกว่าประมาณ 11% และเครื่องหมายสุขภาพเซลล์สมองต่ำกว่ากลุ่มควบคุมประมาณ 15%\n\nการค้นพบที่สำคัญ: การฟื้นฟูด้วยการเลิกบุหรี่\nการวิเคราะห์แบบ Curve-fitting รองรับโมเดล \"การป้องกันและการกู้คืน\"สิ่งสำคัญที่สุดคือ ผู้ใช้เก่าซึ่งละเว้นเป็นเวลาเฉลี่ยประมาณ 29 เดือน ไม่ได้แตกต่างจากการควบคุมการไม่ใช้งานมาตรการวัดความสมบูรณ์ใดๆผู้เขียนสรุปว่าอันตรายต่อพื้นที่ความจำที่เกี่ยวข้องกับ THC \"สามารถฟื้นตัวได้ด้วยการงดเว้นเป็นระยะเวลานาน\"\n\nการฟื้นฟูสมองในระยะเวลาหนึ่งปีหรือมากกว่านั้น\nเมื่อหนึ่งปีปลอดกัญชา ระบบความจำของสมองก็เข้าสู่การฟื้นฟูได้ดี ขนาดของฮิปโปแคมปัสและสุขภาพของเซลล์สมองกำลังกลับสู่ภาวะปกติ ช่วยสนับสนุนความจำและการควบคุมอารมณ์\n\nสัญญาณการกู้คืน\nผู้ใช้เก่าที่งดเว้นเป็นเวลาประมาณ 29 เดือนจะจับคู่ผู้ที่ไม่ใช่ผู้ใช้ตามมาตรการด้านสุขภาพของฮิบโปแคมปัสของการศึกษาในหนึ่งปี ระบบหน่วยความจำกำลังเคลื่อนไปตามเส้นทางการกู้คืนที่บันทึกไว้สู่ภาวะปกติ';

  @override
  String get mdmaReferenceDay1 =>
      'หลังจาก MDMA: The Comedown\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): มุมมองปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ\n\nทำไมคุณถึงรู้สึกต่ำ\nMDMA ทำงานโดยการขับเซโรโทนินออกมาจำนวนมาก (โดยมีโดปามีนอยู่บ้าง)หลังจากนั้นสมองจะสูญเสียเซโรโทนินชั่วคราวบทวิจารณ์นี้อธิบายถึงอารมณ์ที่ลดลง หรือที่เรียกว่า \"อาการบลูส์กลางสัปดาห์\" ซึ่งนักวิจัยวัดจากผู้ใช้มือใหม่และผู้มีประสบการณ์ 2 ถึง 5 วันหลังการใช้งาน\n\nช่วยอะไร.\n• การให้ความชุ่มชื้นและอาหารที่มีคุณค่าทางโภชนาการ\n• นอนหลับ\n• ความอดทน — การลดลงคือการสิ้นเปลือง ไม่ใช่สภาวะถาวร\n\nการลดลงหลังจากการใช้ครั้งเดียวแตกต่างจากการถอนตัวที่เกี่ยวข้องกับการพึ่งพาอาศัยกัน ซึ่งการทบทวนเดียวกันอธิบายว่าเกี่ยวข้องกับความอยาก แต่ไม่มีอาการทางกายภาพที่มีนัยสำคัญ';

  @override
  String get mdmaReferenceDay3 =>
      'ไม่กี่วันหลังจาก MDMA\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): มุมมองปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ\n\nบลูส์กลางสัปดาห์\nนี่เป็นช่วงคร่าวๆ ที่รีวิวนี้อธิบายเมื่อพูดถึง \"อาการบลูส์กลางสัปดาห์\" — อารมณ์ที่ลดลงซึ่งวัดได้ 2 ถึง 5 วันหลังการใช้ทั้งในผู้ใช้มือใหม่และผู้ใช้ที่มีประสบการณ์ ซึ่งเชื่อมโยงกับการสูญเสียเซโรโทนินในระยะสั้นมากกว่าการเปลี่ยนแปลงในระยะยาว\n\nสิ่งที่ทำให้ดีขึ้น\n• โดยทั่วไปอารมณ์จะดีขึ้นจากจุดต่ำสุดในตอนนี้\n• พลังงานกลับคืนมา\n• การนอนหลับเริ่มเข้าสู่ภาวะปกติ';

  @override
  String get mdmaReferenceDay7 =>
      'หนึ่งสัปดาห์หลังจาก MDMA\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): มุมมองปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ\n\nบลูส์กลางสัปดาห์ที่ผ่านมา\nสำหรับคนส่วนใหญ่ หนึ่งสัปดาห์ผ่านไปจากกรอบเวลา 2 ถึง 5 วัน การทบทวนนี้เกี่ยวข้องกับการลดลงอย่างรวดเร็ว ดังนั้น อารมณ์จึงควรกลับมาเป็นปกติการทบทวนตั้งข้อสังเกตว่าสำหรับผู้ที่รับประทานอาหารหนักหรือรับประทานซ้ำๆ ความอยากอาหารอาจคงอยู่โดยเป็นส่วนหนึ่งของรูปแบบการพึ่งพาอาศัยกัน แม้ว่าจะไม่ได้อธิบายว่าสิ่งนี้เกี่ยวข้องกับอาการถอนตัวทางกายภาพที่มีนัยสำคัญก็ตาม\n\nเมื่อใดควรขอความช่วยเหลือ\nหากอารมณ์ไม่ดี วิตกกังวล หรือปัญหาการนอนหลับยังคงมีอยู่ตลอดหนึ่งสัปดาห์ นั่นอาจเป็นมากกว่าอาการทรุดลง คุ้มค่าที่จะพูดคุยกับผู้เชี่ยวชาญ';

  @override
  String get mdmaReferenceDay14 =>
      'ปิด MDMA สองสัปดาห์\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): มุมมองปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ\n\nเส้นเวลาการกู้คืน\nสำหรับการหยุดใช้ครั้งเดียว เวลาสองสัปดาห์จะเกินกว่าเอกสารการทบทวนนี้ที่ลดลง 2 ถึง 5 วัน ดังนั้นอารมณ์ การนอนหลับ และสมาธิจึงควรคงที่หลังจากการใช้ในปริมาณมากหรือซ้ำหลายครั้ง การฟื้นตัวจะดำเนินต่อไปหลังการเลิกบุหรี่ และการศึกษาภาพการเลิกบุหรี่แสดงให้เห็นว่าความสามารถในการรีไซเคิลเซโรโทนินเพิ่มขึ้นตามการเลิกบุหรี่อย่างต่อเนื่อง\n\nสิ่งนี้มีความหมายต่อคุณอย่างไร\nหากคุณใช้เป็นครั้งคราว คุณก็ผ่านพ้นจุดเลวร้ายไปได้หากเป็นบ่อยหรือหนักมาก ให้อดทนกับตัวเอง การฟื้นตัวของสัญญาณเซโรโทนินอย่างสมบูรณ์เป็นกระบวนการที่ใช้เวลานานกว่าสองสัปดาห์ ซึ่งจะครอบคลุมในเหตุการณ์สำคัญถัดไป';

  @override
  String get mdmaReferenceDay30 =>
      'งด MDMA หนึ่งเดือน\n\nที่มา: \"ความพร้อมในการขนย้ายเซโรโทนิน การทำงานของระบบประสาทรับรู้ และความสัมพันธ์ในผู้ใช้ MDMA ที่งดเว้น\" บน PubMed\n\nที่ซึ่งหนึ่งเดือนนั่งอยู่\nการล้มลงและการถอนตัวแบบเฉียบพลันนั้นอยู่เบื้องหลังคุณแล้ว และอารมณ์ ความคิด และความทรงจำก็มั่นคงมากขึ้นการวิจัยด้วยภาพแสดงให้เห็นว่า MDMA ลดความสามารถของสมองในการประมวลผลเซโรโทนิน และความสามารถนี้จะฟื้นตัวได้ด้วยการเลิกบุหรี่อย่างต่อเนื่อง\n\nสัญญาณการกู้คืน\nงานวิจัยเดียวกันนี้แสดงให้เห็นว่าความสามารถในการรีไซเคิลเซโรโทนินฟื้นตัวได้ด้วยการเลิกบุหรี่อย่างต่อเนื่องฟังก์ชั่นอารมณ์และเซโรโทนินจะดีขึ้นก่อน ในขณะที่ความทรงจำยังคงดำเนินต่อไปตามไทม์ไลน์การฟื้นตัวของตัวเอง การงดเว้นอย่างต่อเนื่องจะสนับสนุนทั้งสองอย่าง';

  @override
  String get mdmaReferenceDay90 =>
      'ส่วนลด MDMA สามเดือน\n\nที่มา: \"ความพร้อมในการขนย้ายเซโรโทนิน การทำงานของระบบประสาทรับรู้ และความสัมพันธ์ในผู้ใช้ MDMA ที่งดเว้น\" บน PubMed\n\nการกู้คืนอย่างต่อเนื่อง\nด้วยการงดเว้นอย่างต่อเนื่อง ระบบเซโรโทนินของสมองยังคงฟื้นตัว โดยเฉพาะในบริเวณส่วนลึกของสมองโดยทั่วไปแล้วอารมณ์และการนอนหลับจะคงที่เมื่อถึงจุดนี้\n\nสัญญาณการกู้คืน\nการเลิกบุหรี่อย่างต่อเนื่องจะช่วยกระตุ้นการฟื้นตัวของตัวขนส่งเซโรโทนินทั่วบริเวณสมอง ในขณะที่อารมณ์และการนอนหลับยังคงมีเสถียรภาพ และการฟื้นตัวของความคิดและความทรงจำยังคงดำเนินต่อไป';

  @override
  String get mdmaReferenceDay365 =>
      'ปิด MDMA หนึ่งปี\n\nที่มา: \"ความพร้อมในการขนย้ายเซโรโทนิน การทำงานของระบบประสาทรับรู้ และความสัมพันธ์ในผู้ใช้ MDMA ที่งดเว้น\" บน PubMed\n\nหนึ่งปีผ่านไป\nเมื่องดเว้นไปหนึ่งปี การประมวลผลเซโรโทนินในสมองก็ฟื้นตัวขึ้นอย่างมาก และอารมณ์ก็คงที่\n\nสัญญาณการกู้คืน\nการงดเว้นหนึ่งปีเต็มจะทำให้ระบบเซโรโทนินมีระยะเวลาฟื้นตัวยาวนานขึ้นการวิจัยด้วยภาพแสดงให้เห็นว่าความสามารถในการรีไซเคิลเซโรโทนินเพิ่มขึ้นเมื่อมีการเลิกบุหรี่ ทำให้การกู้คืนเซโรโทนินจำนวนมากเป็นสัญญาณทางชีววิทยาที่ชัดเจนที่สุดในขั้นตอนนี้';

  @override
  String get methReferenceDay1 =>
      'การถอนยาบ้า: 24 ชั่วโมงแรก\n\nที่มา: McGregor และคณะ \"ธรรมชาติ ระยะเวลา และความรุนแรงของการถอนยาบ้า\" Addiction (2005) บน PubMed\n\nความผิดพลาด\nเมทแอมเฟตามีนขับโดปามีนออกมาจำนวนมากเมื่อหยุดใช้งานระบบจะหมดลงการศึกษานี้ติดตามอาการถอนยาทุกวันในช่วงสามสัปดาห์แรกของการเลิกบุหรี่ และพบว่าความรุนแรงโดยรวมจะสูงสุดภายใน 24 ชั่วโมงหลังการใช้ครั้งล่าสุด ซึ่งก็คือ \"การหยุดทำงาน\" ซึ่งเป็นอาการที่ผันผวนอย่างกะทันหันจากการกระตุ้นที่รุนแรงไปจนถึงความเหนื่อยล้าทางร่างกายและจิตใจ\n\nอาการวันแรก\nการศึกษาบันทึกคุณลักษณะการถอนเงินที่รุนแรงที่สุดในขณะนี้:\n• เหนื่อยล้าอย่างมากและนอนหลับเพิ่มขึ้น (นอนไม่หลับ)\n• ความอยากอาหารเพิ่มขึ้น (ยาบ้าระงับความอยากอาหารอย่างรุนแรง)\n• อารมณ์ซึมเศร้าและสูญเสียความสุข\n• ความอยากอาหารอย่างรุนแรง\n• ความวิตกกังวลและหงุดหงิด\n\nความปลอดภัยทางกายภาพ\nกลุ่มอาการถอนยาบ้าโดยทั่วไปไม่ได้เป็นอันตรายถึงชีวิต แต่อาการที่เกี่ยวข้องกับภาวะซึมเศร้าที่วัดได้ในการศึกษานี้อาจรุนแรงตั้งแต่เนิ่นๆ และอาจรวมถึงการคิดฆ่าตัวตายด้วยแนะนำให้มีการดูแลทางการแพทย์โดยเฉพาะอย่างยิ่งสำหรับผู้ใช้ที่มีน้ำหนักมาก\n\nมันเริ่มที่จะยก\nข้อค้นพบที่ให้กำลังใจจากการวิจัยครั้งนี้: ความรุนแรงจะสูงสุดตั้งแต่เริ่มต้นแล้วล้มลงจากจุดสูงสุดใน 24 ชั่วโมงนี้ อาการจะลดลงเรื่อยๆ ในวันต่อๆ ไป จุดที่แย่ที่สุดคือจุดเริ่มต้น';

  @override
  String get methReferenceDay3 =>
      'การถอนยาบ้า: วันที่สาม – ยังอยู่ในระยะเฉียบพลัน\n\nที่มา: McGregor และคณะ \"ธรรมชาติ ระยะเวลา และความรุนแรงของการถอนยาบ้า\" Addiction (2005) บน PubMed\n\nลงมาจากยอดเขา\nการศึกษานี้พบว่าความรุนแรงของการถอนโดยรวมจะถึงจุดสูงสุดภายใน 24 ชั่วโมงแรก จากนั้นลดลงในรูปแบบเส้นตรงโดยประมาณตลอดระยะเฉียบพลัน (ประมาณ 7–10 วัน)ในวันที่สาม คุณจะผ่านจุดสูงสุดไปแล้ว แต่ยังอยู่ในระยะเฉียบพลัน อาการต่างๆ ยังคงเด่นชัดแม้ว่าแนวโน้มจะลดลงก็ตาม\n\nอาการวันที่สาม\nคุณลักษณะที่การศึกษาติดตามซึ่งยังคงมีนัยสำคัญในขณะนี้:\n• อาการซึมเศร้าและการสูญเสียความสุข\n• ความอยากอาหารอย่างรุนแรง\n• มีสมาธิและคิดไม่ชัดเจน\n• การนอนหลับรบกวน — นอนไม่หลับสลับกับการนอนไม่หลับมากเกินไป\n• เหนื่อยล้าอย่างต่อเนื่อง\n\nเหตุใดจึงรู้สึกเช่นนี้\nความรุนแรงของการถอนยานี้สะท้อนถึงระดับของการสูญเสียโดปามีนที่เกิดขึ้นอาการที่เกี่ยวข้องกับภาวะซึมเศร้าที่การศึกษาวัดได้ชัดเจนที่สุดในช่วงแรกๆ เหล่านี้ แต่ที่สำคัญคือ การศึกษาพบว่าความรุนแรงโดยรวมของอาการถอนยา \'ลดลงจนเกือบควบคุมได้ภายในสิ้นสัปดาห์แรกของการเลิกบุหรี่\'\n\nสิ่งนี้จะผ่านไป\nช่วงที่ยากที่สุดคือช่วงสองสามวันแรก และข้อมูลแสดงการลดลงอย่างต่อเนื่องจากจุดนี้การทำความเข้าใจสภาวะนี้เป็นเพียงชั่วคราวและสมองและเส้นประสาท — ไม่ใช่ภาวะถาวร — ช่วยในการผ่านมันไปได้';

  @override
  String get methReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่มียาบ้า: ระยะเฉียบพลันสิ้นสุดลง\n\nที่มา: McGregor และคณะ \"ธรรมชาติ ระยะเวลา และความรุนแรงของการถอนยาบ้า\" Addiction (2005) บน PubMed\n\nสิ้นสุดระยะเฉียบพลัน\nนี่เป็นหนึ่งในข้อค้นพบที่ให้กำลังใจมากที่สุดในการวิจัยผลการศึกษารายงานว่าความรุนแรงของการถอนยาโดยรวม รวมถึงอาการที่เกี่ยวข้องกับภาวะซึมเศร้าที่ติดตามมา \'ลดลงจนเกือบควบคุมได้ภายในสิ้นสัปดาห์แรกของการเลิกบุหรี่\' ถือเป็นการสิ้นสุดระยะเฉียบพลันส่วนที่ชันที่สุดของการปีนอยู่ข้างหลังคุณ\n\nการถอนเงินสองขั้นตอน\nผู้เขียนอธิบายว่าการถอนยาบ้านั้นมี:\n• ระยะเฉียบพลันซึ่งกินเวลาประมาณ 7-10 วัน ซึ่งความรุนแรงของอาการลดลงอย่างต่อเนื่องจากจุดสูงสุดในช่วงแรก\n• ระยะกึ่งเฉียบพลันที่กินเวลาต่อไปอีกอย่างน้อยสองสัปดาห์ โดยมีอาการรุนแรงขึ้นและคงอยู่\n\nสิ่งที่เหลืออยู่ในวันที่ 7\nเมื่อเข้าสู่ระยะกึ่งเฉียบพลัน ความท้าทายหลักตอนนี้อยู่ที่ด้านจิตวิทยามากกว่าความผิดพลาดแบบเฉียบพลัน:\n• อารมณ์ไม่ดี แม้ว่าจะดีขึ้นมากตั้งแต่วันแรกก็ตาม\n• ความอยาก โดยเฉพาะอย่างยิ่งในการตอบสนองต่อสัญญาณ\n• สมาธิและความจำยังคงฟื้นตัว\n• นอนหลับยังคงสงบ\n\nการฟื้นฟูทางกายภาพอยู่ระหว่างดำเนินการ\nเมื่อระยะเฉียบพลันสิ้นสุดลง ความอยากอาหารก็กลับมาอีกครั้งและพลังงานก็ค่อยๆ สร้างขึ้นในขณะที่ร่างกายฟื้นตัวจากผลกระทบของยาที่มีต่อการนอนหลับ โภชนาการ และระบบหัวใจและหลอดเลือด';

  @override
  String get methReferenceDay30 =>
      'หนึ่งเดือนที่ไม่มียาบ้า: อารมณ์จะสงบลง ความอยากยังคงอยู่\n\nที่มา: Zorick et al., \"อาการถอนยาในผู้ป่วยที่เลิกใช้ยาบ้า\" Addiction (2010) บน PubMed Central\n\nติดตามห้าสัปดาห์แรก\nการศึกษานี้ติดตามผู้เข้าร่วมที่ติดยาบ้าซึ่งงดเว้นนานถึงห้าสัปดาห์ โดยเปรียบเทียบกับกลุ่มควบคุมที่ดีต่อสุขภาพ โดยให้ภาพที่ชัดเจนอย่างผิดปกติว่าระดับหนึ่งเดือนอยู่ที่ใด\n\nสิ่งที่ได้รับการปรับปรุงภายในหนึ่งเดือน\n• อาการซึมเศร้า \'ลดลงอย่างมากในช่วง 2 สัปดาห์แรกของการงดเว้นจนถึงระดับต่ำคงที่\' และเมื่อสิ้นสี่สัปดาห์ก็ใกล้เข้ามา แม้ว่าจะยังไม่ตรงกันทางสถิติ ระดับการควบคุมที่ดี (ช่องว่างแคบลงจนถึงเส้นเขตแดน แนวโน้มที่ไม่มีนัยสำคัญ)\n• อาการทางจิตเวชและโรคจิตเริ่มถึงระดับต่ำภายในสิ้นสัปดาห์ที่สอง\nดังนั้น เมื่อผ่านไป 30 วัน ความหดหู่อย่างหนักของการถอนตัวก่อนกำหนดจึงได้บรรเทาลงอย่างมาก ซึ่งเป็นการปรับปรุงที่วัดผลได้อย่างแท้จริง\n\nสิ่งที่ยังคงอยู่\nการศึกษาแสดงให้เห็นชัดเจนว่าอาการหนึ่งยังคงอยู่นานกว่าอาการอื่นๆ กล่าวคือ ความอยาก \'ยังคงดำเนินต่อไปในระดับที่ลดลงตลอด 5 สัปดาห์ของการงดเว้น\'ความอยากอาหารจะอ่อนลงกว่าในสัปดาห์แรกแต่ยังไม่หายไป ซึ่งเป็นเหตุผลว่าทำไมหนึ่งเดือนจึงยังคงเป็นช่วงเวลาที่มีความเสี่ยงสูงและต้องมีการสนับสนุนอย่างต่อเนื่อง\n\nซื้อกลับบ้าน\nภายในหนึ่งเดือน กลไกทางอารมณ์ของสมองจะฟื้นตัวมากพอที่จะทำให้ความรู้สึกในแต่ละวันดีขึ้นกว่าการถอนตัวตั้งแต่เนิ่นๆ ในขณะที่ความอยากอาหารอย่างต่อเนื่องถือเป็นเรื่องปกติของระยะนี้ ไม่ใช่สัญญาณของความล้มเหลว';

  @override
  String get methReferenceDay90 =>
      'สามเดือนโดยไม่ต้องปรุงยา: การรักษาได้เริ่มต้นขึ้นแล้ว - จงอดทน\n\nที่มา: Volkow et al., \"การสูญเสียผู้ขนส่งโดปามีนในผู้เสพยาบ้าฟื้นตัวด้วยการงดเว้นเป็นเวลานาน\" วารสารประสาทวิทยาศาสตร์ (2544)\n\nเกี่ยวกับงานวิจัยนี้\nการศึกษาสแกนสมองครั้งสำคัญนี้ติดตามผู้ใช้ยาบ้าสองครั้ง โดยประมาณ 3 เดือน งดยาบ้า และอีกครั้งประมาณ 14 เดือน เพื่อดูว่าระบบโดปามีนฟื้นตัวได้อย่างไร\n\nที่ซึ่งสามเดือนนั่งอยู่\nเมื่อถึงสามเดือน ระยะเวลาถอนตัวก่อนกำหนดจะสิ้นสุดลงอีกต่อไป และกำลังมีการฟื้นตัวของโดปามีนในระดับลึกยิ่งขึ้นการศึกษาเดียวกันนี้พบในภายหลังว่าโปรตีนที่รีไซเคิลโดปามีนในบริเวณรางวัลและการเคลื่อนไหวของสมองเพิ่มขึ้นประมาณ 16% ถึง 19% หลังจากงดยา 12-17 เดือน\n\nนั่นหมายถึงอะไรสำหรับคุณ\nเมื่อผ่านไป 90 วัน อาการถอนตัวเฉียบพลันจะตามมาไม่ทันคุณ อารมณ์และการนอนหลับก็ดีขึ้น และการมีส่วนร่วมกับการบำบัดก็มีประสิทธิผลมากขึ้นมากแต่การฟื้นตัวของโดปามีนในระดับลึกนั้นเป็นโครงการที่ยาวนานกว่าซึ่งจะเปิดตัวในปีต่อไปหากแรงจูงใจและความสุขยังคงเงียบงันในสามเดือน นั่นก็เป็นสิ่งที่คาดหวังและไม่ใช่สัญญาณของความล้มเหลว แนวโน้มในการศึกษานี้มีแนวโน้มสูงขึ้นอย่างเห็นได้ชัด\n\nเหตุใดจึงคุ้มค่ากับการรอคอย\nการศึกษาเดียวกันนี้แสดงให้เห็นว่าการงดเว้นคือสิ่งที่ผลักดันให้เกิดการฟื้นตัว ยิ่งการงดเว้นนานเท่าใด การฟื้นตัวของ DAT ก็จะยิ่งวัดได้มากขึ้นเท่านั้นสามเดือนเป็นรากฐานกำไรมาเรื่อยๆ';

  @override
  String get methReferenceDay180 =>
      'หกเดือนโดยไม่ต้องปรุงยา: หัวใจสามารถฟื้นตัวได้\n\nที่มา: \"การหยุดการใช้ยาในทางที่ผิดสามารถย้อนกลับความเสียหายที่เกี่ยวข้องกับหัวใจ\" American College of Cardiology (2017) รายงานการศึกษาใน JACC: หัวใจล้มเหลว\n\nยาบ้าและหัวใจ\nเมทแอมเฟตามีนเป็นหนึ่งในยาสันทนาการที่เป็นพิษต่อหัวใจมากที่สุดอาจทำให้เกิดภาวะความดันโลหิตสูงและภาวะหัวใจเต้นผิดจังหวะอย่างรุนแรง และเมื่อเวลาผ่านไปอาจเกิดภาวะคาร์ดิโอไมโอแพทีที่เกี่ยวข้องกับยาบ้า ซึ่งส่งผลให้กล้ามเนื้อหัวใจอ่อนแอลงซึ่งนำไปสู่ภาวะหัวใจล้มเหลว\n\nสิ่งที่การศึกษาพบ\nACC รายงานเกี่ยวกับผู้ป่วยที่เป็นโรคคาร์ดิโอไมโอแพทีที่เกี่ยวข้องกับยาบ้า (ทั้งหมดมีการทำงานของหัวใจสูบฉีดลดลงอย่างมีนัยสำคัญ)การค้นพบที่สำคัญและมีความหวัง: การเลิกสูบบุหรี่ \'สามารถย้อนกลับความเสียหายที่ยาทำให้เกิดต่อหัวใจและปรับปรุงการทำงานของหัวใจได้\'ผู้ป่วยที่หยุดใช้มีผลลัพธ์ที่ดีกว่าอย่างเห็นได้ชัดมากกว่าผู้ที่ยังคงใช้ต่อไป และผู้เขียนเน้นย้ำว่าการได้รับยาตั้งแต่เนิ่นๆ สามารถป้องกันการเสื่อมสภาพของคาร์ดิโอไมโอแพทีได้อีก\n\nทำไมหกเดือนจึงมีความสำคัญ\nการงดเว้นทุกเดือนจะช่วยขจัดความเครียดที่เป็นพิษต่อหัวใจ และช่วยให้กล้ามเนื้อฟื้นตัวได้เมื่อถึงหกเดือน คุณได้ทำให้ระบบหัวใจและหลอดเลือดของคุณฟื้นตัวจากความเสียหายนั้นได้อย่างต่อเนื่องและยาวนาน ซึ่งเป็นภาวะที่การศึกษานี้ดีขึ้นอย่างแน่นอน\n\nสัญญาณการกู้คืน\nผลลัพธ์ที่มีหลักฐานสนับสนุนชัดเจนคือการหยุดยาบ้าสามารถฟื้นฟูความเสียหายของหัวใจที่เกี่ยวข้องกับยาบ้า และปรับปรุงการทำงานของหัวใจหกเดือนโดยไม่มีการดูถูกสารกระตุ้นซ้ำๆ จะทำให้หัวใจฟื้นตัวได้มาก';

  @override
  String get methReferenceDay365 =>
      'หนึ่งปีที่ไม่มียาบ้า: การฟื้นฟูสมองที่วัดได้\n\nที่มา: Wang et al., \"การฟื้นตัวบางส่วนของการเผาผลาญของสมองในผู้เสพยาบ้าหลังจากการเลิกบุหรี่เป็นเวลานาน\" American Journal of Psychiatry (2004) บน PubMed\n\nสิ่งที่ภาพแสดงให้เห็น\nการศึกษาสแกนสมองนี้ตรวจสอบผู้ใช้ยาบ้าตั้งแต่เนิ่นๆ และอีกครั้งหลังจากผ่านไป 12–17 เดือนพบว่ามีการฟื้นตัวของสมองอย่างแท้จริง โดยบางพื้นที่ฟื้นตัวได้เร็วกว่าบริเวณอื่น\n\nข่าวดี: การฟื้นฟูสมองและการคิดอย่างลึกซึ้ง\nฐานดอกซึ่งเป็นศูนย์ถ่ายทอดสมองส่วนลึก เริ่มใช้พลังงานตามปกติมากขึ้นด้วยการงดเว้นในระยะยาวการฟื้นตัวนั้นติดตามได้ด้วยการเคลื่อนไหวที่ดีขึ้นและประสิทธิภาพของความจำทางวาจา ดังนั้นการปรับปรุงการสแกนสมองจึงปรากฏในการคิดและความทรงจำที่แท้จริง\n\nวงจรรางวัลจะฟื้นตัวช้าลง\nเมื่ออายุ 12-17 เดือน ศูนย์ถ่ายทอดสมองส่วนลึกฟื้นตัวอย่างแข็งแกร่ง และติดตามการเคลื่อนไหวและความจำทางวาจาได้ดีขึ้นระบบการให้รางวัลและแรงจูงใจยังคงแข็งแกร่งขึ้นเช่นกัน ทำให้ภาพรวมหนึ่งปีเป็นหนึ่งในการฟื้นฟูครั้งใหญ่ในด้านความคิดและความทรงจำ\n\nนี่หมายถึงอะไรในหนึ่งปี\nในหนึ่งปี คาดหวังว่าสมองจะคิดและจดจำได้ดีกว่าการฟื้นตัวตั้งแต่เนิ่นๆ มาก ซึ่งเป็นการรักษาที่ชัดเจนและวัดผลได้แต่หากแรงจูงใจหรือความสามารถในการรู้สึกเพลิดเพลินยังคงล่าช้าในบางครั้ง ซึ่งสอดคล้องกับหลักวิทยาศาสตร์ ไม่ใช่ความล้มเหลวส่วนบุคคล การศึกษานี้พบว่าวงจรการให้รางวัลเหล่านั้นสามารถฟื้นตัวได้ช้ากว่า โดยที่การขาดดุลบางส่วนยังคงปรากฏให้เห็นในปีที่ผ่านมา';

  @override
  String get methReferenceDay420 =>
      '14 เดือนโดยไม่มียาบ้า: เครื่องหมายโดปามีนดีดตัวขึ้น\n\nที่มา: Volkow et al., \"การสูญเสียผู้ขนส่งโดปามีนในผู้เสพยาบ้าฟื้นตัวด้วยการงดเว้นเป็นเวลานาน\" วารสารประสาทวิทยาศาสตร์ (2544)\n\nการค้นหาหัวข้อข่าว\nการศึกษาวิจัยด้วยการสแกนสมองครั้งสำคัญนี้ตรวจสอบผู้ใช้ยาบ้าตั้งแต่เนิ่นๆ และอีกครั้งหลังจากนั้นประมาณ 12–17 เดือนโปรตีนที่รีไซเคิลโดปามีนเพิ่มขึ้นประมาณ 16% ถึง 19% ในบริเวณรางวัลและการเคลื่อนไหวของสมอง และถึงระดับที่ไม่แตกต่างอย่างมีนัยสำคัญจากการควบคุมเพื่อสุขภาพอีกต่อไปการงดเว้นนานขึ้นหมายถึงการฟื้นตัวที่มากขึ้น\n\nเหตุใด DAT จึงมีความสำคัญ\nโปรตีนเหล่านี้จะรีไซเคิลโดปามีนหลังจากที่ปล่อยออกมายาบ้าทำให้พวกมันหมดสิ้นลง ทำให้ระบบโดปามีนมีการควบคุมไม่ดีการฟื้นตัวภายในเวลาประมาณ 14 เดือนถือเป็นสัญญาณของการฟื้นตัวอย่างแท้จริงและวัดผลได้\n\nสัญญาณการกู้คืน\nหลังจากผ่านไป 12–17 เดือน โปรตีนที่รีไซเคิลโดปามีนในพื้นที่รางวัลและการเคลื่อนไหวเพิ่มขึ้นประมาณ 16% ถึง 19% และถึงระดับที่ควบคุมได้ดีระบบโดปามีนฟื้นตัวเข้าสู่ภาวะปกติได้อย่างวัดผลได้ ในขณะที่การคิด ความจำ และการเคลื่อนไหวดีขึ้นอย่างต่อเนื่อง\n\nสิ่งนี้หมายความว่าอย่างไรเมื่ออายุ 14 เดือน\nฮาร์ดแวร์ของระบบโดปามีนกำลังฟื้นตัวสู่ภาวะปกติได้อย่างวัดผลได้ ซึ่งเป็นสาเหตุที่แท้จริงของการมองโลกในแง่ดีแต่การฟื้นตัวแบบเต็มรูปแบบ (หน่วยความจำ แรงจูงใจ การควบคุมการเคลื่อนไหว) อาจล้าหลังการถ่ายภาพ และปรับปรุงต่อไปด้วยการงดเว้นอย่างต่อเนื่อง';

  @override
  String get methReferenceDay730 =>
      'สองปีที่ไม่มียาบ้า: ความคิดและอารมณ์ดีขึ้นเรื่อยๆ\n\nที่มา: Iudicello และคณะ \"การปรับปรุงการทำงานระบบประสาทรับรู้ในระยะยาวและความทุกข์ทางอารมณ์ในกลุ่มผู้ใช้ยาบ้าที่บรรลุภาวะเลิกบุหรี่อย่างคงที่\" วารสารประสาทวิทยาทางคลินิกและการทดลอง (2010) บน PubMed Central\n\nการฟื้นตัวที่ดำเนินต่อไปในปีที่ผ่านมา\nการศึกษานี้ติดตามผู้ใช้ยาบ้าเป็นเวลาประมาณ 13 เดือน และเปรียบเทียบผู้ที่ไม่รับประทานยาคงที่กับผู้ใช้ที่ใช้ยาต่อเนื่องและการควบคุมที่ดีการงดเว้นอย่างต่อเนื่องทำให้การคิดโดยรวมดีขึ้น และลดความทุกข์ทางอารมณ์ โดยเพิ่มขึ้นต่อเนื่องเกินหนึ่งปี\n\nสิ่งที่ทำให้ดีขึ้น\n• การคิดโดยรวมเกี่ยวกับผู้ที่ไม่สูบบุหรี่ขึ้นอยู่กับการควบคุมที่ดี ในขณะที่ผู้ใช้ที่ยังคงรู้สึกบกพร่องอย่างมีนัยสำคัญ\n• สิ่งที่ได้ประโยชน์สูงสุดคือความเร็วในการประมวลผลและความสามารถของมอเตอร์ โดยเฉพาะอย่างยิ่งสำหรับผู้ที่มีความบกพร่องมากที่สุดตั้งแต่เริ่มต้น\n• อารมณ์ดีขึ้นอย่างเห็นได้ชัด: มีเพียงผู้ที่ไม่ทานอาหารเท่านั้นที่มีอาการซึมเศร้าและอารมณ์โดยรวมดีขึ้นอย่างเห็นได้ชัด\n\nสัญญาณการกู้คืน\nผู้ที่งดเว้นอย่างสม่ำเสมอสามารถควบคุมการคิดโดยรวมได้ดีและรายงานว่ามีความทุกข์ทางอารมณ์น้อยลงการเรียนรู้ด้วยวาจา ความจำในการทำงาน การวางแผน และการมุ่งเน้นสามารถพัฒนาต่อไปได้หลังจากปีแรก ดังนั้นแนวโน้มการฟื้นตัวจะดำเนินต่อไปจนถึงปีที่สอง\n\nสองปีใน\nข้อความตามหลักฐานเชิงประจักษ์: การเลิกบุหรี่อย่างต่อเนื่องจะให้ผลตอบแทนที่ดีในช่วงปีแรก — มีความคิดที่เฉียบคมขึ้น อารมณ์ดีขึ้น และปรับปรุงการทำงานอย่างต่อเนื่อง — แม้ว่าบางพื้นที่จะใช้เวลานานกว่าในการกลับมาอีกครั้งก็ตาม';

  @override
  String get nitrousOxideReferenceDay1 =>
      'วันแรก: น้ำมันหมด แต่ดู B12\n\nที่มา: Knuf & Maani, \"ไนตรัสออกไซด์\" StatPearls (ชั้นวางหนังสือ NCBI)\n\nเคลียร์ได้เร็วแค่ไหน\nไนตรัสออกไซด์ออกฤทธิ์อย่างรวดเร็วภายใน 2 ถึง 5 นาที และจะออกจากร่างกายอย่างรวดเร็วพอๆ กับที่คุณหยุดหายใจเข้าไปจนถึงวันนี้ ไม่มีก๊าซเหลืออยู่ในระบบของคุณเลย\n\nความเสี่ยงที่แท้จริงไม่ใช่แก๊ส\nสิ่งสำคัญหลังจากการหยุดคือสิ่งที่อาจเกิดขึ้นซ้ำๆ ไปแล้วไนตรัสออกไซด์ไปยับยั้งเมไทโอนีนซินเทส ซึ่งเป็นเอนไซม์ที่อาศัยวิตามินบี 12StatPearls ตั้งข้อสังเกตว่าการสัมผัสซ้ำๆ ทั้งในด้านการประกอบอาชีพหรือสันทนาการ สามารถนำไปสู่โรคโลหิตจางชนิดเมกาโลบลาสติก ความผิดปกติของสมองและเส้นประสาท และในบางกรณีซึ่งพบไม่บ่อยก็คือการเสื่อมของไขสันหลัง\n\nหากคุณใช้งานหนักหรือบ่อยครั้ง\nไนตรัสออกไซด์ไม่ได้ถูกบันทึกไว้ว่าทำให้เกิดอาการถอนยาได้เช่นเดียวกับที่ฝิ่นหรือแอลกอฮอล์เกิดขึ้น ดังนั้น วันแรกจึงไม่เกี่ยวกับว่าร่างกายของคุณเรียกร้องยาเป็นเรื่องเกี่ยวกับการเริ่มให้ความสนใจกับอาการที่เกี่ยวข้องกับวิตามินบี 12 ซึ่งจะครอบคลุมในอีกไม่กี่เหตุการณ์สำคัญถัดไป และเข้ารับการตรวจดูว่ามีอาการใด ๆ เกิดขึ้นหรือไม่';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 ชั่วโมง: ไม่มีการถอนตัว แต่ให้สังเกตอาการทางประสาท\n\nที่มา: Knuf & Maani, StatPearls;ทิคาเรีย และคณะ(2026), คิวเรียส\n\nไนตรัสออกไซด์ต่างจากฝิ่นหรือแอลกอฮอล์ตรงที่ไม่มีการบันทึกว่าทำให้เกิดอาการถอนตัวทางกายภาพสิ่งกระตุ้นในระยะนี้คือนิสัยและความอยาก ไม่ใช่ร่างกายเรียกร้องให้ยาทำงาน\n\nระวังสิ่งเหล่านี้\nการทบทวนอย่างเป็นระบบในกรณีที่มีไนตรัสออกไซด์เพื่อการพักผ่อนหย่อนใจจำนวน 1,809 ราย (Tikaria et al., 2026) พบว่าอาการของสมองและเส้นประสาท โดยเฉพาะการรู้สึกเสียวซ่าหรืออาการชา (อาชา) เป็นสัญญาณที่พบบ่อยที่สุดของอันตรายที่เกี่ยวข้องกับวิตามินบี 12 ซึ่งมักจะปรากฏแม้ว่าการตรวจเลือดแบบมาตรฐานจะดูปกติก็ตามมีรายงานปัญหาการเดินและความอ่อนแอด้วย\n\nหากคุณสังเกตเห็นสิ่งเหล่านี้\nไปพบแพทย์.การทบทวนเดียวกันพบว่าการตรวจเลือดมาตรฐาน (ฮีโมโกลบิน เซรั่ม B12) พลาดส่วนแบ่งที่สำคัญของผู้ป่วยที่ได้รับผลกระทบ การทดสอบกรดเมทิลมาโลนิก (MMA) และโฮโมซิสเทอีนมีความไวมากกว่า และควรขอเป็นพิเศษหากคุณเปิดเผยการใช้ไนตรัสออกไซด์';

  @override
  String get nitrousOxideReferenceDay7 =>
      'หนึ่งสัปดาห์: รับการทดสอบหากคุณใช้งานหนัก\n\nที่มา: Tikaria และคณะ(2026), \"มรดกที่เป็นพิษของการใช้ไนตรัสออกไซด์เพื่อการพักผ่อนหย่อนใจ\" Cureus\n\nสิ่งที่แสดงหลักฐาน\nการทบทวนอย่างเป็นระบบนี้พบว่าการขาดวิตามินบี 12 จากไนตรัสออกไซด์มักจะ \"ใช้งานได้\" โดยซีรั่มบี 12 ดูปกติในผู้ป่วยที่ได้รับผลกระทบประมาณครึ่งหนึ่ง แม้ว่าพวกเขาจะมีความเสียหายต่อสมองและเส้นประสาทจริงๆ ก็ตามHomocysteine ​​และ MMA มีความผิดปกติบ่อยกว่ามาก (84% และ 73% ของผู้ป่วยที่ได้รับการทดสอบตามลำดับ) และเป็นตัวบ่งชี้ที่น่าเชื่อถือมากกว่า\n\nจะทำอย่างไร\nหากการใช้ของคุณหนักหรือบ่อยครั้ง การหยุดหนึ่งสัปดาห์เป็นเวลาที่เหมาะสมในการไปพบแพทย์และขอการทดสอบโฮโมซิสเทอีนและ MMA โดยเฉพาะ ไม่ใช่แค่ระดับวิตามินบี 12 มาตรฐาน โดยเฉพาะอย่างยิ่งหากคุณมีอาการรู้สึกเสียวซ่า ชา ปัญหาการทรงตัว หรือความอ่อนแอที่ไม่สามารถอธิบายได้\n\nการฟื้นตัวของสมองเป็นเรื่องปกติหลังจากการหยุดไนตรัสและการรักษาด้วยวิตามินบี 12: ชุดข้อมูลทางคลินิกขนาดใหญ่รายงานการปรับปรุงบางส่วนหรือทั้งหมดในผู้ป่วยที่ติดตามส่วนใหญ่ โดยจะฟื้นตัวต่อเนื่องในช่วงเดือนแรกหลังการรักษา';

  @override
  String get nitrousOxideReferenceDay14 =>
      'สองสัปดาห์: อาการทางสมองและเส้นประสาทควรติดตามผล\n\nที่มา: Tikaria และคณะ(2026), คิวเรียส;คนุฟ & มาอานี, สเตทเพิร์ลส์\n\nสิ่งที่ได้รับรายงาน\nรายงานกรณีและซีรีส์ที่ตรวจสอบโดย Tikaria และคณะอธิบายความเสียหายของเส้นประสาทที่เกี่ยวข้องกับไนตรัสออกไซด์ซึ่งแสดงเป็นการสูญเสียประสาทสัมผัส การเดินผิดปกติ และบางครั้งความอ่อนแอที่ส่งผลต่อการเดิน - การค้นพบนี้อาจคล้ายกับสภาพสมองและเส้นประสาทของ other และบางครั้งก็อาจพลาดหากไม่ได้กล่าวถึงการใช้ไนตรัสออกไซด์กับแพทย์\n\nสัญญาณการกู้คืนบนไทม์ไลน์\nแหล่งที่มาทั้งสองแห่งไม่ได้รายงานว่าโดยปกติจะใช้เวลาฟื้นตัวนานเท่าใดเมื่อหยุดใช้และรักษาข้อบกพร่องใดๆ แล้วรายงานผู้ป่วยอธิบายถึงผลลัพธ์ที่หลากหลาย ตั้งแต่การฟื้นตัวเต็มที่ไปจนถึงการขาดดุลที่ยั่งยืน ขึ้นอยู่กับความเสียหายที่เกิดขึ้นก่อนการวินิจฉัยเป็นส่วนใหญ่สิ่งที่สอดคล้องกันในวรรณกรรมก็คือการรักษาตั้งแต่เนิ่นๆ นำไปสู่ผลลัพธ์ที่ดีกว่า\n\nหากคุณยังไม่ได้รับการตรวจสอบ\nการหยุดสองสัปดาห์ยังเป็นเวลาที่ดีที่จะไปเจาะเลือด แม้ว่าจะไม่มีอาการใดๆก็ตาม โดยเฉพาะโฮโมซิสเทอีนและ MMA แทนที่จะใช้เซรั่มบี 12 เพียงอย่างเดียว';

  @override
  String get nitrousOxideReferenceDay30 =>
      'หนึ่งเดือน: นิสัยและความอยาก ไม่ใช่การพึ่งพาทางกายภาพ\n\nที่มา: Knuf & Maani, \"ไนตรัสออกไซด์\" StatPearls (ชั้นวางหนังสือ NCBI)\n\nที่คุณยืนอยู่\nStatPearls ไม่ได้อธิบายว่าไนตรัสออกไซด์ทำให้เกิดอาการพึ่งพาทางกายภาพ ดังนั้นการหยุดหนึ่งเดือนหมายถึงการกระตุ้นที่ยืดเยื้อใดๆ เกี่ยวข้องกับนิสัย บริบททางสังคม หรือความเบื่อหน่าย มากกว่าที่ร่างกายจะปรับตัวกับการไม่มียา\n\nคำถาม B12\nหากคุณได้รับการทดสอบและรักษาอาการขาดวิตามินบี 12 เป็นเวลาหนึ่งเดือนที่แพทย์จะตรวจสอบว่าระดับของคุณและอาการต่างๆ ตอบสนองหรือไม่หากคุณไม่ได้รับการทดสอบและใช้งานอย่างหนัก ก็ยังคุ้มค่าที่จะถาม\n\nสิ่งที่ได้รับการคุ้มครอง\nทุกเดือนที่คุณไม่ได้ใช้คือหนึ่งเดือนที่คุณไม่ได้เพิ่มการยับยั้งการสังเคราะห์เมไทโอนีนที่มีอยู่หรือความเสี่ยงต่อสมองและเส้นประสาทที่มาพร้อมกับมัน';

  @override
  String get nitrousOxideReferenceDay90 =>
      'สามเดือน: ถึงเวลาตรวจสอบอีกครั้ง หากคุณยังไม่ได้\n\nที่มา: Tikaria และคณะ(2026), \"มรดกที่เป็นพิษของการใช้ไนตรัสออกไซด์เพื่อการพักผ่อนหย่อนใจ\" Cureus\n\nสิ่งที่เรารู้ - และไม่รู้\nฐานการวิจัยนี้สร้างขึ้นจากรายงานกรณีและชุดกรณี ไม่ใช่การศึกษาการฟื้นตัวที่มีการควบคุม ดังนั้นจึงไม่มีการเผยแพร่ไทม์ไลน์ที่เชื่อถือได้สำหรับวิธีที่อาการต่างๆ จะได้รับการแก้ไขภายในสามเดือนโดยเฉพาะสิ่งที่หลักฐานแสดงให้เห็นก็คือผลลัพธ์ที่ได้นั้นแตกต่างกันไปอย่างมาก ผู้ป่วยบางรายที่มีความบกพร่องเล็กน้อยและตรวจพบได้ตั้งแต่เนิ่นๆ จะฟื้นตัวได้เต็มที่ ในขณะที่ผู้ที่มีการวินิจฉัยล่าช้าหรือความเสียหายของเส้นประสาทที่รุนแรงกว่านั้นอาจมีภาวะขาดดุลได้ยาวนาน\n\nส่วนที่ดำเนินการได้\nหากคุณมีอาการทางสมองและเส้นประสาท และไม่ได้รับการตรวจเลือดหรือการตรวจโดยผู้เชี่ยวชาญ การหยุดสามเดือนถือเป็นจุดที่สมเหตุสมผลหากคุณได้รับการรักษาและปรับปรุง นี่เป็นเวลาที่เหมาะสมในการยืนยันว่าแนวโน้มยังคงดำเนินต่อไปกับแพทย์ของคุณ\n\nการอยู่ห่างๆ เป็นเรื่องสำคัญที่สุด\nการตรวจสอบมีความสอดคล้องในเรื่องหนึ่ง: การได้รับสารอย่างต่อเนื่องจะทำให้ B12 หยุดทำงานและเพิ่มความเสี่ยงการไม่ใช้เป็นปัจจัยเดียวที่ใหญ่ที่สุดที่ทำให้คุณโปรดปราน';

  @override
  String get nitrousOxideReferenceDay365 =>
      'หนึ่งปี: การป้องกันที่ดีที่สุดคือการงดเว้นอย่างต่อเนื่อง\n\nที่มา: Knuf & Maani, StatPearls;ทิคาเรีย และคณะ(2026), คิวเรียส\n\nในกรณีที่หลักฐานปรากฏจริง\nไม่มีแหล่งข้อมูลใดที่ให้คำมั่นสัญญาถึงกำหนดเวลาการฟื้นตัวที่เฉพาะเจาะจง และนั่นก็คุ้มค่าที่จะพูดตามตรง วรรณกรรมเกี่ยวกับการขาดไนตรัสออกไซด์และวิตามินบี 12 สร้างขึ้นเกือบทั้งหมดจากรายงานผู้ป่วยรายบุคคล แทนที่จะเป็นการศึกษาติดตามผลในระยะยาวสิ่งที่เป็นที่ยอมรับกันดีก็คือกลไก: ไนตรัสออกไซด์จะยับยั้งการทำงานของวิตามินบี 12 ทุกครั้งที่ใช้ และการหยุดจะขจัดอันตรายที่ดำเนินอยู่ออกไปโดยสิ้นเชิง\n\nหากคุณมีอาการที่เกี่ยวข้องกับการขาด\nรายงานผู้ป่วยอธิบายถึงผลลัพธ์ที่หลากหลาย ตั้งแต่การฟื้นตัวอย่างสมบูรณ์ไปจนถึงอาการของเส้นประสาทที่คงอยู่ ซึ่งส่วนใหญ่เชื่อมโยงกับความเสียหายที่เกิดขึ้นและระยะเวลาในการรักษาหากคุณยังคงประสบกับอาการต่างๆ เป็นเวลาหนึ่งปี นั่นเป็นเหตุผลที่คุณควรทำงานร่วมกับนักประสาทวิทยาต่อไป ไม่ใช่สัญญาณว่าทำอะไรไม่ได้ การฟื้นฟูเส้นประสาทสามารถดำเนินต่อไปได้เป็นระยะเวลานาน\n\nมีอะไรแน่นอน\nปีที่ปราศจากไนตรัสออกไซด์คือหนึ่งปีที่ไม่มีการยับยั้งการทำงานของเมไทโอนีนซินเทสอีกต่อไปนั่นคือการรับประกันว่าทั้งสองแหล่งสนับสนุน';

  @override
  String get opioidReferenceDay1 =>
      'การถอน Opioid: วันแรก\n\nที่มา: \"แนวทางทางคลินิกสำหรับการจัดการการถอนและการรักษาผู้ติดยาในพื้นที่ปิด\" องค์การอนามัยโลก (2552) บนชั้นวางหนังสือ NCBI\n\n⚠ หมายเหตุด้านความปลอดภัย\nการถอนฝิ่นไม่ค่อยเป็นอันตรายถึงชีวิตในบุคคลที่มีสุขภาพดี แต่จะทำให้เกิดความทุกข์ทรมานทางร่างกายอย่างรุนแรงและมีความเสี่ยงสูงที่จะกลับมาเป็นอีกการกลับเป็นซ้ำหลังจากการงดเว้นช่วงระยะเวลาหนึ่งเป็นอันตรายอย่างยิ่ง เนื่องจากความอดทนลดลงอย่างรวดเร็ว การใช้ยาในขนาดเดียวกันกับก่อนเลิกบุหรี่อาจทำให้เกิดการใช้ยาเกินขนาดถึงแก่ชีวิตได้แนะนำให้มีการดูแลทางการแพทย์และการรักษาด้วยตัวเอกฝิ่น\n\nเมื่อการถอนเริ่มต้นขึ้น\nตารางเวลาการถอนตัวของ WHO กำหนดเวลาตามประเภทฝิ่น:\n• ฝิ่นที่ออกฤทธิ์สั้น (เฮโรอีน ออกซีโคโดน): เริ่มมีอาการ 8–24 ชั่วโมงหลังการใช้ครั้งสุดท้าย ระยะเวลา 4–10 วัน\n• ฝิ่นที่ออกฤทธิ์นาน (เมทาโดน): เริ่มมีอาการ 12–48 ชั่วโมง ระยะเวลา 10–20 วัน\n\nอาการวันแรก\nหลักเกณฑ์ของ WHO ระบุคุณลักษณะเบื้องต้นของการถอนฝิ่น:\n• ความวิตกกังวลและความกระวนกระวายใจ\n• ปวดกล้ามเนื้อและปวดเมื่อย\n• มีน้ำไหลออกจากตาและจมูก\n• หาวและเหงื่อออก\n• นอนไม่หลับ โดยมีอาการร้อนวูบวาบ\n• คลื่นไส้ในระยะเริ่มแรก\n\nทำไมมันรู้สึกแย่จัง\nระบบฝิ่นควบคุมความเจ็บปวด ความเครียด สุขภาพทางอารมณ์ และความสบายขั้นพื้นฐานการใช้ฝิ่นในระยะยาวจะยับยั้งการผลิตฝิ่น (เอ็นดอร์ฟิน) ของร่างกายเมื่อกำจัดฝิ่นออก ร่างกายจะขาดระบบความสะดวกสบายตามปกติ โดยประสบกับความเจ็บปวด ความวิตกกังวล และความทุกข์ทรมานในระดับที่สะท้อนถึงความลึกของการปราบปรามนั้นแนวทางของ WHO แนะนำให้มีการดูแลแบบประคับประคอง รวมถึงการดื่มน้ำวันละ 2-3 ลิตร และติดตามดูวันละ 3-4 ครั้ง';

  @override
  String get opioidReferenceDay7 =>
      'หยุดใช้ยา Opioids หนึ่งสัปดาห์: อาการสูงสุดลดลง\n\nที่มา: \"แนวทางทางคลินิกสำหรับการจัดการการถอนและการรักษาผู้ติดยาในพื้นที่ปิด\" องค์การอนามัยโลก (2552) บนชั้นวางหนังสือ NCBI\n\nจุดสูงสุดและความเสื่อมถอย\nตารางเวลาของ WHO กำหนดให้การถอนฝิ่นที่ออกฤทธิ์สั้นคือ 4-10 วัน โดยอาการจะเกิดขึ้นตั้งแต่เนิ่นๆ แล้วค่อยผ่อนคลายในช่วงนั้นภายในสิ้นสัปดาห์แรก:\n• การอาเจียนและท้องร่วงจะได้รับการแก้ไขเป็นส่วนใหญ่\n• ตะคริวของกล้ามเนื้อมีความรุนแรงน้อยลง\n• ความทุกข์ทางกายลดลงอย่างเห็นได้ชัด\n\nสิ่งที่เหลืออยู่ในวันที่ 7\nแม้ว่าอาการทางกายภาพเฉียบพลันจะดีขึ้น แต่ปัญหาสำคัญยังคงมีอยู่:\n• นอนไม่หลับ — การหยุดชะงักของการนอนหลับเป็นหนึ่งในอาการถอนฝิ่นที่คงอยู่นานที่สุด\n• อารมณ์หดหู่และอารมณ์เรียบ\n• เหนื่อยล้าและอ่อนแรง\n• ความอยากอาหาร\n• ความวิตกกังวล\n\nการถอนตัวหลังเฉียบพลัน\nหลังจากช่วงถอนยาครั้งแรก ปัญหาการนอนหลับ อารมณ์ที่เปลี่ยนไป และความอยากอาหารอาจดำเนินต่อไปเป็นเวลาหลายสัปดาห์หรือหลายเดือนการสนับสนุนอย่างต่อเนื่องมีความสำคัญมากที่สุดในช่วงระยะการกู้คืนที่ยาวนานขึ้นนี้\n\nการรักษาด้วยตัวเอกฝิ่น\nแนวปฏิบัติของ WHO อธิบายว่าเมทาโดนและบูพรีนอร์ฟีนเป็นวิธีการรักษาที่มีประสิทธิภาพซึ่งช่วยลดความรุนแรงของการถอนยาและช่วยให้ฟื้นตัวได้ยาเหล่านี้ยังช่วยลดอัตราการเสียชีวิตจากความผิดปกติจากการใช้ยาฝิ่น และผู้คนจำนวนมากที่ประสบความสำเร็จในการฟื้นตัวในระยะยาวก็ใช้ยาเหล่านี้ตลอดระยะฟื้นตัวระยะแรกๆ';

  @override
  String get opioidReferenceDay14 =>
      'งดฝิ่นสองสัปดาห์: รูปแบบการนอนเริ่มดีขึ้น\n\nที่มา: งานวิจัยทางเภสัชวิทยาที่ผ่านการตรวจสอบโดยผู้ทรงคุณวุฒิเกี่ยวกับฝิ่นและการนอนหลับ\n\nการเชื่อมต่อ Opioid-Sleep\nบทความวิจัยนี้ตรวจสอบความสัมพันธ์แบบสองทิศทางระหว่างการใช้ฝิ่นกับการรบกวนการนอนหลับเอกสารการค้นพบที่ว่าฝิ่นขัดขวางสถาปัตยกรรมการนอนหลับปกติอย่างรุนแรงผ่านกลไกหลายประการ:\n• ระงับการนอนหลับแบบคลื่นช้า (ลึก)\n• รบกวนการนอนหลับ REM\n• ทำให้หายใจไม่สะดวก (หยุดหายใจขณะหลับส่วนกลาง)\n• รบกวนการควบคุมจังหวะการเต้นของหัวใจ\n\nวงจรอุบาทว์\nการวิจัยเน้นย้ำถึงธรรมชาติของปัญหาแบบสองทิศทาง กล่าวคือ การใช้ฝิ่นขัดขวางการนอนหลับ และการนอนหลับที่ไม่ดีจะเพิ่มความไวต่อความเจ็บปวดและความอยากอย่างรุนแรง ส่งผลให้มีการใช้ฝิ่นเพิ่มขึ้นการเลิกพึ่งพาสารฝิ่นยังหมายถึงการทำลายวงจรการรบกวนการนอนหลับด้วย\n\nนอนตอนสองสัปดาห์\nเมื่องดฝิ่นเป็นเวลา 14 วัน การนอนหลับจะเริ่มเป็นปกติ:\n• ภาวะหยุดหายใจขณะหลับส่วนกลาง (ถ้ามี) จะหายไปภายในไม่กี่วัน\n• การนอนหลับลึกแบบคลื่นช้าๆ กำลังเริ่มฟื้นตัว\n• การนอนหลับ REM กำลังกลับสู่สัดส่วนปกติ\n• การนอนหลับเริ่มมีความน่าเชื่อถือมากขึ้น\n\nการนอนหลับยังคงเป็นความท้าทายที่สำคัญสำหรับหลายๆ คนในช่วงสองสัปดาห์ แต่แนวโน้มดีขึ้นอย่างเห็นได้ชัดการนอนหลับที่ดีขึ้นช่วยเพิ่มอารมณ์โดยตรง ลดความอยาก และสนับสนุนการคิดที่ชัดเจนซึ่งจำเป็นสำหรับการฟื้นฟู';

  @override
  String get opioidReferenceDay30 =>
      'งดฝิ่นหนึ่งเดือน: การคิดและความทรงจำเริ่มฟื้นตัว\n\nที่มา: เมโยคลินิก\n\nทำความเข้าใจเกี่ยวกับความผิดปกติในการใช้ฝิ่น\nมาโยคลินิกอธิบายว่าฝิ่นเกาะติดกับตัวรับทั่วสมองและร่างกาย ช่วยบรรเทาอาการปวด รู้สึกสบาย และง่วงนอนเมื่อใช้ซ้ำๆ สมองจะตอบสนองน้อยลงและผลิตสารเคมีคล้ายฝิ่นน้อยลงนั่นทำให้เกิดการพึ่งพาอาศัยกันทางกายภาพ\n\nการคิดและความทรงจำในหนึ่งเดือน\nเมื่อครบ 30 วัน การฟื้นตัวทางความคิดและความจำก็เกิดขึ้นอย่างมีความหมายหมอกสมองที่เลวร้ายที่สุดได้หายไปแล้ว และส่วนหน้าของสมองซึ่งทำหน้าที่เกี่ยวกับการวางแผนและการควบคุมตนเองก็กำลังฟื้นตัว:\n• การตัดสินใจกำลังดีขึ้น\n• หน่วยความจำในการทำงานกำลังฟื้นตัว\n• ความเร็วในการประมวลผลเพิ่มขึ้น\n• ความเข้มข้นเชื่อถือได้มากขึ้น\n\nระบบเอ็นโดรฟิน\nในหนึ่งเดือน ระบบเอ็นโดรฟินตามธรรมชาติของสมองกำลังฟื้นตัว โดยผลิตสารเคมีคล้ายฝิ่นของตัวเองมากขึ้น และตอบสนองได้ตามปกติมากขึ้นอีกครั้งความเรียบทางอารมณ์และความทนทานต่อความเจ็บปวดที่ลดลงจะดีขึ้นเรื่อยๆ ในขณะที่การฟื้นตัวดำเนินต่อไป\n\nการป้องกันการกำเริบของโรค\nMayo Clinic เน้นย้ำว่าการมีสติเป็นเวลาหนึ่งเดือนไม่ได้หมายความว่าความเสี่ยงของการกำเริบของโรคจะผ่านไปแล้ว แต่ยังคงเพิ่มสูงขึ้นความทนทานลดลงอย่างมีนัยสำคัญ ซึ่งหมายความว่าการกลับเป็นซ้ำโดยใช้ขนาดยาก่อนหน้านี้มีความเสี่ยงในการใช้ยาเกินขนาดอย่างร้ายแรง';

  @override
  String get opioidReferenceDay60 =>
      'งดฝิ่นสองเดือน: วงจรความเครียดของสมองเริ่มสงบลง\n\nที่มา: \"ความยืดหยุ่นของระบบประสาทของต่อมทอนซิลที่ขยายออกในการถอนฝิ่นและการงดฝิ่นเป็นเวลานาน\" Frontiers in Pharmacology (2023)\n\nความรู้สึกเชิงลบมาจากไหน\nการทบทวนนี้แสดงให้เห็นว่าการใช้ยาฝิ่นในระยะยาวเปลี่ยนแปลงวงจรความเครียดและความกลัวของสมองได้อย่างไรในระหว่างการถอน วงจรเหล่านี้จะทำงานมากเกินไปในขณะที่การส่งสัญญาณโดปามีนในวงจรรางวัลลดลงการผสมผสานดังกล่าวช่วยอธิบายความวิตกกังวล อารมณ์ไม่ดี และความอยากอาหารในช่วงฟื้นตัวเร็ว\n\nเหตุใดสองเดือนจึงช่วยบรรเทาได้\nสิ่งสำคัญที่สุดคือเอกสารการตรวจสอบว่าการเปลี่ยนแปลงบางส่วนสามารถย้อนกลับได้ในแบบจำลองสัตว์ การสูญเสียความหนาแน่นของกระดูกสันหลังในเปลือก accumbens ถูกอธิบายว่าเป็น \'การลดลงที่ยั่งยืนแต่สามารถย้อนกลับได้\' โดยกลับไปสู่ค่าก่อนใช้ยาในช่วงสองสามสัปดาห์เนื่องจากวงจรความเครียดและรางวัลเหล่านี้ควบคุมใหม่ กลไกพื้นฐานสำหรับความวุ่นวายทางอารมณ์ที่ฟื้นตัวเร็วจะบรรเทาลง ซึ่งสอดคล้องกับปฏิกิริยาที่ลดลงและอารมณ์ที่มั่นคงมากขึ้น ที่หลายคนรายงานภายในเวลาประมาณสองเดือน\n\nสัญญาณการกู้คืน\nการเปลี่ยนแปลงความหนาแน่นของกระดูกสันหลังและวงจรความเครียดแบบพลิกกลับได้ที่ได้รับการบันทึกไว้ในเอกสารนี้แสดงให้เห็นถึงกระบวนการฟื้นฟูทางชีวภาพที่แท้จริง: วงจรที่ขับเคลื่อนสภาวะทางอารมณ์เชิงลบของการพึ่งพาจะเคลื่อนกลับไปยังสถานะก่อนใช้ยาในระหว่างการเลิกบุหรี่';

  @override
  String get opioidReferenceDay90 =>
      'งดฝิ่นสามเดือน: เคมีของรางวัลเริ่มฟื้นตัว\n\nที่มา: \"การฟื้นฟูสมองเชิงโครงสร้างและการทำงานของบุคคลที่มีความผิดปกติในการใช้สารเสพติดระหว่างการเลิกบุหรี่: การทบทวนการศึกษาการสร้างภาพระบบประสาทตามยาว\" การพึ่งพายาและแอลกอฮอล์ (2022) บน PubMed Central\n\nโดปามีนและฝิ่น\nฝิ่นกระตุ้นการปล่อยโดปามีนในระบบการให้รางวัลของสมองการใช้งานระยะยาวทำให้ระบบหมดประสิทธิภาพ ในการศึกษาสแกนสมองครั้งหนึ่ง โปรตีนที่รีไซเคิลโดปามีนต่ำกว่าระดับปกติประมาณ 30% ในช่วงเริ่มต้นซึ่งช่วยอธิบายการสูญเสียความสุขที่พบในความผิดปกติจากการใช้ยาฝิ่นและการฟื้นตัวตั้งแต่เนิ่นๆ\n\nการฟื้นตัวเป็นแบบค่อยเป็นค่อยไป\nการทบทวนนี้รวบรวมการศึกษาระยะยาวที่สแกนคนกลุ่มเดียวกันเรื่องการเลิกบุหรี่อีกครั้งการขาดดุลโดปามีน-ผู้ขนส่งฟื้นตัวประมาณ 20% ในช่วง 6-12 เดือนของการงดเว้น และความผิดปกติของสารสีเทาและสารสีขาวที่หน้าผากบางส่วนที่พบในการถอนยาตั้งแต่เนิ่นๆ ไม่สามารถตรวจพบได้อีกต่อไปหลังจากผ่านไปประมาณหนึ่งเดือนเมื่อถึงสามเดือน คุณจะเข้าสู่ช่วงฟื้นตัวได้เร็ว ระบบการให้รางวัลและระบบส่วนหน้ากำลังซ่อมแซมอย่างวัดผลได้ แต่ยังไม่เสร็จสิ้น\n\nสิ่งที่ผู้คนสัมผัส\nเมื่อวงจรเหล่านี้ฟื้นตัว ผู้คนจำนวนมากจะสังเกตเห็นเมื่อผ่านไปประมาณ 90 วัน:\n• เพลิดเพลินกับกิจกรรม อาหาร และความสัมพันธ์อย่างแท้จริงมากขึ้น\n• ความอยากอาหารลดลงเมื่อเทียบกับการฟื้นตัวตั้งแต่เนิ่นๆ\n• การคิดที่ชัดเจนและการตัดสินใจที่ดีขึ้น\n\nสัญญาณการกู้คืน\nการถ่ายภาพตามยาวของมนุษย์แสดงให้เห็นว่าความพร้อมของสารโดปามีนและการขนส่งเพิ่มขึ้นในช่วง 6-12 เดือนของการงดเว้น ในขณะที่ความผิดปกติของสารสีเทาและสีขาวที่หน้าผากเริ่มเป็นปกติเร็วกว่ามากเมื่อครบ 90 วัน การฟื้นฟูสมองที่วัดผลได้ก็เกิดขึ้นแล้ว';

  @override
  String get opioidReferenceDay180 =>
      'งดฝิ่นหกเดือน: ระบบภูมิคุ้มกันเริ่มฟื้นตัว\n\nที่มา: \"ผลของความทนทานต่อฝิ่นและการถอนฝิ่นต่อระบบภูมิคุ้มกัน\" วารสารเภสัชวิทยาประสาทวิทยา (2549) บน PubMed\n\nฝิ่นและระบบภูมิคุ้มกัน\nการทบทวนนี้แสดงให้เห็นว่าการใช้ฝิ่นในระยะยาวทำให้ระบบภูมิคุ้มกันอ่อนแอลงได้หลายวิธี:\n• การออกฤทธิ์ฝิ่นโดยตรงต่อเซลล์ภูมิคุ้มกัน (ทีเซลล์, เซลล์ NK, มาโครฟาจ)\n• รบกวนสารเคมีส่งสัญญาณภูมิคุ้มกัน\n• การหยุดชะงักของแกนไฮโปดีพ สมอง ต่อมใต้สมอง ต่อมหมวกไต (HPA)\n• เพิ่มความไวต่อการติดเชื้อ\n\nสัญญาณการกู้คืน\nฝิ่นในระยะยาวจะไปกดระบบภูมิคุ้มกันหลายส่วนเมื่อเลิกใช้ยากลุ่มฝิ่นเป็นเวลาหกเดือน การระงับอย่างต่อเนื่องนั้นก็หายไปเป็นเวลาครึ่งปี และการทำงานของระบบภูมิคุ้มกันก็กำลังฟื้นตัวสู่ภาวะปกติ\n\nหกเดือนหมายถึงอะไร\nการไม่มีฝิ่นเป็นเวลา 6 เดือนจะทำให้เซลล์ภูมิคุ้มกัน การส่งสัญญาณของภูมิคุ้มกัน และระบบความเครียดของร่างกายมีเวลาที่จะฟื้นตัวเข้าสู่ภาวะปกติได้อย่างยั่งยืน\n\nทำไมเรื่องนี้ถึงยังมีความสำคัญ\nสิ่งนี้มีความเกี่ยวข้องเป็นพิเศษสำหรับผู้ที่ฉีดฝิ่น ซึ่งเผชิญกับความเสี่ยงในการติดเชื้อเพิ่มเติม เช่น เอชไอวีและไวรัสตับอักเสบซี การกำจัดฝิ่น การปรับปรุงโภชนาการ และการเลิกบุหรี่จะทำให้ระบบภูมิคุ้มกันมีภาวะที่จำเป็นต่อการฟื้นตัว';

  @override
  String get opioidReferenceDay365 =>
      'งดฝิ่นหนึ่งปี: โครงสร้างสมองและการฟื้นฟูทางเคมี\n\nที่มา: \"การฟื้นฟูสมองเชิงโครงสร้างและการทำงานของบุคคลที่มีความผิดปกติในการใช้สารเสพติดระหว่างการเลิกบุหรี่: การทบทวนการศึกษาการสร้างภาพระบบประสาทตามยาว\" การพึ่งพายาและแอลกอฮอล์ (2022) บน PubMed Central\n\nสิ่งที่แสดงโดยการถ่ายภาพมนุษย์\nการทบทวนนี้รวบรวมการศึกษาที่สแกนคนกลุ่มเดียวกันที่มีความผิดปกติในการใช้ฝิ่นมากกว่าหนึ่งครั้งในการเลิกบุหรี่ข้อค้นพบชี้ไปที่การฟื้นตัวอย่างต่อเนื่อง:\n• โปรตีนที่รีไซเคิลโดปามีนในพื้นที่รางวัลและการเคลื่อนไหว ซึ่งต่ำกว่าปกติประมาณ 30% ในช่วงเริ่มต้น เพิ่มขึ้นประมาณ 20% ในช่วง 6-12 เดือนจากการเลิกใช้ยากลุ่มฝิ่น\n• ความผิดปกติของสารสีเทาที่หน้าผากในการถอนยาตั้งแต่เนิ่นๆ ไม่สามารถตรวจพบได้อีกต่อไปหลังจากเลิกบุหรี่ไปประมาณหนึ่งเดือน\n• สารสีขาว (หน้าผากและซิงกูเลท) และการทำงานของหน้าผากในสภาวะพักก็เริ่มกลับมาเป็นปกติอีกครั้งภายในเดือนแรก\n\nที่ที่หนึ่งปีนั่งอยู่\nภายใน 12 เดือน คุณอยู่หรือเลยกรอบเวลาที่ยาวนานที่สุดที่การศึกษาเหล่านี้วัดได้ระบบโดปามีนมีเวลาฟื้นตัวมากที่สุด และวงจรหน้าผากที่สนับสนุนการควบคุมตนเองและการตัดสินได้รับการแก้ไขเป็นเวลาหลายเดือน ซึ่งเป็นคู่ทางชีววิทยาของการคิดที่ชัดเจนขึ้น ความอยากที่ลดลง และอารมณ์ที่มั่นคงมากขึ้นที่ผู้คนบรรยายในหนึ่งปี\n\nสัญญาณการกู้คืน\nในหนึ่งปี สัญญาณการถ่ายภาพของมนุษย์มุ่งเน้นไปที่การฟื้นฟูอย่างมาก: ความพร้อมใช้งานของสารโดปามีนและการขนส่งเพิ่มขึ้นในช่วง 6-12 เดือน ในขณะที่ความผิดปกติของโครงสร้างและการทำงานของหน้าผากต้องใช้เวลาหลายเดือนเพื่อทำให้เป็นปกติ';

  @override
  String get opioidReferenceDay730 =>
      'สองปีจาก Opioids: รากฐานที่มั่นคง\n\nที่มา: \"การรักษาความผิดปกติของการใช้ฝิ่น\" ศูนย์ควบคุมและป้องกันโรค (CDC)\n\nภาวะเรื้อรัง จัดการได้ดี\nCDC อธิบายความผิดปกติจากการใช้ฝิ่นว่าเป็น \"โรคเรื้อรังที่อาจส่งผลกระทบต่อทุกคน\" - \"เป็นภาวะทางการแพทย์ ไม่ใช่ความล้มเหลวทางศีลธรรม\"การฟื้นตัวอย่างต่อเนื่องเป็นเวลาสองปีหมายความว่าคุณได้จัดการกับภาวะดังกล่าวได้สำเร็จผ่านช่วงที่มีความเสี่ยงมากที่สุดช่วงหนึ่ง\n\nสิ่งที่ CDC บอกว่าใช้ได้ผล\nคำแนะนำของ CDC มุ่งเน้นไปที่การรักษาที่ช่วยให้การฟื้นตัวมีเสถียรภาพในระยะยาว:\n• ยาสำหรับความผิดปกติจากการใช้ฝิ่น เช่น บูพรีนอร์ฟีน เมทาโดน และนัลเทรกโซน ซึ่งเรียกว่ามีประสิทธิผลเป็นพิเศษ\n• ผสมผสานการใช้ยากับการบำบัดพฤติกรรมและการให้คำปรึกษา\n• การรักษาที่คงอยู่ตามระยะเวลาที่แตกต่างกัน โดยปรับให้เหมาะกับแต่ละบุคคล\nCDC ตั้งข้อสังเกตว่ายาเหล่านี้ช่วย \'ปรับเคมีในสมองให้เป็นปกติ\' และบรรเทาความอยากอาหาร สารเคมีที่รู้สึกว่าถูกแย่งชิงจากการเสพติดที่ใช้งานอยู่จะกลับมาได้ผลกับคุณอีกครั้ง\n\nอยู่อย่างปลอดภัย\nCDC กระตุ้นให้ผู้ที่ฟื้นตัวควรถามแพทย์เกี่ยวกับความเสี่ยงในการกลับมาใช้ยาเกินขนาดและใช้ยาเกินขนาด และควรเตรียมนาล็อกโซนไว้ความอดทนจะลดลงในระหว่างการเลิกบุหรี่ ดังนั้นการกลับมาใช้ยาฝิ่นหลังจากผ่านไปเป็นเวลานานจึงเป็นอันตรายอย่างยิ่ง การรู้ว่านั่นเป็นส่วนหนึ่งของการปกป้องสิ่งที่คุณสร้างขึ้น\n\nสองปีใน\nCDC ชัดเจนว่าการฟื้นฟูมักเป็นกระบวนการระยะยาวมากกว่าเส้นชัยสองปีไม่ใช่จุดสิ้นสุดของการเดินทาง แต่เป็นรากฐานที่มั่นคงและแข็งแรง และเป็นหลักฐานที่ชัดเจนว่าแนวทางที่คุณใช้ได้ผล';

  @override
  String get pornographyReferenceDay1 =>
      'วันแรก: การควบคุมกลับคืน\n\nที่มา: Kraus et al., ความผิดปกติของพฤติกรรมทางเพศซึ่งบีบบังคับใน ICD-11, World Psychiatry (2018)\n\nปัญหาที่สำคัญทางคลินิกไม่ใช่การใช้สื่อลามกเพียงอย่างเดียวความผิดปกติของพฤติกรรมทางเพศซึ่งบีบบังคับ หมายถึง ปัญหาที่เกิดขึ้นอย่างต่อเนื่องในการควบคุมพฤติกรรมทางเพศซ้ำๆ เมื่อรูปแบบนั้นทำให้เกิดความทุกข์ทรมานหรือความบกพร่องอย่างมากการใช้สื่อลามกที่เป็นปัญหาสามารถเป็นหนึ่งในการนำเสนอปัญหาที่กว้างขึ้นได้\n\nนั่นทำให้วันแรกเป็นรูปธรรมมากกว่าเป็นเรื่องลึกลับ คุณได้ขัดขวางพฤติกรรมที่คุณตัดสินใจว่าอยู่เหนือการควบคุมหนึ่งวันที่เสร็จสิ้นไม่ได้พิสูจน์ว่าสมองและเส้นประสาทรีเซ็ตได้ แต่จะทำให้คุณสังเกตได้จริงเป็นครั้งแรกว่าเมื่อใดที่มีสิ่งกระตุ้นเกิดขึ้น สถานการณ์ใดที่กระตุ้นให้เกิดสิ่งกระตุ้น และสิ่งที่คุณสามารถทำได้แทน\n\nหากการใช้งานของคุณไม่สร้างความลำบากใจ บกพร่อง หรือควบคุมได้ยาก กรอบการทำงาน CSBD ทางคลินิกอาจไม่มีผลกับคุณเหตุการณ์สำคัญเหล่านี้มุ่งเป้าไปที่ผู้ที่จงใจเปลี่ยนแปลงการใช้งานที่เป็นปัญหาหรือเป็นการบีบบังคับ';

  @override
  String get pornographyReferenceDay3 =>
      'วันที่สาม: รู้ว่าแรงกระตุ้นมีหน้าตาเป็นอย่างไร\n\nที่มา: Lewczuk และคณะ การถอนตัวและความอดทนที่เกี่ยวข้องกับความผิดปกติของพฤติกรรมทางเพศซึ่งบีบบังคับและการใช้สื่อลามกที่เป็นปัญหา วารสารการติดพฤติกรรม (2022)\n\nในตัวอย่างโปแลนด์ที่ลงทะเบียนล่วงหน้าในระดับประเทศของผู้ใหญ่ 1,541 ประสบการณ์ที่คล้ายกับการถอนตัวที่รายงานด้วยตนเองที่แข็งแกร่งกว่านั้นมีความสัมพันธ์กับ CSBD ที่มากขึ้นและความรุนแรงในการใช้สื่อลามกที่เป็นปัญหาในบรรดาผู้เข้าร่วมที่มีปัญหาการใช้สื่อลามก ประสบการณ์ที่รายงานโดยทั่วไป ได้แก่ ความคิดทางเพศที่หยุดยาก ความปรารถนาที่ควบคุมยาก ความเร้าอารมณ์ที่เพิ่มขึ้น ความหงุดหงิด อารมณ์เปลี่ยนแปลง และปัญหาการนอนหลับ\n\nความกระวนกระวายใจ ความคิดทางเพศที่ล่วงล้ำ ความต้องการที่รุนแรง และความหงุดหงิดได้รับการบันทึกไว้ในผู้ที่มีปัญหาการใช้งานที่รุนแรงกว่าหากพวกมันปรากฏขึ้นในช่วงวันที่สาม ให้ปฏิบัติต่อพวกมันเหมือนกับรูปแบบการถอนตัวที่แท้จริงและจัดการกับสิ่งกระตุ้น\n\nเขียนว่าสิ่งกระตุ้นใดที่เกิดขึ้นจริง อะไรเกิดขึ้นก่อนหน้านั้น และคำตอบใดที่ช่วยได้การฟื้นตัวจะควบคุมได้ง่ายขึ้นเมื่อมีการตั้งชื่อทริกเกอร์ แทนที่จะถือว่าเป็นเหตุการณ์ลึกลับในสมอง';

  @override
  String get pornographyReferenceDay7 =>
      'หนึ่งสัปดาห์: พบผลการศึกษาเรื่องการเลิกบุหรี่แบบสุ่ม\n\nที่มา: ผลของการงดสื่อลามก 7 วันต่ออาการที่เกี่ยวข้องกับการถอนตัวในผู้ใช้สื่อลามกทั่วไป เอกสารสำคัญของพฤติกรรมทางเพศ (2023)\n\nนักวิจัยสุ่มผู้ใช้สื่อลามกเป็นประจำ 176 คนเพื่อพยายามงดเว้นเจ็ดวันหรือดำเนินการต่อตามปกติจากกลุ่มตัวอย่างทั้งหมด การงดเว้นไม่ได้ทำให้ความอยาก อารมณ์เชิงลบ หรืออาการถอนเพิ่มขึ้นโดยรวมอย่างมีนัยสำคัญ\n\nการวิเคราะห์เชิงสำรวจพบว่ามีความอยากเพิ่มขึ้นในกลุ่มคนที่รวมคะแนนการใช้ที่เป็นปัญหาสูงเข้ากับการใช้สื่อลามกรายวันก่อนการศึกษาผลลัพธ์ดังกล่าวจำเป็นต้องมีการจำลองแบบ แต่มีประโยชน์: สัปดาห์แรกที่ยากลำบากอาจเป็นจริงสำหรับผู้ใช้ที่มีปัญหาหนักกว่า ในขณะที่การทดลองนี้ไม่รองรับกลุ่มอาการถอนสื่อลามกสากล\n\nหากคุณทำได้ตลอดทั้งสัปดาห์ ตอนนี้คุณมีหลักฐานเกี่ยวกับรูปแบบของคุณเองได้ดีกว่าไทม์ไลน์ทั่วไปทางอินเทอร์เน็ต';

  @override
  String get pornographyReferenceDay14 =>
      'สองสัปดาห์: วาดแผนที่ตัวกระตุ้นที่สำคัญจริงๆ\n\nที่มา: ตัวกำหนดทางจิตสังคมของการใช้สื่อลามกที่เป็นปัญหา: การทบทวนอย่างเป็นระบบ (2023)\n\nการทบทวนนี้สังเคราะห์การศึกษา 66 ชิ้นและพบว่าการใช้สื่อลามกที่เป็นปัญหานั้นสัมพันธ์กับปัจจัยหลายอย่างมากกว่ากลไกโดปามีนง่ายๆ กลไกเดียวปัจจัยทางจิตวิทยาและสังคมที่ระบุซ้ำแล้วซ้ำอีก ได้แก่ ความอยาก ความเครียด การหลีกเลี่ยง ความเหงา ความนับถือตนเอง ความเชื่อเชิงลบ และรูปแบบการเผชิญปัญหา\n\nสองสัปดาห์จะทำให้คุณได้สัมผัสกับวันธรรมดา วันหยุดสุดสัปดาห์ ความเบื่อหน่าย ความเครียด ความเป็นส่วนตัว อุปกรณ์ และบริบทของ other ซ้ำๆ ที่อาจบ่งบอกถึงพฤติกรรมเดิมๆใช้ข้อมูลนั้นหากความเครียดเป็นตัวกระตุ้น ให้ออกแบบการตอบสนองต่อความเครียดหากความเหงาเป็นตัวกระตุ้น ให้เพิ่มการติดต่อหากกระตุ้นการเข้าถึงได้ง่าย ให้เปลี่ยนสภาพแวดล้อม\n\nหลักฐานสนับสนุนการทำงานกับตัวขับเคลื่อนการใช้งานที่มีปัญหาไม่จำเป็นต้องแกล้งทำเป็นว่าทุกคนติดตามการนับถอยหลังทางชีวภาพแบบเดียวกัน';

  @override
  String get pornographyReferenceDay30 =>
      'หนึ่งเดือน: การควบคุมมีความสำคัญมากกว่าการนับความถี่ธรรมดา\n\nที่มา: Bőthe et al. ปัญหาการทำงานทางเพศเกี่ยวข้องกับการใช้สื่อลามกบ่อยครั้งและ / หรือการใช้สื่อลามกที่เป็นปัญหาหรือไม่ พฤติกรรมเสพติด (2021)\n\nในชุมชนตัวอย่างผู้ใหญ่ 14,581 คน การใช้สื่อลามกที่เป็นปัญหามีความสัมพันธ์เชิงบวกในระดับปานกลางกับปัญหาการทำงานทางเพศทั้งในชายและหญิงความถี่ในการใช้สื่อลามกโดยตัวมันเองแสดงให้เห็นความสัมพันธ์เชิงลบเล็กน้อยกับปัญหาเหล่านั้น\n\nความแตกต่างนั้นสำคัญหลักฐานไม่สนับสนุนการบอกผู้ใช้สื่อลามกทุกคนว่าความถี่ในการดูเพียงอย่างเดียวส่งผลต่อการทำงานทางเพศเป้าหมายที่เกี่ยวข้องทางคลินิกมากขึ้นคือการสูญเสียการควบคุมและปัญหาที่อยู่รอบรูปแบบนั้น\n\nในหนึ่งเดือน ให้เปรียบเทียบชีวิตตอนนี้กับตอนที่คุณเริ่มต้น: ความหมกมุ่น เวลาที่เสียไป ความสามารถในการหยุด การทำงานทางเพศ ความขัดแย้งในความสัมพันธ์ และความทุกข์ทรมานการเปลี่ยนแปลงเหล่านี้มีความสำคัญมากกว่าการรอการรีเซ็ตสมองในวันที่ 30 ในตำนาน';

  @override
  String get pornographyReferenceDay90 =>
      'สามเดือน: การเปลี่ยนแปลงที่ยั่งยืนเป็นไปได้\n\nที่มา: Crosby & Twohig การบำบัดด้วยการยอมรับและความมุ่งมั่นสำหรับการใช้สื่อลามกทางอินเทอร์เน็ตที่เป็นปัญหา: การทดลองแบบสุ่ม พฤติกรรมบำบัด (2016)\n\nการทดลองแบบสุ่มขนาดเล็กนี้เปรียบเทียบโปรแกรม ACT 12 เซสชันกับรายชื่อผู้รอในผู้ชายที่เป็นผู้ใหญ่ 28 คนการดูสื่อลามกลดลงมากในกลุ่ม ACT เมื่อสิ้นสุดการรักษา และการลดลงอย่างมากยังคงอยู่ที่การติดตามผลสามเดือน\n\nการศึกษาไม่ได้พิสูจน์ว่าการงดเว้น 90 วันเพียงอย่างเดียวให้ผลลัพธ์เดียวกัน และกลุ่มตัวอย่างมีขนาดเล็กและแคบทางประชากรศาสตร์สิ่งที่แสดงให้เห็นมีความสำคัญ: การใช้สื่อลามกที่เป็นปัญหาสามารถแก้ไขได้ และทักษะที่มีโครงสร้างสามารถทำให้เกิดการเปลี่ยนแปลงที่คงอยู่เกินระยะเวลาการรักษาทันที\n\nหากความก้าวหน้าของคุณยังคงขึ้นอยู่กับการลงมือทำเป็นส่วนใหญ่ สามเดือนก็เป็นจุดที่ดีในการเสริมสร้างระบบที่อยู่รอบ ๆ ตัวมัน: แผนการกระตุ้น การยอมรับสิ่งกระตุ้นโดยไม่ลงมือทำ ความขัดแย้งทางสิ่งแวดล้อม ความรับผิดชอบ และการบำบัดเมื่อจำเป็น';

  @override
  String get pornographyReferenceDay180 =>
      'หกเดือน: การควบคุมอาการในระยะยาวสามารถคงอยู่ได้\n\nที่มา: Hallberg และคณะ การศึกษาแบบสุ่มควบคุมของการบำบัดพฤติกรรมทางปัญญาแบบกลุ่มที่บริหารโดยกลุ่มสำหรับความผิดปกติทางเพศในผู้ชาย วารสารการแพทย์ทางเพศ (2019)\n\nในผู้ชาย 137 คนที่มีพฤติกรรมทางเพศที่ไม่สามารถควบคุมได้ กลุ่ม CBT เป็นเวลา 7 สัปดาห์ลดอาการที่เกี่ยวข้องกับเพศสัมพันธ์และการบีบบังคับทางเพศได้ดีกว่าการเข้าคิวรอ พร้อมทั้งสุขภาพจิตที่ดีขึ้นผลการรักษายังคงมีเสถียรภาพในการติดตามผลทั้ง 3 และ 6 เดือน\n\nการศึกษานี้ครอบคลุมถึงโรคไฮเปอร์เซ็กชวลในวงกว้างมากกว่าการงดสื่อลามกเพียงอย่างเดียว ดังนั้นจึงไม่ควรกลายเป็นการกล่าวอ้างว่าทุกคนจะหายจากโรคทางชีววิทยาเมื่อหกเดือนข้อความนี้สนับสนุนข้อความที่ชัดเจนและมีประโยชน์มากขึ้น: การปรับปรุงพฤติกรรมทางเพศแบบบีบบังคับอย่างต่อเนื่องสามารถคงอยู่ได้ตลอดระยะเวลาดังกล่าว\n\nหกเดือนจึงเป็นเหตุการณ์สำคัญในการบำรุงรักษารักษากิจวัตรที่ทำให้การควบคุมง่ายขึ้น แทนที่จะถือว่าวันที่เป็นการอนุญาตให้รื้อออก';

  @override
  String get pornographyReferenceDay365 =>
      'หนึ่งปี: หลักฐานของการเปลี่ยนแปลงพฤติกรรมที่ยั่งยืน\n\nที่มา: ผลการติดตามผลหนึ่งปีของการรักษาตามการยอมรับสำหรับภาวะอารมณ์เกิน (2026)\n\nในการติดตามผลหนึ่งปี ผู้เข้าร่วมในการศึกษาการรักษาโดยอาศัยการยอมรับนี้ไม่ได้กลับไปสู่ระดับภาวะอารมณ์เกินทางเพศก่อนการรักษาผู้เขียนอธิบายว่าการค้นพบนี้ถือเป็นหลักฐานเบื้องต้นของประโยชน์ที่ยั่งยืนและมีความหมายทางคลินิก โดยสามารถควบคุมความอยากในกระบวนการต่างๆ ที่ตามมาเมื่อเวลาผ่านไป\n\nนี่เป็นหลักฐานการติดตามผลการรักษา ไม่ใช่ข้อพิสูจน์ว่าสมองรีเซ็ตได้หนึ่งปีคำกล่าวอ้างที่มีความหมายนั้นดีกว่าอยู่แล้ว: การควบคุมที่เกี่ยวข้องทางคลินิกสามารถคงอยู่ได้เป็นเวลาหนึ่งปี แทนที่จะหายไปทันทีที่การแทรกแซงเริ่มแรกสิ้นสุดลง\n\nหนึ่งปีของการเปลี่ยนแปลงที่คุณดูแลรักษาไว้ก็ถือเป็นชุดข้อมูลส่วนบุคคลขนาดใหญ่เช่นกันเปรียบเทียบการควบคุม ความทุกข์ การทำงาน ความสัมพันธ์ และการใช้เวลาในปัจจุบันกับจุดเริ่มต้นของคุณสิ่งเหล่านี้คือผลลัพธ์ที่สำคัญทางคลินิก';

  @override
  String get pornographyReferenceDay1825 =>
      'ห้าปี: การควบคุมระยะยาวคือผลลัพธ์\n\nแหล่งที่มา: ความผิดปกติของพฤติกรรมทางเพศที่บีบบังคับและการใช้สื่อลามกที่เป็นปัญหา: การทบทวนโดยผู้เชี่ยวชาญจากสหวิทยาการที่ครอบคลุม (2026)\n\nการวิจารณ์สมัยใหม่ถือว่า CSBD และการใช้สื่อลามกที่เป็นปัญหาเป็นปัญหาที่ซับซ้อนที่เกี่ยวข้องกับการควบคุม ความทุกข์ การทำงาน บริบท และความแตกต่างระหว่างบุคคลไม่มีเกณฑ์การรีเซ็ตสมองและเส้นประสาทในระยะเวลาห้าปีที่ได้รับการตรวจสอบแล้ว\n\nแต่ห้าปีไม่ใช่เหตุการณ์สำคัญที่ว่างเปล่าเป็นเวลา 1,825 วันในการรักษาทิศทางพฤติกรรมที่คุณเลือกเนื่องจากปัญหาทางคลินิกคือการสูญเสียการควบคุมอย่างต่อเนื่องโดยมีความทุกข์ทรมานหรือการด้อยค่า การควบคุมอย่างต่อเนื่องและการฟื้นฟูการทำงานในช่วงหลายปีที่ผ่านมาจึงเป็นผลลัพธ์ที่มีความหมายในสิทธิของตนเอง\n\nในขั้นตอนนี้ คำถามที่มีประโยชน์ไม่ใช่อีกต่อไปว่าสมองของคุณมีเปอร์เซ็นต์ของการเดินสายไฟใหม่ถึงเปอร์เซ็นต์ที่สมมติขึ้นแล้วหรือไม่อยู่ที่ว่ารูปแบบเก่ายังคงควบคุมตัวเลือกของคุณหรือขัดขวางชีวิตที่คุณต้องการหากไม่เป็นเช่นนั้น นั่นคือความสำเร็จระยะยาวที่สำคัญ';

  @override
  String get smokingReferenceDay1 =>
      'วันแรก: สิทธิประโยชน์เริ่มตั้งแต่ตอนนี้\n\nที่มา: NHS Better Health\n\nสิทธิประโยชน์เริ่มต้นภายในไม่กี่นาที ไม่ใช่หลายวันร่างกายจะเริ่มเป็นปกติทันทีที่ควันหยุดลง\n\nเกิดอะไรขึ้นวันนี้\n• 20 นาที: อัตราชีพจรเริ่มกลับสู่ปกติ\n• 8 ชั่วโมง: คาร์บอนมอนอกไซด์ในเลือดลดลงครึ่งหนึ่ง;ระดับออกซิเจนกำลังฟื้นตัว\n• 48 ชั่วโมง: ก๊าซคาร์บอนมอนอกไซด์ลดลงถึงระดับผู้ไม่สูบบุหรี่\n\nคาร์บอนมอนอกไซด์จับกับเซลล์เม็ดเลือดแดงแรงกว่าออกซิเจน และแทนที่มันออกจากเลือดทุกอวัยวะได้รับออกซิเจนน้อยกว่าที่ควรจะเป็นซึ่งจะกลับตัวภายในสองวัน\n\nการถอนเงินจะเริ่มตั้งแต่วันแรก\n• ความอยาก — โดยทั่วไปแต่ละครั้งจะกินเวลา 3–5 นาที\n• หงุดหงิดและมีสมาธิลำบาก\n• เพิ่มความอยากอาหาร\n\nสิ่งเหล่านี้เกิดขึ้นชั่วคราวและสามารถจัดการได้โปรแกรม NHS Better Health ให้การสนับสนุนฟรี รวมถึงแอปและคำแนะนำจากเภสัชกร';

  @override
  String get smokingReferenceDay3 =>
      'วันที่สาม: การถอนเงินสูงสุด\n\nที่มา: แม็คลาฟลิน, ดานี และเดอ ไบอาซี\n\nภายใน 72 ชั่วโมง นิโคตินจะหายไปจากร่างกายของคุณสมองสร้างตัวรับนิโคตินเพิ่มขึ้นในช่วงที่คุณสูบบุหรี่ตอนนี้พวกมันถูกกระตุ้นต่ำเกินไป ทำให้เกิดอาการถอนยา\n\nอาการพีค\n• ความอยาก — รุนแรงที่สุดในตอนนี้\n• หงุดหงิด หงุดหงิด กระวนกระวายใจ\n• มีสมาธิยาก\n• ความวิตกกังวล\n• ปวดหัว\n• เพิ่มความอยากอาหาร\n• อาการไอ (ทางเดินหายใจโล่ง — เป็นสัญญาณที่ดี)\n\nนี่เป็นวันที่ยากที่สุดไม่มีอะไรจะแย่ไปกว่านี้แล้ว จากนี้อาการจะค่อยๆ บรรเทาลงเมื่อสมองของคุณปรับตัว\n\nNRT, varenicline และ bupropion ล้วนลดความรุนแรงของการถอนยาในระยะนี้อย่างมีนัยสำคัญ';

  @override
  String get smokingReferenceDay7 =>
      'หนึ่งสัปดาห์: การกลับมาของรสชาติและกลิ่น\n\nที่มา: NHS Better Health\n\nการเลิกสูบบุหรี่ได้หนึ่งสัปดาห์เป็นตัวทำนายความสำเร็จในระยะยาว ผู้คนที่ผ่านสัปดาห์แรกไปได้มีแนวโน้มที่จะเลิกบุหรี่ถาวรมากกว่า\n\nสิ่งที่ได้คืนมา\n• อาหารมีรสชาติอร่อยยิ่งขึ้น\n• กลิ่นหอมสดใสยิ่งขึ้น\n• การหายใจง่ายขึ้น — ทางเดินหายใจโล่งขึ้น\n• การไหลเวียนดีขึ้น\n• ผิวมีความชุ่มชื้นดีขึ้น\n\nการสูบบุหรี่ทำลายตัวรับรสและกลิ่นโดยตรงภายในไม่กี่วันหลังจากหยุด พวกเขาก็เริ่มฟื้นตัว\n\nการถอนนิโคตินแบบเฉียบพลันกำลังผ่อนคลายลงความอยากทางกายภาพจะสั้นลงและเกิดขึ้นน้อยลงความอยากที่เกิดจากการกระตุ้นอาจยังคงอยู่ แต่ความเร่งด่วนทางร่างกายที่เลวร้ายที่สุดอยู่เบื้องหลังคุณ';

  @override
  String get smokingReferenceDay14 =>
      'สองสัปดาห์: การไหลเวียนดีขึ้น\n\nที่มา: NHS Better Health\n\nภายใน 2-12 สัปดาห์หลังจากหยุด การไหลเวียนโลหิตจะดีขึ้นนิโคตินทำให้หลอดเลือดแคบลงทุกครั้งที่สูบบุหรี่หากไม่มีมัน หลอดเลือดจะผ่อนคลายและเลือดจะไหลเวียนได้อย่างอิสระมากขึ้น\n\nนี่หมายถึงอะไร\n• การไหลเวียนของเลือดไปยังมือ เท้า และเนื้อเยื่อส่วนปลายดีขึ้น\n• หลายๆ คนสังเกตว่ามือและเท้าอุ่นขึ้น\n• การเดินและขึ้นบันไดเริ่มรู้สึกง่ายขึ้น\n\nเมื่อคาร์บอนมอนอกไซด์ถูกกำจัดออกจากเลือดไปแล้วในวันแรกและการไหลเวียนดีขึ้น ออกซิเจนจะเข้าถึงกล้ามเนื้อได้อย่างมีประสิทธิภาพมากขึ้น\n\nเยื่อบุทางเดินหายใจกำลังฟื้นตัวและดันน้ำมูกที่สะสมอยู่ออกมาหากคุณไอมากกว่าปกติ นั่นเป็นสัญญาณของการฟื้นตัว ไม่ใช่อาการพ่ายแพ้';

  @override
  String get smokingReferenceDay30 =>
      'หนึ่งเดือน: การทำงานของปอดเพิ่มขึ้น\n\nที่มา: NHS Better Health\n\nการหายใจจะง่ายขึ้นและการทำงานของปอดดีขึ้น — เพิ่มขึ้นถึง 10% ในช่วง 3 ถึง 9 เดือนในหนึ่งเดือน คุณจะเข้าสู่ช่วงฟื้นตัวที่ดี\n\nเกิดอะไรขึ้นในปอด\n• Cilia งอกขึ้นมาใหม่และสามารถล้างเสมหะได้อย่างมีประสิทธิภาพมากขึ้น\n• ทางเดินหายใจอักเสบกำเริบ\n• อาการไอของผู้สูบบุหรี่อย่างต่อเนื่องจะจางลง\n• ความอดทนในการออกกำลังกายดีขึ้น\n\nปัญหาการไอ หายใจมีเสียงวี๊ด และการหายใจจะดีขึ้นเมื่อการทำงานของปอดเพิ่มขึ้นหนึ่งเดือนเป็นจุดที่มีความหมายสำหรับเส้นโค้งการฟื้นตัว';

  @override
  String get smokingReferenceDay90 =>
      'สามเดือน: ความเสี่ยงจากภาวะหัวใจวายลดลง\n\nที่มา: PMC — ผลกระทบต่อหัวใจและหลอดเลือดจากการสูบบุหรี่และการเลิกบุหรี่ (2024)\n\nการสูบบุหรี่ทำลายหัวใจและหลอดเลือดแดงได้หลายวิธี: เร่งการสะสมของคราบจุลินทรีย์ในหลอดเลือด ส่งเสริมการแข็งตัวของเลือด เพิ่มความดันโลหิต และทำลายเยื่อบุหลอดเลือดแดงผลการแข็งตัวของเลือดและส่งเสริมการแข็งตัวของเลือดจะย้อนกลับภายในไม่กี่วันหลังจากหยุด และการทบทวนนี้รายงานการลดลงของอาการหัวใจวายและโรคหลอดเลือดสมองลดลงอย่างเห็นได้ชัดภายในปีแรกของการเลิกบุหรี่\n\nตอนนี้มีอะไรปรับปรุงบ้าง\n• ปัจจัยการแข็งตัวของเลือดกำลังเข้าสู่ภาวะปกติ\n• ความดันโลหิตและอัตราการเต้นของหัวใจคงที่\n• การลดลงอย่างรวดเร็วที่สุดในช่วงแรกของความเสี่ยงต่อการเกิดโรคหลอดเลือดหัวใจเฉียบพลันกำลังดำเนินไปด้วยดี\n\nประโยชน์ที่ออกฤทธิ์ช้ากว่า — ย้อนกลับไปหลายปีของการสะสมของคราบพลัคในหลอดเลือด — ใช้เวลานานกว่าและครอบคลุมในเหตุการณ์สำคัญในภายหลังทุกเดือนที่ปลอดบุหรี่จะช่วยฟื้นฟู';

  @override
  String get smokingReferenceDay180 =>
      'หกเดือน: การฟื้นฟูภูมิคุ้มกัน\n\nที่มา: ระยะเวลาปลอดบุหรี่และการฟื้นตัวของการทำงานของเซลล์ภูมิคุ้มกันในถุงลม (PubMed)\n\nการสูบบุหรี่จะไปกดเซลล์ภูมิคุ้มกันที่อยู่ลึกเข้าไปในปอด ทำให้ความสามารถในการดูดซับและฆ่าเชื้อแบคทีเรียลดลงการฟื้นตัวจะค่อยเป็นค่อยไป โดยผู้ที่งดเว้นเพียง 2 เดือนจะมีอาการบกพร่องมากที่สุด ในขณะที่การทำงานจะดีขึ้นเรื่อยๆ เมื่องดเว้นนานขึ้นภายใน 6 เดือน การป้องกันภูมิคุ้มกันในปอดจะฟื้นตัวอย่างมีนัยสำคัญ\n\nนี่หมายถึงอะไร\nปอดสามารถกำจัดแบคทีเรียและอนุภาคที่สูดเข้าไปได้อย่างมีประสิทธิภาพมากขึ้น ลดความไวต่อโรคหวัด ไข้หวัดใหญ่ และโรคปอดบวม\n\nการป้องกันทางภูมิคุ้มกันมีการปรับปรุงอย่างต่อเนื่องเกินกว่าหกเดือน แต่ตอนนี้การป้องกันของร่างกายมีความแข็งแกร่งมากกว่าในช่วงสัปดาห์แรกๆ อย่างเห็นได้ชัด';

  @override
  String get smokingReferenceDay365 =>
      'หนึ่งปี: ความเสี่ยงจากภาวะหัวใจวายลดลงอย่างรวดเร็ว\n\nที่มา: PMC - การเลิกบุหรี่และผลลัพธ์ของโรคหลอดเลือดสมอง;CDC ประโยชน์ของการเลิกสูบบุหรี่\n\nการสูบบุหรี่เพิ่มความเสี่ยงต่อโรคหลอดเลือดสมองประมาณสองเท่าโดยส่งเสริมการสะสมของคราบจุลินทรีย์ในหลอดเลือด เพิ่มการแข็งตัวของเลือด เพิ่มความดันโลหิต และทำลายหลอดเลือดในสมองเส้นเวลาผลประโยชน์ในการเลิกบุหรี่ของ CDC เองทำให้ความเสี่ยงโรคหัวใจวายลดลงอย่างมากที่เครื่องหมาย 1 ถึง 2 ปี - คุณอยู่ที่ขอบด้านหน้าของหน้าต่างนั้น\n\nเส้นเวลาการกู้คืน\nการทำให้ความเสี่ยงต่อโรคหลอดเลือดสมองเป็นปกตินั้นใช้เวลานานกว่า: การศึกษาเรื่องโรคหลอดเลือดสมองที่อ้างถึงได้ติดตามผู้เลิกบุหรี่โดยมีค่ามัธยฐานเกือบ 5 ปี เพื่อแสดงอัตราโรคหลอดเลือดสมองที่ต่ำกว่าผู้สูบบุหรี่อย่างต่อเนื่อง และข้อมูลของ CDC ช่วยลดความเสี่ยงโรคหลอดเลือดหัวใจตีบลงครึ่งหนึ่งที่ 3 ถึง 6 ปี โดยความเสี่ยงโรคหลอดเลือดสมองลดลงในช่วง 5 ถึง 10 ปี\n\nหนึ่งปียังคงเป็นเหตุการณ์สำคัญทางการแพทย์อย่างแท้จริง ส่วนการลดความเสี่ยงเฉียบพลันที่ชันที่สุดอยู่เบื้องหลังคุณ แม้ว่าคุณประโยชน์ต่อระบบหัวใจและหลอดเลือดและมะเร็งในระยะยาวจะยังคงสร้างต่อไปเป็นเวลาหลายปีก็ตาม';

  @override
  String get smokingReferenceDay1825 =>
      'ห้าปี: ความเสี่ยงมะเร็งลดลง\n\nที่มา: CDC, ประโยชน์ของการเลิกบุหรี่\n\nเมื่ออายุได้ห้าปี คุณประโยชน์จากโรคมะเร็งที่น่าทึ่งที่สุดบางส่วนก็มาถึง\n\nเหตุการณ์สำคัญห้าถึงสิบปี\n• เพิ่มความเสี่ยงมะเร็งปาก คอ และกล่องเสียง: ลดลงครึ่งหนึ่ง\n• ความเสี่ยงต่อโรคหลอดเลือดสมอง: ลดลง\n\nยังอยู่ข้างหน้า\n• สิบปี: ความเสี่ยงต่อการเสียชีวิตด้วยโรคมะเร็งปอดลดลงประมาณครึ่งหนึ่ง (หลังจาก 10–15 ปี)ความเสี่ยงของมะเร็งกระเพาะปัสสาวะ หลอดอาหาร และมะเร็งไตลดลง\n• สิบห้าปี: ความเสี่ยงต่อโรคหลอดเลือดหัวใจใกล้เคียงกับผู้ไม่สูบบุหรี่\n• ยี่สิบปี: ความเสี่ยงมะเร็งปาก คอ และกล่องเสียงใกล้เคียงกับระดับของผู้ไม่สูบบุหรี่;เพิ่มความเสี่ยงมะเร็งปากมดลูกประมาณครึ่งหนึ่ง\n\nการไม่สูบบุหรี่เป็นเวลาห้าปีถือเป็นความสำเร็จที่แท้จริง ตอนนี้คุณอยู่ในหน้าต่างที่การลดความเสี่ยงต่อโรคมะเร็งที่สำคัญที่สุดบางอย่างมีอยู่ แม้ว่าคุณประโยชน์หลายประการ (เช่น ความเสี่ยงต่อโรคหลอดเลือดหัวใจจะหายเป็นปกติอย่างสมบูรณ์) จะยังคงอยู่อีกหลายปีก็ตาม';

  @override
  String get snriReferenceDay3 =>
      'การยุติ SNRI: วันแรก\n\nที่มา: สำนักพิมพ์ด้านสุขภาพของฮาร์วาร์ด\n\nหมายเหตุด้านความปลอดภัยที่สำคัญ\nควรหยุด SNRIs ภายใต้การดูแลของแพทย์หลังจากค่อยๆ ลดลงเท่านั้นโดยเฉพาะอย่างยิ่ง Venlafaxine (Effexor) มีครึ่งชีวิตสั้นมากประมาณ 5 ชั่วโมง ซึ่งหมายความว่ายาจะออกจากร่างกายอย่างรวดเร็ว และอาการที่หยุดยาอาจรุนแรงและกะทันหัน\n\nเหตุใด SNRI จึงหยุดได้ยากกว่า SSRI\nSNRI ส่งผลต่อสารเคมีในสมองที่ควบคุมอารมณ์สองชนิด ได้แก่ เซโรโทนินและนอร์อะดรีนาลีน ซึ่งหมายความว่าทั้งคู่จำเป็นต้องปรับใหม่เมื่อคุณหยุดอาการของการหยุดยามักรุนแรงกับ SNRIs มากกว่า SSRIs:\n• อาการคล้ายไข้หวัดใหญ่ (เหนื่อยล้า เหงื่อออก ปวดกล้ามเนื้อ)\n• นอนไม่หลับและนอนไม่หลับ\n• คลื่นไส้ — มักเด่นชัดกว่ากลุ่ม SSRI\n• ความไม่สมดุลและเวียนศีรษะ\n• การรบกวนทางประสาทสัมผัส — \'การปะทะของสมอง\' อาจรุนแรงมากเมื่อใช้ยาเวนลาฟาซีน\n• ตื่นตัวมากเกินไป หงุดหงิด และวิตกกังวล\n\nการเปรียบเทียบ SNRI\nVenlafaxine มีรูปแบบการหยุดใช้ยาที่ยากที่สุดเนื่องจากมีครึ่งชีวิตสั้นDuloxetine (Cymbalta) มีแนวโน้มที่จะค่อนข้างง่ายกว่าเนื่องจากมีครึ่งชีวิตนานกว่า 12 ชั่วโมงDesvenlafaxine อยู่ระหว่างทั้งสอง';

  @override
  String get snriReferenceDay7 =>
      'หนึ่งสัปดาห์หลังจาก SNRIs: การปรับระบบเคมีและสมองสองระบบ\n\nที่มา: NHS - การหยุดหรือเลิกยาแก้ซึมเศร้า (คำแนะนำทั่วไปเกี่ยวกับยาแก้ซึมเศร้า กลไกเฉพาะของ noradrenaline ด้านล่างนี้สะท้อนถึงเภสัชวิทยา SNRI ทั่วไป แทนที่จะเป็นรายละเอียดเฉพาะของ SNRI จากหน้า NHS)\n\nความท้าทายระบบคู่\nต่างจากยาแก้ซึมเศร้าส่วนใหญ่ที่ส่งผลต่อระบบหนึ่ง SNRIs ส่งผลต่อทั้งเซโรโทนินและนอร์อะดรีนาลีนภายในหนึ่งสัปดาห์ ทั้งสองระบบกำลังปรับเปลี่ยน:\n\nผลของระบบนอร์อะดรีนาลีน\nระบบนอร์อะดรีนาลีนควบคุมการตอบสนองการต่อสู้หรือหนีของร่างกาย การควบคุมความดันโลหิต และระดับพลังงานขณะที่มันปรับใหม่:\n• ความดันโลหิตผันผวนอาจเกิดขึ้นได้\n• ความวิตกกังวลอาจรู้สึกทางกายมากขึ้น (หัวใจเต้นเร็ว เหงื่อออก)\n• ระดับพลังงานอาจไม่สอดคล้องกัน\n\nผลของระบบเซโรโทนิน\nในขณะเดียวกัน ระบบเซโรโทนินก็กำลังปรับตัว ทำให้เกิดอาการถอนยาตามปกติของการหยุดยาแก้ซึมเศร้าการผสมผสานระหว่างการปรับทั้งสองระบบอาจทำให้สัปดาห์แรกมีความท้าทายเป็นพิเศษ\n\nอาการนี้มักจะแสดงให้เห็นว่าความดันโลหิตคงที่ดีขึ้น และมีอาการวิงเวียนศีรษะน้อยลงเมื่อยืนในทางอารมณ์ อารมณ์จะแปรปรวนมากกว่าที่จะเป็นใน 30 วัน แต่จะไม่อยู่ในภาวะอิสระอีกต่อไป';

  @override
  String get snriReferenceDay14 =>
      'สองสัปดาห์หลังจาก SNRIs: อาการทางกายภาพจางลง\n\nที่มา: Davies & Read (2019), พฤติกรรมเสพติด\n\nสถานะสองสัปดาห์\nสำหรับคนส่วนใหญ่ที่ค่อยๆ ลดลงอย่างเหมาะสม ระยะทางกายภาพเฉียบพลันจะได้รับการแก้ไขเป็นส่วนใหญ่ภายในสองสัปดาห์:\n• ช่องว่างของสมองลดลงหรือหายไปอย่างเห็นได้ชัด\n• อาการคลื่นไส้และอาการคล้ายไข้หวัดใหญ่หายไป\n• อาการวิงเวียนศีรษะและปัญหาการทรงตัวดีขึ้น\n• ความดันโลหิตและอัตราการเต้นของหัวใจคงที่เมื่อปรับสมดุลของนอร์อะดรีนาลีน\n\nสิ่งที่อาจคงอยู่\n• ความไวทางอารมณ์และความแปรปรวนทางอารมณ์\n• ความวิตกกังวล ซึ่งระบบนอร์อะดรีนาลีนมีอิทธิพลเป็นพิเศษ\n• อาการเหนื่อยล้า เนื่องจากระบบนอร์อะดรีนาลีนให้ความตื่นตัวและพลังงาน\n\nบริบทการวิจัย\nการทบทวนพฤติกรรมการเสพติดอย่างเป็นระบบ (Davies & Read, 2019) ยืนยันว่าผลของการหยุด SNRI เป็นหนึ่งในกลุ่มยาแก้ซึมเศร้าที่รุนแรงที่สุด โดย venlafaxine เกี่ยวข้องกับอัตราอาการถอนยาที่มีนัยสำคัญสูงเป็นพิเศษ';

  @override
  String get snriReferenceDay30 =>
      'หนึ่งเดือนหลังจาก SNRI: การปรับความเสถียรของระบบคู่\n\nที่มา: Davies & Read (2019), พฤติกรรมเสพติด - การทบทวนอุบัติการณ์การถอนยาต้านอาการซึมเศร้า ความรุนแรง และระยะเวลาอย่างเป็นระบบ\n\nเฟสการรักษาเสถียรภาพ\nหนึ่งเดือนแสดงถึงเหตุการณ์สำคัญในการฟื้นตัวของเซโรโทนินและนอร์อะดรีนาลีนการทบทวนนี้พบว่า แม้ว่าคนส่วนน้อยจำนวนมากจะประสบกับอาการถอนยาที่กินเวลานานกว่าสองสามสัปดาห์ แต่คนส่วนใหญ่ก็ผ่านพ้นระยะเฉียบพลันและรุนแรงที่สุดของอาการหยุดยาทางกายภาพไปแล้วเมื่อถึงจุดนี้\n\nโดยทั่วไปสิ่งที่จะปรับปรุงภายในหนึ่งเดือน\n• อาการหยุดเคลื่อนไหวทางกายภาพ (สมองกระตุก คลื่นไส้ เวียนศีรษะ) หายไปเป็นส่วนใหญ่\n• ความดันโลหิตกลับสู่ระดับธรรมชาติ\n• การปรับปรุงคุณภาพการนอนหลับ — รูปแบบการนอนหลับ REM ฟื้นฟูตามธรรมชาติ\n• ระดับพลังงานเริ่มคงที่เมื่อการควบคุมนอร์อะดรีนาลีนเป็นปกติ\n\nความละเอียดทื่อทางอารมณ์\nหนึ่งในประสบการณ์ที่ได้รับรายงานบ่อยที่สุดในระยะนี้คือการแก้ปัญหาอารมณ์ที่บั่นทอนลง ผู้คนจำนวนมากใน SNRI สังเกตเห็นช่วงทางอารมณ์ที่ \"แบน\"เมื่อยาคลายตัวและสมองปรับสภาพ อารมณ์และความรู้สึกไวก็มักจะกลับมาอีกครั้ง';

  @override
  String get snriReferenceDay90 =>
      'สามเดือนหลังจาก SNRIs: การถอนตัวที่ผ่านมาอย่างดี\n\nที่มา: \"Antidepressant Withdrawal Syndrome\" จดหมายบำบัด 112 (2018) Therapeutics Initiative บนชั้นวางหนังสือ NCBI\n\nเหตุใด SNRI จึงสมควรได้รับการดูแลเป็นพิเศษ\nการทบทวนหลักฐานนี้แยกยาต้านอาการซึมเศร้าที่มีครึ่งชีวิตสั้นๆ ซึ่งรวมถึง venlafaxine และ duloxetine (ทั้ง SNRIs) เนื่องจากมีความเสี่ยงสูงต่ออาการถอนยาการศึกษาที่ได้รับทุนสนับสนุนจากผู้ผลิตพบว่า 51% ของผู้ที่หยุดยาดูล็อกซีทีนมีอาการอย่างน้อย 1 อาการดังนั้นการถอนตัวของ SNRI จึงสามารถออกเสียงได้ ซึ่งเป็นเหตุผลว่าทำไมการค่อย ๆ ลดลงและได้รับการดูแลอย่างค่อยเป็นค่อยไปจึงมีความสำคัญ\n\nที่ซึ่งสามเดือนนั่งอยู่\nจดหมายระบุถึงอาการถอนยา \'โดยปกติจะปรากฏภายในสองสามวันหลังจากหยุด\' และ \'อาการถอนยาต้านอาการซึมเศร้าส่วนใหญ่จะหายไปภายใน 2 สัปดาห์\' (อาจนานกว่านั้นในบางครั้ง)ภายในสามเดือน ระยะการถอนตัวแบบเฉียบพลันยังตามหลังคนส่วนใหญ่ไปมาก\n\nสัญญาณการกู้คืนบน \'การกู้คืนตัวรับ\'\nไทม์ไลน์ยอดนิยมอ้างว่าระบบเซโรโทนินและนอร์อะดรีนาลีนได้ \'ปรับสมดุลใหม่อย่างสมบูรณ์\' ภายในสามเดือนหลักฐานที่ชัดเจนเกี่ยวข้องกับกลุ่มอาการถอนยาและจังหวะเวลา ไม่ใช่นาฬิกาฟื้นตัวของตัวรับที่แม่นยำสิ่งที่เชื่อถือได้: ภายในสามเดือนระยะการถอนตัวจะได้รับการแก้ไขโดยทั่วไป และหลายๆ คนสังเกตเห็นว่าความรู้สึกบางอย่างที่มีต่อ SNRIs ที่ลดทอนลงทางอารมณ์จะบรรเทาลงหลังจากหยุด\n\nการถอนกับการกำเริบของโรค\nจดหมายแนะนำให้แยกความแตกต่างจากการคืนสภาพที่แท้จริงหากความวิตกกังวลหรืออารมณ์ไม่ดียังคงอยู่เป็นเวลาสามเดือน ให้ตรวจสอบกับแพทย์ที่สั่งจ่ายยา แทนที่จะคิดว่าเป็นเพียงอาการถอนยาเท่านั้น';

  @override
  String get snriReferenceDay180 =>
      'หกเดือนหลังจาก SNRIs: การฟื้นฟูสมองและเส้นประสาท\n\nสัญญาณการกู้คืนข้อมูลหกเดือน\nภายในหกเดือนหลังจากการลดขนาดลงโดยได้รับการดูแลจากแพทย์ ระยะเวลาการถอน SNRI ในระยะเริ่มแรกที่รุนแรงนั้นยังตามหลังคุณอยู่มากอารมณ์ การนอนหลับ สมรรถภาพทางเพศ และความคิดที่ชัดเจน ใช้เวลาหลายเดือนในการฟื้นตัว:\n• วิถีทางของเซโรโทนิน: ได้รับการฟื้นฟูอย่างมีนัยสำคัญ\n• วิถีทางของนอร์อะดรีนาลีน: ทำให้เป็นมาตรฐาน โดยที่ระบบตอบสนองต่อความเครียดก็ปกติดีเช่นกัน\n• สถาปัตยกรรมสลีป: คาดว่าจะได้รับการกู้คืนอย่างสมบูรณ์\n• การทำงานทางเพศ: ส่วนใหญ่กลับคืนสู่สภาพเดิมสำหรับคนส่วนใหญ่ (ความผิดปกติทางเพศเป็นผลข้างเคียงของ SNRI ที่พบบ่อย แม้ว่าบางคนอาจยังคงอยู่ได้และควรปรึกษากับผู้สั่งจ่ายยา)\n\nความยืดหยุ่นต่อความเครียด\nหลายๆ คนในช่วง 6 เดือนรายงานว่ามีความยืดหยุ่นดีขึ้นอย่างเห็นได้ชัดต่อแรงกดดันในชีวิตประจำวัน เนื่องจากบทบาทของระบบนอร์อะดรีนาลีนในการตอบสนองต่อความตื่นตัวและความเครียด ซึ่ง SNRI ปรับเปลี่ยนได้อย่างมีประสิทธิภาพ กลับคืนสู่ระดับธรรมชาติแล้ว';

  @override
  String get snriReferenceDay365 =>
      'หนึ่งปีหลังจาก SNRIs: ฟื้นตัวได้สำเร็จ\n\nหนึ่งปี: การกู้คืนระบบ Dual ที่สมบูรณ์\nหนึ่งปีหลังจากเสร็จสิ้นการเทเปอร์ SNRI ทั้งระบบเซโรโทนินและนอร์อะดรีนาลีนก็มีวงจรที่สมบูรณ์ในการปรับตัวและทำให้เสถียร\n\nสิ่งที่หลักฐานสนับสนุนจริงในหนึ่งปี\nจดหมายทบทวนการรักษาฉบับนี้ตั้งข้อสังเกตว่าอาการถอนยา \'มักจะปรากฏภายในสองสามวันหลังจากหยุด\' และส่วนใหญ่จะหายภายในประมาณสองสัปดาห์ ไม่มีการศึกษาแบบควบคุมที่ติดตามบุคคลโดยเฉพาะหนึ่งปีหลังจากการหยุด SNRIสิ่งที่ได้รับการสนับสนุนอย่างดีจากภาพทางคลินิกที่กว้างขึ้นในระยะนี้:\n• ผู้ที่เรียวร่างกายอย่างเหมาะสมและได้รับการสนับสนุนด้านจิตใจส่วนใหญ่ยังคงสบายดี\n• อาการทื่อทางอารมณ์และความผิดปกติทางเพศซึ่งเป็นลักษณะเฉพาะของการใช้ SNRI ได้รับการแก้ไขอย่างสมบูรณ์สำหรับคนส่วนใหญ่\n• การคิดที่ชัดเจน รวมถึงคุณประโยชน์ด้านสมาธิที่ SNRI สามารถให้ได้ จะถูกรักษาไว้โดยการทำงานของสมองตามธรรมชาติ\n\nความสำคัญของเหตุการณ์สำคัญนี้\nการยุติ SNRI ได้สำเร็จ โดยเฉพาะยาเวนลาฟาซีน ถือเป็นความสำเร็จครั้งสำคัญความเข้มข้นของกระบวนการยุติยาและความมุ่งมั่นที่จำเป็นในการจัดการภายใต้การดูแลของแพทย์ แสดงให้เห็นถึงความยืดหยุ่นที่โดดเด่น';

  @override
  String get socialMediaReferenceDay1 =>
      'ก้าวถอยหลังจากโซเชียลมีเดีย: วันแรก\n\nที่มา: Lambert และคณะ \"การหยุดพักจากโซเชียลมีเดียหนึ่งสัปดาห์ช่วยเพิ่มความเป็นอยู่ที่ดี อาการซึมเศร้า และความวิตกกังวล: การทดลองแบบสุ่มที่มีกลุ่มควบคุม\" จิตวิทยาไซเบอร์ พฤติกรรม และเครือข่ายทางสังคม (2022) บน PubMed\n\nสิ่งที่แสดงหลักฐาน\nในการศึกษาที่มีการควบคุมอย่างเข้มงวดนี้ ผู้คนจะถูกสุ่มให้หยุดพักจาก Facebook, Instagram, Twitter และ TikTok เป็นเวลาหนึ่งสัปดาห์ หรือให้ใช้งานต่อไปตามปกติกลุ่มพักมีการปรับปรุงความเป็นอยู่ที่ดีขึ้นอย่างมีนัยสำคัญ ภาวะซึมเศร้าและความวิตกกังวลลดลงนั่นเป็นหลักฐานจริงที่ควบคุมได้ซึ่งการถอยกลับช่วยได้\n\nสิ่งที่แสดงหลักฐาน\nการใช้โซเชียลมีเดียโดยบีบบังคับมีความเชื่อมโยงอย่างมากกับอารมณ์ที่ลดลงและความวิตกกังวลที่สูงขึ้น และการทดลองแบบสุ่มแสดงให้เห็นว่าการจงใจตัดออกสามารถปรับปรุงความเป็นอยู่ที่ดี ในขณะเดียวกันก็ลดอาการซึมเศร้าและวิตกกังวลภายในหนึ่งสัปดาห์\n\nวันแรก: สิ่งที่คาดหวัง\n• กระวนกระวายใจและอยากตรวจสอบ\n• การแจ้งเตือน \'Phantom\' — รู้สึกถึงกระแสที่ไม่เคยเกิดขึ้น\n• ความเบื่อหน่ายเมื่อคุณปรับตัวเข้ากับสิ่งเร้าที่น้อยลงอย่างต่อเนื่อง\nสิ่งเหล่านี้เป็นความรู้สึกเกี่ยวกับนิสัยตามปกติและเกิดขึ้นชั่วคราวการตระหนักถึงรูปแบบเป็นขั้นตอนแรกในการเปลี่ยนแปลง';

  @override
  String get socialMediaReferenceDay3 =>
      'สามวันโดยไม่มีโซเชียลมีเดีย: ความวิตกกังวลและอารมณ์\n\nที่มา: Lambert และคณะ \"การหยุดพักจากโซเชียลมีเดียหนึ่งสัปดาห์ช่วยเพิ่มความเป็นอยู่ที่ดี อาการซึมเศร้า และความวิตกกังวล: การทดลองแบบสุ่มที่มีกลุ่มควบคุม\" จิตวิทยาไซเบอร์ พฤติกรรม และเครือข่ายทางสังคม (2022) บน PubMed\n\nเหตุใดการหยุดพักจึงช่วยให้อารมณ์ดีขึ้น\nในการทดลองที่มีการควบคุมนี้ ผู้ที่ได้รับการสุ่มให้หยุดพักจากโซเชียลมีเดียเป็นเวลาหนึ่งสัปดาห์ ทำให้สัปดาห์นั้นสิ้นสุดลงด้วยความวิตกกังวลและภาวะซึมเศร้าที่ลดลง และมีความเป็นอยู่ที่ดีขึ้นมากกว่าผู้ที่เลื่อนดูเนื้อหาอย่างต่อเนื่องความทุกข์ยากในแต่ละวันจากการใช้งานหนักๆ ส่วนใหญ่มาจากการเปรียบเทียบทางสังคม — การวัดชีวิตจริงของคุณเทียบกับวงล้อไฮไลท์ที่รวบรวมไว้ของผู้อื่น — และจากการดึงความกลัวที่จะพลาดในระดับต่ำ\n\nเกิดอะไรขึ้นประมาณ 72 ชั่วโมง\nในช่วงพักช่วงเช้า นิสัยยังคงดัง:\n• มีความต้องการอย่างมากในการตรวจสอบ ซึ่งมักเกิดขึ้นจากช่วงเวลาที่เป็นกิจวัตร (ตื่น รอต่อแถว)\n• หงุดหงิดและกระสับกระส่ายอยู่บ้าง\n• สำหรับบางคน ความวิตกกังวลที่เกิดจากการเปรียบเทียบจะผ่อนคลายลงเป็นครั้งแรก\n• นิสัยการเลื่อนก่อนนอนเริ่มคลายตัว\n\nกับดักการเปรียบเทียบคลายออก\nหากไม่มีฟีดไฮไลต์ของผู้คน other อย่างต่อเนื่อง การเปรียบเทียบที่กระตุ้นให้เกิดความวิตกกังวลเกี่ยวกับโซเชียลมีเดียจะมีเชื้อเพลิงน้อยลงผลการทดลองชี้ให้เห็นว่าภายในสิ้นสัปดาห์แรก การเปลี่ยนแปลงในช่วงแรกๆ เหล่านี้จะทำให้อารมณ์ดีขึ้นอย่างวัดผลได้ ดังนั้นความรู้สึกไม่สบายใน 3 วันจึงเป็นส่วนที่ยากของการเปลี่ยนแปลงที่ได้ผล';

  @override
  String get socialMediaReferenceDay7 =>
      'หนึ่งสัปดาห์ที่ไม่มีโซเชียลมีเดีย: ผลตอบแทนที่วัดได้\n\nที่มา: Lambert และคณะ \"การหยุดพักจากโซเชียลมีเดียหนึ่งสัปดาห์ช่วยเพิ่มความเป็นอยู่ที่ดี อาการซึมเศร้า และความวิตกกังวล: การทดลองแบบสุ่มที่มีกลุ่มควบคุม\" จิตวิทยาไซเบอร์ พฤติกรรม และเครือข่ายทางสังคม (2022) บน PubMed\n\nหนึ่งสัปดาห์พอดี - และได้ผล\nนี่คือหลักชัยสำคัญที่การวิจัยพูดคุยโดยตรงที่สุด: การแทรกแซงของการทดลองคือการหยุดพักหนึ่งสัปดาห์เมื่อเทียบกับผู้ที่ใช้โซเชียลมีเดียอย่างต่อเนื่อง กลุ่มแบ่งมีความเป็นอยู่ที่ดีขึ้นอย่างมีนัยสำคัญ รวมถึงภาวะซึมเศร้าและความวิตกกังวลลดลงอย่างมากหลังจากผ่านไปเพียงเจ็ดวันการเข้าถึงหนึ่งสัปดาห์ก็มาถึงจุดที่การศึกษาแบบมีการควบคุมพบว่ามีประโยชน์อย่างแท้จริง\n\nสิ่งที่คนทั่วไปสังเกตเห็น\nนอกเหนือจากการเพิ่มอารมณ์ที่วัดได้ ผู้คนมักรายงานว่า:\n• มีเวลามากขึ้น — หลายคนแปลกใจว่าพวกเขาใช้ไปมากขนาดไหน\n• มีสมาธิง่ายขึ้น เนื่องจากนิสัยการเปลี่ยนความสนใจอย่างต่อเนื่องคลายตัวลง\n• ช่วงเย็นที่สงบขึ้นและนอนหลับได้ง่ายขึ้นโดยไม่ต้องเลื่อนเตียงก่อนเข้านอน\nผลลัพธ์เหล่านี้สอดคล้องกับการปรับปรุงวัดความเป็นอยู่ที่ดีขึ้นในวงกว้างในการทดลอง\n\nดำเนินต่อไป\nหนึ่งสัปดาห์ถือเป็นเหตุการณ์สำคัญที่แท้จริงและมีหลักฐานสนับสนุนประโยชน์ของอารมณ์ เวลา และความสนใจมีแนวโน้มที่จะลึกซึ้งยิ่งขึ้นตามรูปแบบการรักษาสุขภาพที่ดียิ่งนานขึ้น';

  @override
  String get socialMediaReferenceDay14 =>
      'สองสัปดาห์โดยไม่มีโซเชียลมีเดีย: กำไรสองสัปดาห์\n\nที่มา: Coyne & Woodruff, \"การหยุดพัก: ผลของการมีส่วนร่วมในการดีท็อกซ์ทางดิจิทัลบนโซเชียลมีเดียสองสัปดาห์... ในหมู่คนหนุ่มสาว\" พฤติกรรมศาสตร์ (2023) บน PubMed Central\n\nเกี่ยวกับการศึกษาวิจัยครั้งนี้\nคนหนุ่มสาวจำกัดการใช้โซเชียลมีเดียไว้ที่ประมาณ 30 นาทีต่อวันเป็นเวลาสองสัปดาห์ โดยมีการติดตามการใช้งานบนโทรศัพท์ของพวกเขาอย่างเป็นกลาง (ลดลงประมาณ 78%)ผู้เข้าร่วมลดการใช้โซเชียลมีเดียลงประมาณ 78% ทำให้เหตุการณ์สำคัญนี้เป็นการทดสอบในโลกแห่งความเป็นจริงโดยตรงว่าจะเกิดอะไรขึ้นเมื่อลดการใช้งานลงอย่างมากเป็นเวลาสองสัปดาห์\n\nสิ่งที่ปรับปรุง\nในช่วงสองสัปดาห์ ผู้เข้าร่วมมีการปรับปรุงใน:\n• การนอนหลับ — ทั้งระยะเวลาและคุณภาพ\n• ความพอใจในการใช้ชีวิต\n• ความเครียด\n• การรับรู้เรื่องสุขภาพ\n• คะแนนตามระดับการติดสมาร์ทโฟนและโซเชียลมีเดีย\nผลกำไรที่วัดได้เป็นรูปธรรม: การนอนหลับนานขึ้นและดีขึ้น ความเครียดลดลง ความพึงพอใจในชีวิตที่สูงขึ้นและการรับรู้ความเป็นอยู่ที่ดี และคะแนนการติดสมาร์ทโฟน/โซเชียลมีเดียลดลง\n\nระวังการถอยหลัง\nนักวิจัยยังสังเกตเห็นว่ามีการใช้การคืบคลานกลับไปยังระดับก่อนหน้าในภายหลังสองสัปดาห์ถือเป็นกำไรที่แท้จริง แต่มันเน้นย้ำว่าเหตุใดการวางแผนโดยเจตนา ไม่ใช่แค่การหยุดพักชั่วคราว เท่านั้น จึงเป็นสิ่งที่รักษาผลประโยชน์เอาไว้';

  @override
  String get socialMediaReferenceDay30 =>
      'หนึ่งเดือนที่ไม่มีโซเชียลมีเดีย: การเชื่อมต่อที่แท้จริงลึกซึ้งยิ่งขึ้น\n\nที่มา: Coyne & Woodruff, \"การหยุดพัก: ผลของการมีส่วนร่วมในการดีท็อกซ์ทางดิจิทัลบนโซเชียลมีเดียสองสัปดาห์... ในหมู่คนหนุ่มสาว\" พฤติกรรมศาสตร์ (2023) บน PubMed Central\n\nการเชื่อมต่อสามารถปรับปรุงได้เมื่อคุณก้าวถอยหลัง\nฟังดูขัดแย้งกัน แต่ในการศึกษานี้ การตัดโซเชียลมีเดียออกไปมีความเกี่ยวข้องกับการปรับปรุงความสัมพันธ์ที่สนับสนุน ควบคู่ไปกับความพึงพอใจในชีวิตที่ดีขึ้นและความเครียดที่ลดลงเวลาและความใส่ใจที่ไปที่ฟีดนั้นมีให้สำหรับคนในชีวิตของคุณจริงๆ\n\nสิ่งที่หนึ่งเดือนมีแนวโน้มที่จะนำมา\nภายใน 30 วัน หลายคนพบว่า:\n• บทสนทนานำเสนอมากขึ้นและถูกขัดจังหวะน้อยลง\n• มีความสนใจในกิจกรรมและงานอดิเรกในโลกแห่งความเป็นจริงมากขึ้น\n• ภาพลักษณ์ของตัวเองโดยอาศัยจำนวนไลค์ ความคิดเห็น และจำนวนผู้ติดตามน้อยลง\n\nสัญญาณการกู้คืน\nภายในหนึ่งเดือน คุณได้รักษารูปแบบการมีสุขภาพดีขึ้นเป็นสองเท่าของกรอบเวลาการแทรกแซงของการศึกษาการนอนหลับ ความเครียด ความพึงพอใจในชีวิต สุขภาพ และความสัมพันธ์ที่เพิ่มขึ้นที่วัดได้ในช่วงสองสัปดาห์นั้น มีเวลาอีกสองสัปดาห์ในการรวมเข้ากับกิจวัตรประจำวัน\n\nทำให้การนับเวลา\nตั้งเป้าที่จะเติมเต็มเวลาว่างด้วยกิจกรรมที่สร้างการเชื่อมต่อและการเติมเต็มอย่างแท้จริง แทนที่จะแค่สลับหน้าจอหนึ่งไปอีกหน้าจอหนึ่ง';

  @override
  String get socialMediaReferenceDay60 =>
      'สองเดือนโดยไม่มีโซเชียลมีเดีย: หลักฐานสนับสนุนอะไร\n\nที่มา: Ramadhan และคณะ \"ผลกระทบของการดีท็อกซ์โซเชียลมีเดียแบบดิจิทัลต่อสุขภาพจิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Narra J (2024) บน PubMed Central\n\nรูปภาพที่น่าเชื่อถือที่สุด\nนักวิจัยรวมผลลัพธ์จากการศึกษา 10 เรื่อง รวมถึงการทดลองแบบควบคุม 7 เรื่องผลลัพธ์ที่ชัดเจนที่สุดคืออาการซึมเศร้าลดลงอย่างมีนัยสำคัญ หลังจากที่ผู้คนเลิกใช้โซเชียลมีเดีย\n\nผลลัพธ์ที่แข็งแกร่งที่สุด\nการวิจัยแบบผสมผสานพบว่าอาการซึมเศร้าลดลงอย่างเห็นได้ชัดภายในสองเดือน คุณจะรักษาระดับการเข้าถึงข้อมูลดิจิทัลที่ลดลงแบบเดียวกับที่สร้างประโยชน์ต่อสุขภาพจิต\n\nสองเดือนจะเป็นอย่างไร\nด้วยการเปรียบเทียบรายวันที่น้อยลงและการเสริมแรงที่ขับเคลื่อนด้วยฟีดน้อยลง ภาพลักษณ์ของตัวเองจึงมีเหตุผลน้อยลงมากในการขึ้นอยู่กับจำนวนไลค์ ความคิดเห็น หรือจำนวนผู้ติดตาม ในขณะที่หลักฐานที่รวบรวมได้ชัดเจนที่สุดชี้ไปที่อาการซึมเศร้าที่ลดลง\n\nTakeaway ในทางปฏิบัติ\nหลักฐานดังกล่าวให้รางวัลแก่การเปลี่ยนแปลงที่ยั่งยืนโดยเจตนาใช้จุดสองเดือนเพื่อรักษาขีดจำกัดโดยเจตนาไว้แทนที่จะเลื่อนกลับไป และเพื่อลงทุนในแหล่งความหมายและการเชื่อมโยงแบบออฟไลน์';

  @override
  String get socialMediaReferenceDay90 =>
      'สามเดือนที่ไม่มีโซเชียลมีเดีย: ความปกติใหม่\n\nที่มา: Coyne & Woodruff, \"การหยุดพัก: ผลของการมีส่วนร่วมในการดีท็อกซ์ทางดิจิทัลบนโซเชียลมีเดียสองสัปดาห์... ในหมู่คนหนุ่มสาว\" พฤติกรรมศาสตร์ (2023) บน PubMed Central\n\nการนอนหลับคือความโดดเด่น\nผลการวิจัยที่ชัดเจนที่สุดของการศึกษาครั้งนี้คือการนอนหลับที่ดีขึ้น ทั้งระยะเวลาและคุณภาพ เมื่อผู้เข้าร่วมตัดการใช้โซเชียลมีเดียทันทีเมื่อเวลาผ่านไปสามเดือนของรูปแบบการมีสุขภาพดีอย่างยั่งยืน ม้วนหนังสือตอนดึกที่เคยกินเพื่อการนอนหลับได้หยุดแข่งขันกับการพักผ่อนมานานแล้ว และการนอนหลับที่ดีขึ้นมีแนวโน้มที่จะช่วยยกระดับอารมณ์ สมาธิ และพลังงานไปด้วย\n\nปรับปรุงอะไรอีกบ้าง\nการศึกษาเดียวกันนี้พบว่าความเครียด ความพึงพอใจในชีวิต การรับรู้ด้านสุขภาพ และความสัมพันธ์ที่สนับสนุนเพิ่มขึ้นเมื่อผ่านไปสามเดือน สิ่งเหล่านี้จะไม่ใช่สิ่งแปลกใหม่อีกต่อไป พวกเขามีเวลาปรับตัวเข้าสู่ภาวะปกติใหม่\n\nสัญญาณการฟื้นตัวของกลไก\nการตัดโซเชียลมีเดียทำให้ระยะเวลาการนอนหลับและคุณภาพการนอนหลับดีขึ้นอย่างมากในการศึกษาการแทรกแซงการรักษารูปแบบนั้นไว้เป็นเวลาสามเดือนจะเปลี่ยนการนอนดึกให้กลายเป็นนิสัยการนอนหลับที่ยั่งยืน\n\nการปรากฏตัวและความสัมพันธ์\nด้วยการสะท้อนให้เติมเต็มทุกช่วงเวลาที่เงียบสงบด้วยโทรศัพท์ที่อ่อนแอลงมาก การอยู่ในการสนทนา การรับประทานอาหาร และการหยุดทำงาน — จะเกิดขึ้นอย่างเป็นธรรมชาติมากขึ้น และความสัมพันธ์ที่คุณลงทุนในช่วงสามเดือนมีแนวโน้มที่จะรู้สึกแข็งแกร่งขึ้น';

  @override
  String get socialMediaReferenceDay180 =>
      'หกเดือนโดยไม่มีโซเชียลมีเดีย: การฟื้นตัวที่วัดได้\n\nที่มา: Ramadhan และคณะ \"ผลกระทบของการดีท็อกซ์โซเชียลมีเดียแบบดิจิทัลต่อสุขภาพจิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Narra J (2024) บน PubMed Central\n\nการวิเคราะห์เมตาเพิ่มอะไร\nเมื่อรวมการศึกษา 10 ชิ้น รวมถึงการทดลองควบคุม 7 ชิ้น นักวิจัยพบว่าอาการซึมเศร้าลดลงอย่างเห็นได้ชัด หลังจากที่ผู้คนลดหรือหยุดโซเชียลมีเดียชั่วคราว\n\nสิ่งที่พบจริง\n• อาการซึมเศร้า: การลดลงที่มีนัยสำคัญทางสถิติ (ผลประโยชน์ที่ชัดเจนและสม่ำเสมอที่สุด)\n• ความพึงพอใจในชีวิต: ไม่มีผลกระทบที่มีนัยสำคัญ\n• ความเครียด: ไม่มีผลกระทบที่มีนัยสำคัญ\n• สุขภาพจิตโดยรวม: ไม่มีผลกระทบที่มีนัยสำคัญ\nผลลัพธ์ที่รวบรวมได้ชัดเจนที่สุด: ดีท็อกซ์แบบดิจิทัลลดอาการซึมเศร้าได้อย่างมาก\n\nเหตุใดคุณจึงยังรู้สึกถึงผลประโยชน์ในวงกว้าง\nหกเดือนของการลดการสัมผัสอาหารสัตว์จะทำให้เกิดประโยชน์ในทางปฏิบัติที่เห็นได้จากการแทรกแซงที่สั้นลง: มีเวลามากขึ้น การตรวจสอบที่บังคับน้อยลง และการลดการสัมผัสทางดิจิทัลที่เกี่ยวข้องกับอาการซึมเศร้าอย่างยั่งยืน\n\nควบคุมฟีด\nประโยชน์สูงสุดมาจากการทำลายการใช้งานที่หนักหน่วง เฉื่อยชา และบีบบังคับภายในหกเดือน การควบคุมโซเชียลมีเดียโดยเจตนาถือเป็นค่าเริ่มต้นใหม่ แทนที่จะเป็นฟีดที่ควบคุมความสนใจของคุณ';

  @override
  String get socialMediaReferenceDay365 =>
      'หนึ่งปีที่ไม่มีโซเชียลมีเดีย: ความสัมพันธ์ที่ได้รับการเจรจาใหม่\n\nที่มา: Ramadhan และคณะ \"ผลกระทบของการดีท็อกซ์โซเชียลมีเดียแบบดิจิทัลต่อสุขภาพจิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Narra J (2024) บน PubMed Central\n\nหนึ่งปีแห่งการเปลี่ยนแปลงที่ยั่งยืน\nการวิจัยที่ผสมผสานกันอย่างลงตัวที่สุดแสดงให้เห็นว่าการถอยห่างจากโซเชียลมีเดียสามารถลดอาการซึมเศร้าได้หนึ่งปีเต็มหมายความว่ารูปแบบการรับแสงต่ำกลายเป็นเรื่องปกติของคุณมากกว่าการพักระยะสั้นๆ\n\nหนึ่งปีสร้างอะไร\nหนึ่งปีเต็มจะทำให้คุณมีเวลาหลายร้อยชั่วโมงสำหรับความสัมพันธ์ที่แท้จริง งานอดิเรก ทักษะ การไตร่ตรอง และความคิดสร้างสรรค์การตรวจสอบอัตโนมัติมีเวลาหนึ่งปีเต็มในการอ่อนแรง ในขณะที่กิจวัตรออฟไลน์เหล่านั้นมีเวลาหนึ่งปีเต็มในการเสริมกำลัง\n\nผลประโยชน์ที่ยั่งยืน\nสุขภาพจิตที่วัดได้ชัดเจนที่สุดคืออาการซึมเศร้าที่ลดลงประโยชน์ที่ได้รับในทางปฏิบัติ ได้แก่ เวลามากขึ้น การหยุดชะงักน้อยลง และการตรวจสอบที่บังคับน้อยลง จะทำให้คุณควบคุมฟีดได้ทุกวัน\n\nอะไรจะเกิดขึ้นต่อไป\nปีแห่งการเปลี่ยนแปลงโดยเจตนาได้รีเซ็ตความสัมพันธ์ไม่ว่าคุณจะกลับไปใช้โดยตั้งใจอย่างจำกัด หรือเลิกใช้งานโดยสิ้นเชิง วงจรบังคับได้ถูกทำลายลง และนั่นคือชัยชนะที่ยั่งยืน';

  @override
  String get ssriReferenceDay3 =>
      'การหยุดชะงักของ SSRI: วันแรก\n\nที่มา: สำนักพิมพ์ด้านสุขภาพของฮาร์วาร์ด\n\nหมายเหตุด้านความปลอดภัยที่สำคัญ\nควรหยุด SSRIs ภายใต้การดูแลของแพทย์หลังจากค่อยๆ ลดลงการหยุดอย่างกะทันหัน — โดยเฉพาะหลังการใช้ในระยะยาว — จะทำให้ความรุนแรงของอาการการหยุดยาเพิ่มขึ้นอย่างมาก\n\nSSRI Discontinuation Syndrome คืออะไร?\nกลุ่มอาการหยุดยา SSRI เป็นปรากฏการณ์ทางการแพทย์ที่ได้รับการบันทึกไว้อย่างดี ซึ่งเกิดขึ้นเมื่อ SSRI หยุดหรือลดลงอย่างมากแพทย์ใช้คำย่อ FINISH เพื่ออธิบายอาการที่พบบ่อย:\n• อาการคล้ายไข้หวัดใหญ่ (เหนื่อยล้า เหงื่อออก ปวดกล้ามเนื้อ)\n• นอนไม่หลับและนอนไม่หลับ\n• คลื่นไส้\n• ความไม่สมดุลและเวียนศีรษะ\n• ความผิดปกติทางประสาทสัมผัส — โดยเฉพาะ \'สมองกระตุก\'\n• ตื่นตัวมากเกินไป หงุดหงิด และวิตกกังวล\n\nเรื่องครึ่งชีวิต\nFluoxetine (Prozac) มีครึ่งชีวิตที่ยาวนานมากที่ 4-6 วัน ดังนั้นจึงสามารถละลายได้เองอย่างมีประสิทธิภาพและทำให้เกิดการหยุดยาน้อยลงParoxetine (Paxil) มีครึ่งชีวิตสั้นที่สุดของ SSRIs ทั่วไป และทำให้เกิดอาการหยุดยาที่รุนแรงที่สุดSertraline, citalopram และ escitalopram อยู่ระหว่างนั้น';

  @override
  String get ssriReferenceDay7 =>
      'หนึ่งสัปดาห์หลังจาก SSRIs: ระยะเฉียบพลัน\n\nที่มา: NHS — การหยุดหรือเลิกยาแก้ซึมเศร้า\n\nระยะยุติเฉียบพลัน\nเอกสาร NHS ระบุว่าอาการหยุดยาต้านอาการซึมเศร้าส่วนใหญ่เริ่มภายในห้าวันหลังจากหยุด และในกรณีส่วนใหญ่มักคงอยู่นานถึงหกสัปดาห์ภายในหนึ่งสัปดาห์ อาการทางร่างกายเฉียบพลันมักจะเด่นชัดที่สุด และเริ่มมีแนวโน้มลดลงสำหรับผู้ที่ค่อยๆ ลดลง\n\nสิ่งที่คาดหวังในหนึ่งสัปดาห์\n• อาการทางกาย (คลื่นไส้ เวียนศีรษะ รู้สึกคล้ายไข้หวัดใหญ่) รุนแรงที่สุดแต่น่าจะเริ่มบรรเทาลง\n• ปัญหาการนอนหลับรวมถึงความฝันอันสดใสหรือการนอนไม่หลับเป็นเรื่องปกติ\n• ความบกพร่องทางอารมณ์ — การเปลี่ยนแปลงอารมณ์อย่างรวดเร็ว — เกิดขึ้นบ่อยครั้งในระยะนี้\n• ช่องว่างสมองอาจยังคงอยู่ แต่โดยทั่วไปจะเริ่มความถี่ลดลง\n\nบทบาทของการเรียว\nNHS ขอแนะนำอย่างยิ่งให้ลดขนาดลงอย่างช้าๆ — บางครั้งอาจใช้เวลานานหลายเดือนสำหรับผู้ใช้ระยะยาว — เพื่อลดผลกระทบจากการหยุดใช้งานราชวิทยาลัยจิตแพทย์ได้พัฒนาแนวทางการลดขนาดยาที่แนะนำการลดขนาดยาทีละน้อย โดยมักใช้สูตรของเหลว สำหรับผู้ที่รับประทาน SSRI เป็นเวลานาน';

  @override
  String get ssriReferenceDay14 =>
      'สองสัปดาห์หลังจาก SSRIs: อาการทางกายภาพคลี่คลาย\n\nที่มา: Davies & Read (2019), พฤติกรรมการเสพติด – \'การทบทวนอย่างเป็นระบบเกี่ยวกับอุบัติการณ์ ความรุนแรง และระยะเวลาของผลการถอนยาแก้ซึมเศร้า\'\n\nสิ่งที่การวิจัยพบ\nการทบทวนอย่างเป็นระบบครั้งสำคัญนี้พบว่าประมาณ 56% ของผู้ที่หยุดยาแก้ซึมเศร้ามีอาการถอนยา และ 46% ระบุว่าอาการเหล่านี้รุนแรงสำหรับคนส่วนใหญ่ที่ติดตามความเรียวที่เหมาะสม ระยะเฉียบพลันจะได้รับการแก้ไขเป็นส่วนใหญ่ภายในสองสัปดาห์:\n• ช่องว่างของสมองลดลงหรือหายไปอย่างเห็นได้ชัด\n• อาการคลื่นไส้และอาการคล้ายไข้หวัดใหญ่หายไป\n• อาการวิงเวียนศีรษะและปัญหาเรื่องการทรงตัวดีขึ้น\n• การนอนหลับเริ่มเข้าสู่ภาวะปกติ\n\nแยกแยะความเลิกต่อเนื่องจากการกำเริบของโรค\nอาการที่เกิดขึ้นภายในไม่กี่วันหลังจากหยุดและตรงกับโปรไฟล์ FINISH มักเป็นกลุ่มอาการหยุดชะงักอาการที่เกิดขึ้นหลังจาก 2-4 สัปดาห์และคล้ายกับสภาพเดิมที่กำลังรับการรักษามีแนวโน้มที่จะกลับเป็นอีกมากกว่าการติดตามความแตกต่างนี้กับผู้สั่งจ่ายยาเป็นสิ่งสำคัญ';

  @override
  String get ssriReferenceDay30 =>
      'หนึ่งเดือนหลังจาก SSRIs: การรักษาเสถียรภาพ\n\nที่มา: Haddad PM (2001), ความปลอดภัยของยา - \'กลุ่มอาการหยุดยาต้านอาการซึมเศร้า\'\n\nเฟสการรักษาเสถียรภาพ\nการทบทวนนี้อธิบายการเริ่มหยุดยาอย่างรวดเร็ว โดยทั่วไปภายในไม่กี่วันหลังจากหยุดหรือลดยาแก้ซึมเศร้า และตั้งข้อสังเกตว่าปฏิกิริยาส่วนใหญ่ไม่รุนแรงและเกิดขึ้นไม่นาน โดยสามารถแก้ไขได้โดยไม่ต้องให้การรักษาเฉพาะเจาะจงหนึ่งเดือนแสดงถึงการเปลี่ยนจากช่วงเฉียบพลันไปสู่ความเสถียรสำหรับคนส่วนใหญ่ที่ค่อยๆ ลดลง อาการของการหยุดยาแบบเฉียบพลันจะได้รับการแก้ไขไปมากแล้ว\n\nภูมิทัศน์ทางอารมณ์ในหนึ่งเดือน\nการเปลี่ยนแปลงทางอารมณ์ในหนึ่งเดือนมีความผันแปรและสำคัญที่ต้องติดตาม:\n• บางคนรู้สึก \'ประจบประแจง\' ทางอารมณ์ในช่วงแรกเมื่อสมองปรับตัว ซึ่งโดยทั่วไปจะดีขึ้น\n• คนอื่นๆ ประสบกับความสดใสทางอารมณ์ที่พวกเขาไม่เคยรู้สึกมาหลายปี\n• ระดับความวิตกกังวลจะแตกต่างกันไปตามแต่ละบุคคลและสภาวะแวดล้อม\n\nคุณค่าของการสนับสนุนโดยไม่ใช้ยา\nการวิจัยแสดงให้เห็นอย่างต่อเนื่องว่าการบำบัดด้วยการพูดคุย เช่น CBT (CBT) และการบำบัดทางจิตโดยอาศัยหลักฐานเชิงประจักษ์ other มีประสิทธิภาพสูงสำหรับเงื่อนไขที่ SSRI ปฏิบัติระยะเวลาหนึ่งเดือนเป็นช่วงเวลาที่ดีเยี่ยมเพื่อให้แน่ใจว่าการสนับสนุนเหล่านี้จะเกิดขึ้น';

  @override
  String get ssriReferenceDay90 =>
      'สามเดือนหลังจาก SSRIs: การถอนตัวที่ผ่านมาอย่างดี\n\nที่มา: \"Antidepressant Withdrawal Syndrome\" จดหมายบำบัด 112 (2018) Therapeutics Initiative บนชั้นวางหนังสือ NCBI\n\nที่ซึ่งสามเดือนนั่งอยู่\nการทบทวนหลักฐานนี้ตั้งข้อสังเกตว่าอาการถอนยาต้านอาการซึมเศร้า \'มักจะปรากฏภายในสองสามวันหลังจากหยุดหรือลดขนาดยา\' และ \'อาการถอนยาต้านอาการซึมเศร้าส่วนใหญ่จะหายภายใน 2 สัปดาห์\' แม้ว่ากรณีที่รุนแรงอาจกินเวลาหลายสัปดาห์หรือหลายเดือนก็ตามภายในสามเดือน ระยะการถอนตัวแบบเฉียบพลันยังตามหลังคนส่วนใหญ่ไปมาก\n\nเหตุใด SSRI จึงแตกต่างกันไป\nการถอนยามีแนวโน้มที่จะถอนตัวด้วย SSRIs ครึ่งชีวิตที่สั้นกว่า (เช่น paroxetine) มากกว่าการใช้ยาที่มีครึ่งชีวิตยาว (fluoxetine)จดหมายฉบับนี้ระบุอย่างตรงไปตรงมาว่าปฏิกิริยาการถอนยาอาจมีสาระสำคัญ การทบทวนอย่างเป็นระบบสองครั้งพบว่าปฏิกิริยาดังกล่าว \'คล้ายกันมาก\' กับปฏิกิริยาที่เกิดจากเบนโซไดอะซีพีน และเกิดขึ้นในผู้ที่หยุดยาอย่างน้อยหนึ่งในสาม\n\nสัญญาณการกู้คืนบน \'การกู้คืนตัวรับ\'\nคุณอาจเห็นคำกล่าวอ้างที่มั่นใจว่าตัวรับเซโรโทนิน \'จะรู้สึกไวอีกครั้งภายใน 2-3 เดือน\'หลักฐานที่ชัดเจนเป็นเรื่องเกี่ยวกับกลุ่มอาการถอนยาและจังหวะเวลา ไม่ใช่นาฬิกาฟื้นตัวของตัวรับที่แม่นยำสิ่งที่เชื่อถือได้: ภายในสามเดือนระยะการถอนตัวจะได้รับการแก้ไขโดยทั่วไป และหลายคนสังเกตเห็นผลข้างเคียงทางอารมณ์และทางเพศที่ประสบการณ์บางอย่างเกี่ยวกับ SSRIs จะผ่อนคลายลงหลังจากหยุด\n\nหากอาการยังคงอยู่\nจดหมายแนะนำให้แยกความแตกต่างจากการคืนสภาพที่แท้จริงหากอารมณ์ไม่ดีหรือวิตกกังวลยังคงมีอยู่เป็นเวลาสามเดือน คุณควรตรวจสอบกับผู้สั่งจ่ายยาของคุณ แทนที่จะคิดว่าเป็นเพียง \"การถอนตัว\"';

  @override
  String get ssriReferenceDay180 =>
      'หกเดือนหลังจาก SSRIs: มุมมองที่มีเหตุผล\n\nที่มา: \"Antidepressant Withdrawal Syndrome\" จดหมายบำบัด 112 (2018) Therapeutics Initiative บนชั้นวางหนังสือ NCBI\n\nสิ่งที่เป็นที่ยอมรับภายในหกเดือน\nการทบทวนนี้ตั้งข้อสังเกตว่าแม้แต่อาการถอนยาที่รุนแรงและยาวนาน โดยทั่วไปแล้วจะคงอยู่นานหลายสัปดาห์ถึงหลายเดือน แทนที่จะเป็นอย่างไม่มีกำหนด ดังนั้นภายในหกเดือน อาการถอนยาแบบเฉียบพลันจึงได้รับการแก้ไขอย่างชัดเจนสำหรับคนส่วนใหญ่\n\nมีความซื่อสัตย์เกี่ยวกับส่วนที่เหลือ\nภายในหกเดือน ระยะเวลาการถอนตามปกติจะช้ากว่าคุณไปมาก และระบบเซโรโทนินก็ต้องใช้เวลาหลายเดือนในการชำระหนี้ผลข้างเคียงทางเพศมักจะดีขึ้นหลังจากหยุดหากยังคงมีอยู่ ให้ปรึกษากับผู้สั่งจ่ายยาของคุณ\n\nสิ่งที่ผู้คนมักรายงาน\n• ช่วงทางอารมณ์ที่กว้างขึ้นเมื่อเทียบกับการใช้ยา\n• ปรับปรุงการนอนหลับและพลังงานให้มากที่สุด\n• การปรับปรุงอย่างค่อยเป็นค่อยไปอย่างต่อเนื่อง แม้ว่าอัตราการก้าวจะแตกต่างกันอย่างมากระหว่างแต่ละบุคคล';

  @override
  String get ssriReferenceDay365 =>
      'หนึ่งปีหลังจาก SSRIs: การฟื้นตัวที่วัดได้\n\nที่มา: ดัฟฟี่ และคณะ(2021) การประเมินเทคโนโลยีสุขภาพ — การทดลอง ANTLER\n\nสิ่งที่การทดลองนี้พบจริง\nANTLER ติดตามผู้ใช้ยาต้านอาการซึมเศร้าในระยะยาวในการดูแลเบื้องต้นของสหราชอาณาจักร ผู้ที่ยังคงใช้ยาหรือหยุดยาไปแล้วในปีต่อมา 56% ของผู้ที่หยุดการกำเริบของโรค เทียบกับ 39% ของผู้ที่ยังคงใช้ยา ซึ่งมีความเสี่ยงเพิ่มขึ้นเป็นสองเท่า และกลุ่มที่เลิกยารายงานว่าคุณภาพชีวิตโดยเฉลี่ยค่อนข้างต่ำลง\n\nรูปภาพฟูลเลอร์\nแม้จะมีอัตราการกำเริบของโรคที่สูงขึ้น แต่ผู้คนจำนวนมากที่หยุดยาไม่กลับเป็นซ้ำและยังคงสบายดีโดยไม่ต้องใช้ยาประมาณหนึ่งในสามของผู้ที่หยุดยาในที่สุดก็เริ่มใช้ยาแก้ซึมเศร้าอีกครั้ง ซึ่งเป็นทางเลือกทางคลินิกที่สมเหตุสมผล ไม่ใช่ความล้มเหลว\n\nหมายเหตุเกี่ยวกับอนาคต\nอาการซึมเศร้าและวิตกกังวลเป็นภาวะเรื้อรังสำหรับบางคนไม่มีความล้มเหลวในการกลับไปใช้ยาหากอาการที่เป็นอยู่ยืนยันตัวเองอีกครั้งเป้าหมายคือความเป็นอยู่ที่ดี และหนึ่งปีของการหยุดยาที่ประสบความสำเร็จนั้นถือเป็นความสำเร็จที่แท้จริงไม่ว่าจะเกิดอะไรขึ้นต่อไป';

  @override
  String get steroidsReferenceDay1 =>
      'การหยุดสเตียรอยด์อะนาโบลิก: วันแรก\n\nที่มา: \"อาการทั่วไปที่เกี่ยวข้องกับการใช้และการเลิกใช้สเตียรอยด์อะนาโบลิกแอนโดรเจนในผู้ชาย\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nระยะเฉียบพลัน\nการตรวจสอบนี้อธิบายถึงการถอน AAS โดยแบ่งเป็นสองขั้นตอนวิธีแรกซึ่งขับเคลื่อนโดยการกระตุ้นระบบประสาทซิมพาเทติกมากกว่าระดับฮอร์โมน จะปรากฏขึ้นภายใน 1-2 วันหลังจากหยุดและอาจรวมถึง:\n• ปวดหัว\n• อาการสั่น\n• ใจสั่น\n• คลื่นไส้\n\nเหตุใดจึงเกิดอาการ\nอะนาโบลิกสเตียรอยด์ยังระงับการผลิตฮอร์โมนเทสโทสเทอโรนของร่างกายด้วย สมองจะตรวจจับสเตียรอยด์และปิดสัญญาณฮอร์โมนที่ปกติขับเคลื่อนฮอร์โมนนั้นการปราบปรามนั้นยังคงมีอยู่หลังจากการหยุด โดยเป็นการกำหนดระยะที่สองของการถอนตัวที่ยาวนานกว่าซึ่งอธิบายไว้ในเหตุการณ์สำคัญในภายหลัง\n\nหมายเหตุด้านความปลอดภัย\nอาการซึมเศร้าอาจเกิดขึ้นได้ในระหว่างการถอนสเตียรอยด์และกลายเป็นเรื่องร้ายแรงแสวงหาการรักษาพยาบาล และความช่วยเหลืออย่างเร่งด่วนสำหรับความคิดที่จะทำร้ายตนเองแพทย์มักจะแนะนำการฟื้นตัวบางคนใช้ยาเพื่อสนับสนุน';

  @override
  String get steroidsReferenceDay14 =>
      'สองสัปดาห์ปิดสเตียรอยด์อะนาโบลิก\n\nที่มา: \"อาการทั่วไปที่เกี่ยวข้องกับการใช้และการเลิกใช้สเตียรอยด์อะนาโบลิกแอนโดรเจนในผู้ชาย\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nระยะเรื้อรังเริ่มต้นขึ้น\nภายในสองสัปดาห์ อาการแสดงความเห็นอกเห็นใจสั้นๆ ในวันแรกๆ มักจะผ่านไปแล้ว และระยะที่สองของการทบทวน ซึ่งได้รับแรงหนุนจากการขาดฮอร์โมนเทสโทสเทอโรนอย่างต่อเนื่อง จะมีความโดดเด่นมากขึ้น:\n• เหนื่อยล้าและอารมณ์ไม่ดี\n• ปวดกล้ามเนื้อ (ปวดกล้ามเนื้อ)\n• ความใคร่ลดลง\n• นอนไม่หลับและอยากอาหาร\n\nยังอยู่ที่ Low Ebb\nการผลิตฮอร์โมนเทสโทสเตอโรนตามธรรมชาติใช้เวลานานกว่าสองสัปดาห์ในการรีเซ็ต ดังนั้นจึงเป็นที่คาดหวังในระยะนี้ ไม่ใช่สัญญาณว่ามีบางอย่างผิดปกติ\n\nกับดักที่รู้จัก\nผู้ชายบางคนกลับมาใช้โดยเฉพาะเพื่อหลีกหนีช่องว่างนี้ ซึ่งเป็นวงจรที่รีเซ็ตนาฬิกาฟื้นตัวแทนที่จะหยุดมันการสนับสนุนจากแพทย์หรือที่ปรึกษาช่วยลดระยะนี้แทนที่จะใช้ยาสเตียรอยด์มากขึ้น';

  @override
  String get steroidsReferenceDay30 =>
      'ลดหนึ่งเดือนสำหรับอะนาโบลิกสเตียรอยด์\n\nที่มา: \"การฟื้นตัวทางกายภาพ จิตวิทยา และชีวเคมีจากภาวะ hypogonadism ที่เกิดจากอะนาโบลิกสเตียรอยด์: การทบทวนการกำหนดขอบเขต\" บน PubMed\n\nการกู้คืนเริ่มต้นขึ้น\nหลังจากหยุดแล้ว ฮอร์โมนจะส่งสัญญาณที่บอกให้อัณฑะสร้างฮอร์โมนเทสโทสเตอโรนอีกครั้งการวิจัยทำให้การฟื้นตัวส่วนใหญ่อยู่ในช่วงสามถึงหกเดือน ดังนั้นภายในหนึ่งเดือน กระบวนการจึงกำลังดำเนินการอยู่\n\nสิ่งที่คาดหวัง\nอารมณ์ ความใคร่ และพลังงานต่ำมักยังคงอยู่ในขณะที่ฮอร์โมนกลับมาอีกครั้งการฟื้นตัวขึ้นอยู่กับอายุ การใช้งานหนักแค่ไหน และยาวนานแค่ไหน';

  @override
  String get steroidsReferenceDay90 =>
      'สามเดือนจากสเตียรอยด์อะนาโบลิก\n\nที่มา: \"การฟื้นตัวทางกายภาพ จิตวิทยา และชีวเคมีจากภาวะ hypogonadism ที่เกิดจากอะนาโบลิกสเตียรอยด์: การทบทวนการกำหนดขอบเขต\" บน PubMed\n\nช่วงเวลาที่ดีสำหรับการตรวจเลือด\nเมื่อผ่านไปสามเดือน ระบบฮอร์โมนก็ถึงเวลาที่จะแสดงการฟื้นตัวอย่างมีความหมายนี่เป็นจุดที่มีประโยชน์ในการขอให้แพทย์ตรวจฮอร์โมนเทสโทสเทอโรนและฮอร์โมนที่ควบคุมฮอร์โมนเพศชาย\n\nสิ่งที่คาดหวัง\nสำหรับผู้ชายหลายๆ คนในช่วง 3 เดือน ระดับกำลังเพิ่มขึ้นแต่ยังไม่เป็นปกติอย่างสมบูรณ์อารมณ์และความใคร่มักจะดีขึ้นก่อนที่ฮอร์โมนเพศชายจะตามทันขนาดอัณฑะและการผลิตอสุจิจะฟื้นตัวช้ากว่าและสามารถปรับปรุงได้ในปีต่อไปการเจริญเติบโตของเนื้อเยื่อเต้านม (gynaecomastia) ที่เกิดขึ้นนั้นไม่น่าจะหายไปได้หากไม่มีการรักษาเฉพาะทาง';

  @override
  String get steroidsReferenceDay180 =>
      'หกเดือนจากสเตียรอยด์อะนาโบลิก\n\nที่มา: \"การฟื้นตัวทางกายภาพ จิตวิทยา และชีวเคมีจากภาวะ hypogonadism ที่เกิดจากอะนาโบลิกสเตียรอยด์: การทบทวนการกำหนดขอบเขต\" บน PubMed\n\nหลักฐานชี้อยู่ที่ไหน\nการทบทวนรายงานว่า LH และ FSH ซึ่งเป็นฮอร์โมนที่สั่งให้อัณฑะสร้างฮอร์โมนเพศชาย มักจะฟื้นตัวภายในประมาณสามถึงหกเดือนเมื่อถึงหกเดือน ฮอร์โมนเทสโทสเทอโรนเองก็อยู่ในเส้นทางการฟื้นตัวเช่นกัน\n\nหากคุณยังไม่อยู่ที่นั่น\nหากอาการฮอร์โมนเทสโทสเตอโรนต่ำยังคงอยู่ในช่วงหกเดือน แพทย์ด้านต่อมไร้ท่อสามารถตรวจสอบสิ่งที่เกิดขึ้นและหารือเกี่ยวกับการรักษา แทนที่จะปล่อยให้คุณรอ';

  @override
  String get steroidsReferenceDay365 =>
      'หนึ่งปีปิดสเตียรอยด์อะนาโบลิก\n\nที่มา: \"ภาวะ hypogonadism ที่เกิดจากสเตียรอยด์ที่เกิดจากอะนาโบลิกแอนโดรเจน ซึ่งเป็นภาวะที่สามารถย้อนกลับได้ในผู้ชาย? การทบทวนอย่างเป็นระบบ\" บน PubMed\n\nฟรีหนึ่งปี\nการหยุดงานหนึ่งปีจะทำให้ระบบฮอร์โมนฟื้นตัวได้ยาวนานฮอร์โมนเทสโทสเตอโรน อารมณ์ ความใคร่ ความแข็งแกร่งตามธรรมชาติ และสุขภาพของหัวใจ ล้วนมีเวลาฟื้นตัวอย่างมาก\n\nรูปภาพระยะยาว\nหากยังคงมีอาการฮอร์โมนเทสโทสเทอโรนต่ำในหนึ่งปี การประเมินฮอร์โมนโดยผู้เชี่ยวชาญคือขั้นตอนถัดไปที่เหมาะสมการไม่ใช้สเตียรอยด์จะช่วยปกป้องการฟื้นตัวที่เกิดขึ้นแล้ว';

  @override
  String get steroidsReferenceDay730 =>
      'สองปีจากสเตียรอยด์อะนาโบลิก\n\nที่มา: \"ภาวะ hypogonadism ที่เกิดจากสเตียรอยด์ที่เกิดจากอะนาโบลิกแอนโดรเจน ซึ่งเป็นภาวะที่สามารถย้อนกลับได้ในผู้ชาย? การทบทวนอย่างเป็นระบบ\" บน PubMed\n\nความปกติใหม่\nภายในสองปี ระดับฮอร์โมนของคุณจะสะท้อนถึงการผลิตตามธรรมชาติของร่างกายสำหรับผู้ชายส่วนใหญ่ที่ฟื้นตัวได้ อารมณ์ ความใคร่ ความแข็งแกร่ง และแรงจูงใจจะคงที่โดยไม่ต้องใช้สเตียรอยด์\n\nการฟื้นฟูฮอร์โมนในระยะยาว\nการวิจัยแสดงให้เห็นว่าฮอร์โมนเทสโทสเตอโรนฟื้นตัวภายในเวลาหลายเดือน ในขณะที่ฮอร์โมนที่ส่งสัญญาณให้อัณฑะมักจะฟื้นตัวภายในสามถึงหกเดือนขนาดของลูกอัณฑะ การผลิตสเปิร์ม และความใคร่สามารถปรับปรุงได้อย่างต่อเนื่องเป็นเวลาหลายเดือนหรือหลายปีเมื่อถึงสองปี อาการของฮอร์โมนเทสโทสเตอโรนต่ำอย่างต่อเนื่องเป็นของผู้เชี่ยวชาญ ไม่ใช่รอบของสเตียรอยด์';

  @override
  String get tcaReferenceDay3 =>
      'การหยุด TCA: วันแรก — Acetylcholine Rebound\n\nที่มา: Dilsaver, Feinberg & Greden (1983), American Journal of Psychiatry — \'อาการถอนยาต้านอาการซึมเศร้าที่รับการรักษาด้วยยาต้านโคลิเนอร์จิค\' (รายงานผู้ป่วย ผู้ป่วย 3 ราย)\n\nอะไรที่ทำให้การยุติ TCA แตกต่างออกไป\nยาต้านอาการซึมเศร้าแบบ Tricyclic มีความแตกต่างโดยพื้นฐานจาก SSRIs และ SNRIs ในกลไกของมันนอกจากจะปิดกั้นการดูดซึมเซโรโทนินและนอร์เอพิเนฟรินแล้ว TCA ยังปิดกั้นระบบอะเซทิลโคลีนของร่างกายอีกด้วยเมื่อคุณหยุด ระบบนั้นจะเด้งกลับ\n\nอาการฟื้นตัวของ Acetylcholine\nซึ่งแตกต่างจากการหยุด SSRI การถอน TCA ทำให้เกิดการฟื้นตัวของ acetylcholine:\n• คลื่นไส้ อาเจียน และท้องร่วง\n• น้ำลายไหลและเหงื่อออกมากเกินไป\n• ปวดศีรษะและปวดกล้ามเนื้อ\n• นอนไม่หลับพร้อมกับฝันที่สดใสหรือรบกวนจิตใจ\n• ความวิตกกังวลและกระสับกระส่าย\n\nTCA ทั่วไปและโปรไฟล์ของพวกเขา\nอะมิทริปไทลีนและอิมิพรามีนมีฤทธิ์ในการบล็อกอะซิติลโคลีนที่แข็งแกร่งที่สุด และมักจะทำให้เกิดการเด้งกลับที่เด่นชัดที่สุดNortriptyline มีผลค่อนข้างรุนแรงกว่าClomipramine ยังมีผลกระทบที่เกี่ยวข้องกับเซโรโทนินอย่างมีนัยสำคัญควบคู่ไปกับโปรไฟล์การปิดกั้นอะซิติลโคลีน';

  @override
  String get tcaReferenceDay7 =>
      'หนึ่งสัปดาห์หลังจาก TCAs: อาการ Acetylcholine บรรเทาลง\n\nการกู้คืน Acetylcholine\nโดยทั่วไปการฟื้นตัวของอะซิติลโคลีนจะถึงจุดสูงสุดภายในสองสามวันแรก และเริ่มผ่อนคลายลงอย่างมากภายในหนึ่งสัปดาห์เมื่อระบบอะเซทิลโคลีนกลับสู่ระดับธรรมชาติ:\n\nอะไรกำลังปรับปรุง\n• อาการทางระบบทางเดินอาหาร (คลื่นไส้ ตะคริว ท้องร่วง) จะลดลง\n• อาการเหงื่อออกและคล้ายไข้หวัดใหญ่คลี่คลายลง\n• การนอนหลับแม้จะยังถูกรบกวนอยู่ แต่ก็เริ่มที่จะทรงตัวแล้ว\n• อาการน้ำลายไหลมากเกินไปกำลังแก้ไข\n\nระบบประสาทอัตโนมัติของร่างกาย\nTCA ส่งผลต่อการทำงานอัตโนมัติของร่างกาย — อัตราการเต้นของหัวใจ ความดันโลหิต การย่อยอาหาร — ผ่านกลไกต่างๆภายในหนึ่งสัปดาห์ อาการของร่างกายโดยอัตโนมัติที่รุนแรงที่สุด รวมถึงอาการวิงเวียนศีรษะเมื่อยืนและการเปลี่ยนแปลงอัตราการเต้นของหัวใจอย่างรวดเร็ว จะเริ่มหายไปเมื่อระบบประสาทปรับใหม่';

  @override
  String get tcaReferenceDay14 =>
      'สองสัปดาห์หลังจาก TCAs: การย้อนกลับของผล Antiacetylcholine\n\nการยกภาระ Antiacetylcholine\nTCAs ก่อให้เกิดผลการปิดกั้นอะเซทิลโคลีนอย่างมีนัยสำคัญต่อร่างกายซึ่งส่งผลต่อระบบต่างๆเมื่อภาระนี้เพิ่มขึ้นในช่วงสองสัปดาห์แรก:\n\nประโยชน์ทางกายภาพ\n• แก้ปัญหาปากแห้ง — การทำงานของต่อมน้ำลายกลับมาเป็นปกติ\n• แก้อาการท้องผูก — การเคลื่อนไหวของลำไส้กลับคืนมาตามธรรมชาติ\n• การทำให้การทำงานของปัสสาวะเป็นปกติ — การกักเก็บปัสสาวะที่ TCA สามารถทำได้กำลังได้รับการแก้ไข\n• การมองเห็นไม่ชัดชัดเจน — ดวงตาปรับตามปกติเพื่อรับแสงอีกครั้ง\n\nประโยชน์ของการคิดและความจำ\nอะเซทิลโคลีนจำเป็นต่อความจำ ความสนใจ และการเรียนรู้วิถีทางอะเซทิลโคลีนที่ถูกยับยั้งโดย TCA กำลังฟื้นตัว:\n• การปรับปรุงหน่วยความจำในการทำงาน\n• ความเร็วในการประมวลผลเพิ่มขึ้น\n• จิตแจ่มใสกลับมา\n\nหลายๆ คนรู้สึกประหลาดใจกับปัญหาหมอกในสมองและความจำที่พวกเขาต้องปรับตัวขณะรับประทาน TCA';

  @override
  String get tcaReferenceDay30 =>
      'หนึ่งเดือนหลังจาก TCAs: ระบบประสาทอัตโนมัติของร่างกายมีเสถียรภาพ\n\nการฟื้นฟูหัวใจ\nTCA ส่งผลต่อจังหวะการเต้นของหัวใจระหว่างการใช้งานโดยออกฤทธิ์ต่อระบบประสาทที่เกี่ยวข้องกับอะซิติลโคลีนและอะดรีนาลีนเอกสารทางคลินิกเกี่ยวกับการหยุดใช้ TCA ยืนยันว่าอาการถอนยาเฉียบพลัน รวมถึงผลกระทบต่อร่างกายโดยอัตโนมัติซึ่งเกิดจาก \'อะซิติลโคลีนและอะดรีนาลีนเกินขนาด\' โดยทั่วไปจะไม่รุนแรงและหายไปภายในหนึ่งถึงสองสัปดาห์หลังจากหยุดภายในหนึ่งเดือน คนส่วนใหญ่จะผ่านกรอบเวลาเฉียบพลันนี้ไปได้ และคาดหวังได้ว่า:\n• จังหวะการเต้นของหัวใจกลับสู่ระดับเริ่มต้นก่อนใช้ยา\n• ความแปรปรวนของอัตราการเต้นของหัวใจมีแนวโน้มไปสู่ระดับธรรมชาติ\n• การควบคุมความดันโลหิต ซึ่งก่อนหน้านี้ได้รับผลกระทบจากการออกฤทธิ์ของยาต่อวิถีอะดรีนาลีน ยังคงมีเสถียรภาพต่อไป\n\nการฟื้นฟูสถาปัตยกรรมการนอนหลับ\nTCAs ระงับการนอนหลับในฝันอย่างรุนแรงเมื่อฤทธิ์ต้านอะซิติลโคลีนหมดฤทธิ์ (จำเป็นต้องใช้อะซิติลโคลีนในการนอนหลับฝัน):\n• การนอนหลับแบบ REM กำลังกลับมา มักจะทำให้เกิดความฝันอันสดใสในขณะที่การนอนหลับฝันกลับมา\n• การนอนหลับแบบคลื่นช้า (ลึก) กำลังดีขึ้น\n• คุณภาพการนอนหลับโดยรวมและการฟื้นฟูดีกว่าระหว่างการใช้ TCA อย่างเห็นได้ชัด';

  @override
  String get tcaReferenceDay90 =>
      'สามเดือนหลังจาก TCA: ทิ้งความเสี่ยงที่แท้จริงไว้เบื้องหลัง\n\nสิ่งที่แสดงหลักฐาน\nการวิเคราะห์เมตาในปี 2024 ของการทดลองแบบสุ่ม 103 รายการ (ผู้เข้าร่วม 10,590 คน) พบว่าเมื่อเปรียบเทียบกับยาหลอก TCA สามารถลดอาการซึมเศร้าได้ แต่ยังมาพร้อมกับโอกาสที่จะเกิดเหตุการณ์ไม่พึงประสงค์ร้ายแรงเกือบสามเท่า (odds ratio 2.78)การทดลองติดตามผู้ป่วยในระหว่างการรักษานานถึง 12 สัปดาห์เท่านั้น ดังนั้นจึงไม่มีข้อมูลระยะยาวที่ได้รับการควบคุมเกี่ยวกับสิ่งที่เกิดขึ้นหลังจากการหยุดยาข้อมูลด้านล่างนี้สะท้อนถึงความเข้าใจทางคลินิกทั่วไปเกี่ยวกับเภสัชวิทยาของ TCA ไม่ใช่การค้นพบเฉพาะจากหลักฐานการทดลองนี้\n\nการกู้คืนหลายระบบ\nTCA ส่งผลต่อระบบเคมีในสมองในวงกว้างมากกว่า SSRI หรือ SNRI:\n• ระบบเซโรโทนิน : ปรับระดับได้\n• ระบบ Noradrenaline : ปรับ\n• ระบบ Acetylcholine : กลับเข้าสู่ภาวะปกติ\n• ระบบฮิสตามีน: ยาระงับประสาทคล้ายแอนติฮิสตามีนได้รับการแก้ไขแล้ว\n\nในสามเดือน ระบบทั้งหมดเหล่านี้มีเวลามากในการฟื้นตัว และที่สำคัญไม่แพ้กันคือ ความเสี่ยงต่อเหตุการณ์ไม่พึงประสงค์ร้ายแรงที่เพิ่มขึ้นที่มาพร้อมกับการรักษาด้วย TCA ที่ออกฤทธิ์อยู่ข้างหลังคุณแล้วหลายคนสังเกตเห็น:\n• ปรับปรุงการคิดที่ชัดเจน — โดยเฉพาะความจำและความสนใจ\n• ความมั่นคงทางอารมณ์ดีขึ้น\n• ปรับปรุงพลังงานและแรงจูงใจ\n• ลดความใจเย็นและความตื่นตัวที่ดีขึ้น';

  @override
  String get tcaReferenceDay180 =>
      'หกเดือนหลังจาก TCA: การฟื้นฟูหัวใจและการคิด\n\nสัญญาณการกู้คืนข้อมูลระยะยาว\nระยะเวลาการถอนตัวก่อนกำหนดหลังจาก TCA มักจะไม่รุนแรงและหายไปภายในหนึ่งถึงสองสัปดาห์ภายในหกเดือนหลังจากการลดลงภายใต้การดูแล อัตราการเต้นของหัวใจ ความทรงจำ และผลกระทบของ TCA ต้องใช้เวลาหลายเดือนในการฟื้นตัว\n\nการฟื้นฟูหัวใจและหลอดเลือด\nภายในหกเดือน ผลกระทบโดยตรงของ TCA ต่อจังหวะการเต้นของหัวใจควรได้รับการแก้ไขในระยะยาว:\n• รักษาจังหวะการเต้นของหัวใจให้เป็นปกติโดยไม่มีอิทธิพลจากยา\n• ความแปรปรวนของอัตราการเต้นของหัวใจ (การวัดว่าหัวใจของคุณปรับตัวได้ดีแค่ไหน) คาดว่าจะดีขึ้นอย่างมาก\n• อาการวิงเวียนศีรษะเมื่อยืนคลี่คลายเต็มที่\n\nการคิดและการฟื้นฟูความจำ\nTCA อาจทำให้เกิดหมอกในสมองและปัญหาความจำได้โดยการปิดกั้นอะเซทิลโคลีน โดยเฉพาะในผู้สูงอายุผลเหล่านี้จะดีขึ้นหลังจากหยุดยาเมื่อหกเดือน:\n• การรวมหน่วยความจำได้รับการปรับปรุงอย่างมาก\n• ความเร็วในการประมวลผลเป็นมาตรฐาน\n• การวางแผน หน่วยความจำในการทำงาน และความสามารถในการสลับระหว่างงานหรือแนวคิดต่างๆ ได้รับการฟื้นฟูอย่างมีความหมาย';

  @override
  String get tcaReferenceDay365 =>
      'หนึ่งปีหลังจาก TCA: ฟื้นตัวได้สำเร็จ\n\nหนึ่งปี: การกู้คืนระบบหลายระบบเสร็จสมบูรณ์\nการทบทวนกลุ่มอาการหยุดยาต้านอาการซึมเศร้านี้ ครอบคลุม TCAs, MAOIs, SSRIs และอื่นๆ พบว่าอาการถอนยามักเริ่มภายในไม่กี่วันหลังจากหยุด และหากปล่อยทิ้งไว้โดยไม่ได้รับการรักษา จะหายได้เองภายในไม่กี่วันถึงสองสามสัปดาห์ไม่มีการศึกษาใดที่วัดผลระบบที่ได้รับผลกระทบจาก TCA โดยเฉพาะอีกครั้งในหนึ่งปี แต่หนึ่งปีหลังจากเสร็จสิ้นการเรียวนั้นก็เกินกว่าอาการหยุดยาที่รายงานมายาวนานที่สุดหลายเดือน ดังนั้นระบบเคมีในสมองที่ได้รับผลกระทบทั้งหมด เช่น เซโรโทนิน นอร์อะดรีนาลีน อะเซทิลโคลีน และฮิสตามีน คาดว่าจะมีวงจรที่สมบูรณ์เพื่อทำให้เป็นปกติ\n\nความสำคัญของการกู้คืน TCA\nTCAs กำหนดภาระจากยาที่ขับเคลื่อนด้วยยาในวงกว้างมากกว่ายาแก้ซึมเศร้ารุ่นใหม่ ซึ่งส่งผลต่อระบบตัวรับมากขึ้นพร้อมๆ กันการหยุดทำงานที่ประสบความสำเร็จหมายถึงการกู้คืนระบบต่างๆ:\n• การกลับรายการของความจำและการคิดบกพร่องโดยสมบูรณ์ที่เกิดจากการปิดกั้นอะเซทิลโคลีนของ TCA\n• ฟื้นตัวเต็มที่\n• การควบคุมสารเคมีในสมองตามธรรมชาติได้รับการฟื้นฟูในทุกวิถีทางที่ได้รับผลกระทบ\n\nหนึ่งปีแห่งความสำเร็จในการควบคุมตนเองหลังจากการเลิกใช้ TCA ถือเป็นความสำเร็จที่แท้จริง ทั้งในด้านการจัดการกระบวนการเลิกยา และในการคงไว้ซึ่งความเป็นอยู่ที่ดีโดยไม่ได้รับการสนับสนุนจากยา';

